def bootstrap_bundled_runtime():
    if getattr(sys, "frozen", False):
        return   # a packaged build carries its own runtime
    script_path = Path(__file__).resolve()
    project_root = script_path.parent.parent if script_path.parent.name.lower() == "outputs" else script_path.parent
    bundled_python = project_root / "work" / "build_env" / "Scripts" / ("pythonw.exe" if os.name == "nt" else "python")
    if os.environ.get("DISTANT_VIEWER_BOOTSTRAPPED") or not bundled_python.exists():
        return
    try:
        if Path(sys.executable).resolve() == bundled_python.resolve():
            return
    except OSError:
        pass
    missing_runtime = any(importlib.util.find_spec(module) is None for module in ("PySide6", "PIL"))
    if not missing_runtime:
        return
    env = os.environ.copy()
    env["DISTANT_VIEWER_BOOTSTRAPPED"] = "1"
    subprocess.Popen([str(bundled_python), str(script_path), *sys.argv[1:]], cwd=str(project_root), env=env)
    sys.exit(0)


bootstrap_bundled_runtime()

