# --------------------------------------------------------------------------
# Resource policy
#
# UNRESTRICTED_RESOURCES is the switch the user asked for: take whatever the
# machine has, do not hold back for anything else running. With it on:
#
#   * Local pools always open at their full ceiling instead of being scaled down
#     by how busy the rest of the machine is.
#   * Pool threads run at normal priority, competing on equal terms with every
#     other program rather than deliberately losing to them.
#
# Setting it to False restores the previous polite behaviour in one line: pools
# narrow as other processes get busy (measured with our own CPU time subtracted,
# so a big local job never throttles itself), and bulk threads drop below normal
# priority so they yield instantly to the UI and to other applications. Worth
# flipping back if the machine ever feels sluggish while a big job runs.
#
# Unaffected either way: anything that talks to a booru. Those limits exist to be
# polite to someone else's server, not to ration this machine, and the sites
# punish extra concurrency with failures rather than rewarding it with speed
# (see REALBOORU_PARALLEL_SAVE_LIMIT above). Same for CV2_VIDEO_DECODE_LOCK,
# which prevents a native crash rather than saving CPU.
UNRESTRICTED_RESOURCES = True
LOCAL_WORKER_FLOOR = 2
LOCAL_WORKER_CEILING = max(4, _CPU_COUNT * 2)
DECODE_WORKER_CEILING = max(2, _CPU_COUNT)
# Pools whose work is reading files off the library drive (thumbnails,
# duplicate hashing, thumbnail repair). Measured on the user's library drive:
# 6 threads build thumbnails as fast as 24 (the drive is the limit, ~60/s), but
# 24 queued reads made every other disk access wait behind them - a stat plus
# two renames went from 1.5ms to 5ms typical and ~1s worst, which is what
# turned moves and view switches into freezes while thumbnails were building.
DISK_WORKER_CEILING = max(2, min(6, _CPU_COUNT))
# Below this much free RAM, stop growing caches and pools regardless of CPU.
LOW_MEMORY_HEADROOM_BYTES = 1536 * 1024 * 1024

THREAD_PRIORITY_BELOW_NORMAL = -1
_RESOURCE_LOCK = threading.Lock()
_CPU_SAMPLE = {"time": 0.0, "idle": 0, "total": 0, "process": 0, "headroom": 1.0}


class MEMORYSTATUSEX(ctypes.Structure):
    _fields_ = [
        ("dwLength", wintypes.DWORD),
        ("dwMemoryLoad", wintypes.DWORD),
        ("ullTotalPhys", ctypes.c_ulonglong),
        ("ullAvailPhys", ctypes.c_ulonglong),
        ("ullTotalPageFile", ctypes.c_ulonglong),
        ("ullAvailPageFile", ctypes.c_ulonglong),
        ("ullTotalVirtual", ctypes.c_ulonglong),
        ("ullAvailVirtual", ctypes.c_ulonglong),
        ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
    ]


def available_memory_bytes() -> int:
    """Free physical RAM. 0 when it cannot be determined, which every caller
    treats as "assume tight" rather than "assume unlimited"."""
    if os.name != "nt":
        return 0
    try:
        status = MEMORYSTATUSEX()
        status.dwLength = ctypes.sizeof(status)
        if not ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
            return 0
        return int(status.ullAvailPhys)
    except (AttributeError, OSError):
        return 0


def _read_cpu_counters() -> tuple[int, int, int]:
    """(idle, total, this process) CPU time in 100ns units, summed over all cores."""
    kernel = ctypes.windll.kernel32

    def as_int(value) -> int:
        return (value.dwHighDateTime << 32) | value.dwLowDateTime

    idle_t, kernel_t, user_t = wintypes.FILETIME(), wintypes.FILETIME(), wintypes.FILETIME()
    if not kernel.GetSystemTimes(ctypes.byref(idle_t), ctypes.byref(kernel_t), ctypes.byref(user_t)):
        raise OSError("GetSystemTimes failed")
    idle = as_int(idle_t)
    # Kernel time already includes idle time, so kernel + user is the true total.
    total = as_int(kernel_t) + as_int(user_t)
    creation, exit_time, proc_kernel, proc_user = (wintypes.FILETIME() for _ in range(4))
    process = 0
    if kernel.GetProcessTimes(
        kernel.GetCurrentProcess(),
        ctypes.byref(creation), ctypes.byref(exit_time),
        ctypes.byref(proc_kernel), ctypes.byref(proc_user),
    ):
        process = as_int(proc_kernel) + as_int(proc_user)
    return idle, total, process


def system_cpu_headroom() -> float:
    """How much of the machine is free once *other* programs are accounted for,
    as 0.0-1.0. Our own CPU time is subtracted, so a big local job does not read
    as contention and throttle itself. Sampled at most once a second."""
    if os.name != "nt":
        return 1.0
    now = time.monotonic()
    with _RESOURCE_LOCK:
        if _CPU_SAMPLE["time"] and now - _CPU_SAMPLE["time"] < 1.0:
            return _CPU_SAMPLE["headroom"]
        try:
            idle, total, process = _read_cpu_counters()
        except (AttributeError, OSError):
            return _CPU_SAMPLE["headroom"]
        if _CPU_SAMPLE["time"]:
            delta_total = total - _CPU_SAMPLE["total"]
            delta_idle = idle - _CPU_SAMPLE["idle"]
            delta_process = process - _CPU_SAMPLE["process"]
            if delta_total > 0:
                foreign_busy = max(0, (delta_total - delta_idle) - delta_process)
                _CPU_SAMPLE["headroom"] = max(0.0, min(1.0, 1.0 - foreign_busy / delta_total))
        _CPU_SAMPLE.update({"time": now, "idle": idle, "total": total, "process": process})
        return _CPU_SAMPLE["headroom"]


def local_worker_budget(ceiling: int = LOCAL_WORKER_CEILING, floor: int = LOCAL_WORKER_FLOOR) -> int:
    """How many threads to give a *local* (CPU/disk) pool right now."""
    ceiling = max(1, int(ceiling))
    floor = max(1, min(int(floor), ceiling))
    memory = available_memory_bytes()
    if memory and memory < LOW_MEMORY_HEADROOM_BYTES:
        # The one guard kept even when unrestricted, because it is not a
        # throttle: each extra worker holds another decoded frame in memory, so
        # piling them on when RAM is nearly gone makes the job slower, not
        # faster, and risks taking the machine down with it.
        return max(floor, ceiling // 2)
    if UNRESTRICTED_RESOURCES:
        return ceiling
    return max(floor, min(ceiling, int(round(floor + (ceiling - floor) * system_cpu_headroom()))))


_GALLERY_ICON_LIMIT_CACHE = [0.0, 0]


def gallery_icon_cache_limit() -> int:
    """compute_gallery_icon_cache_limit(), re-measured at most every 2s.

    It is checked after every icon insert, and the free-RAM query behind it
    was showing up as a steady cost while thumbnails arrived."""
    now = time.monotonic()
    checked_at, limit = _GALLERY_ICON_LIMIT_CACHE
    if limit and now - checked_at < 2.0:
        return limit
    limit = compute_gallery_icon_cache_limit()
    _GALLERY_ICON_LIMIT_CACHE[0], _GALLERY_ICON_LIMIT_CACHE[1] = now, limit
    return limit


def compute_gallery_icon_cache_limit() -> int:
    """Bound the decoded-icon cache by real free RAM instead of one hardcoded
    guess. The viewport-only decoding in populate_gallery/
    refresh_visible_gallery_icons is what actually prevents the old
    double-digit-gigabyte ramp; this only decides how many already-decoded icons
    are worth keeping, so it can grow when the machine has room to spare."""
    memory = available_memory_bytes()
    if not memory:
        return GALLERY_ICON_CACHE_LIMIT
    # A cached icon is roughly a 256x256 32-bit pixmap (~256KB). Spend at most a
    # twentieth of what is free, and never dip below the old fixed limit.
    budget = int(memory * 0.05) // (256 * 1024)
    return max(GALLERY_ICON_CACHE_LIMIT, min(8000, budget))


def lower_current_thread_priority() -> bool:
    """Drop the calling thread below normal priority. Used as the pool
    `initializer` for local bulk work so those threads always lose to the UI and
    to other applications.

    The argtypes matter: GetCurrentThread() returns the pseudo-handle (HANDLE)-2,
    and without declaring HANDLE it comes back through ctypes' default c_int and
    is truncated on 64-bit Windows, so SetThreadPriority silently fails on an
    invalid handle and every thread quietly stays at normal priority."""
    if os.name != "nt":
        return False
    try:
        kernel = ctypes.windll.kernel32
        kernel.GetCurrentThread.restype = wintypes.HANDLE
        kernel.GetCurrentThread.argtypes = []
        kernel.SetThreadPriority.argtypes = [wintypes.HANDLE, ctypes.c_int]
        kernel.SetThreadPriority.restype = wintypes.BOOL
        return bool(kernel.SetThreadPriority(kernel.GetCurrentThread(), THREAD_PRIORITY_BELOW_NORMAL))
    except (AttributeError, OSError):
        return False


def current_thread_priority() -> int | None:
    """The calling thread's priority, or None if it cannot be read. Diagnostics
    and tests only - nothing in the app branches on this."""
    if os.name != "nt":
        return None
    try:
        kernel = ctypes.windll.kernel32
        kernel.GetCurrentThread.restype = wintypes.HANDLE
        kernel.GetCurrentThread.argtypes = []
        kernel.GetThreadPriority.argtypes = [wintypes.HANDLE]
        kernel.GetThreadPriority.restype = ctypes.c_int
        value = kernel.GetThreadPriority(kernel.GetCurrentThread())
        return None if value == 0x7FFFFFFF else int(value)
    except (AttributeError, OSError):
        return None


def local_thread_pool(ceiling: int = LOCAL_WORKER_CEILING, floor: int = LOCAL_WORKER_FLOOR,
                      pending: int | None = None) -> concurrent.futures.ThreadPoolExecutor:
    """A pool sized for whatever the machine can spare, whose threads yield to
    everything else. `pending` caps it at the amount of work actually queued."""
    workers = local_worker_budget(ceiling, floor)
    if pending is not None:
        workers = max(1, min(workers, int(pending)))
    # Unrestricted means these threads compete on equal terms with everything
    # else on the machine; the polite mode drops them below normal instead.
    initializer = None if UNRESTRICTED_RESOURCES else lower_current_thread_priority
    return concurrent.futures.ThreadPoolExecutor(max_workers=workers, initializer=initializer)
