# Win32 SetThreadExecutionState flags - used to stop the PC from auto-sleeping while
# a download is actively in flight (see set_system_sleep_blocked()/sync_sleep_prevention()).
ES_CONTINUOUS = 0x80000000
ES_SYSTEM_REQUIRED = 0x00000001


def set_system_sleep_blocked(blocked: bool):
    try:
        if blocked:
            ctypes.windll.kernel32.SetThreadExecutionState(ES_CONTINUOUS | ES_SYSTEM_REQUIRED)
        else:
            ctypes.windll.kernel32.SetThreadExecutionState(ES_CONTINUOUS)
    except (AttributeError, OSError):
        pass


def _default_app_folder() -> Path:
    base = os.getenv("APPDATA")
    return Path(base) / APP_NAME if base else Path.home() / ".distant-viewer"


def app_data_redirect_file() -> Path:
    """Fixed, never-moved location of the breadcrumb pointing at the real app data
    folder. Kept at the original default location so the app can always find its
    (possibly relocated) data without a chicken-and-egg lookup through settings.json,
    which itself lives inside the folder being pointed to."""
    return _default_app_folder() / "data_location.txt"


_APP_FOLDER_CACHE: Path | None = None


def app_folder() -> Path:
    # This is called once per file during library indexing (via thumb_path_for),
    # so re-doing a redirect-file read plus two mkdir() calls on every single call
    # made indexing a large folder dramatically slower than the actual file
    # scanning itself. The resolved folder cannot change during a run except
    # through set_app_data_redirect(), which invalidates this cache.
    global _APP_FOLDER_CACHE
    if _APP_FOLDER_CACHE is not None:
        return _APP_FOLDER_CACHE
    default_folder = _default_app_folder()
    default_folder.mkdir(parents=True, exist_ok=True)
    try:
        redirected = app_data_redirect_file().read_text(encoding="utf-8").strip()
    except OSError:
        redirected = ""
    folder = Path(redirected) if redirected else default_folder
    folder.mkdir(parents=True, exist_ok=True)
    _APP_FOLDER_CACHE = folder
    return folder


def set_app_data_redirect(folder: Path | None):
    global _APP_FOLDER_CACHE, _THUMBNAIL_FOLDER_CACHE, _EXPLORE_CACHE_FOLDER_CACHE
    redirect_file = app_data_redirect_file()
    try:
        if folder is None:
            if redirect_file.exists():
                redirect_file.unlink()
        else:
            redirect_file.write_text(str(folder), encoding="utf-8")
    except OSError:
        pass
    _APP_FOLDER_CACHE = None
    _THUMBNAIL_FOLDER_CACHE = None
    _EXPLORE_CACHE_FOLDER_CACHE = None


def settings_file() -> Path:
    return app_folder() / "settings.json"


def _load_persisted_settings() -> dict:
    try:
        data = json.loads(settings_file().read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def _load_saved_library_folder() -> Path:
    raw = str(_load_persisted_settings().get("saved_library_folder") or "").strip()
    return Path(raw) if raw else Path(DEFAULT_SAVED_LIBRARY_FOLDER)


