def mix_hex_colors(base: str, other: str, amount: float) -> str:
    """`base` blended `amount` (0-1) of the way toward `other`."""
    b, o = QColor(base), QColor(other)
    t = max(0.0, min(1.0, amount))
    return QColor(
        round(b.red() + (o.red() - b.red()) * t),
        round(b.green() + (o.green() - b.green()) * t),
        round(b.blue() + (o.blue() - b.blue()) * t),
    ).name()


def entry_is_realbooru(entry: dict) -> bool:
    for value in [
        entry.get("site"),
        entry.get("source_url"),
        entry.get("media_url"),
        entry.get("path"),
        entry.get("thumb_url"),
    ]:
        if "realbooru" in str(value or "").lower():
            return True
    return False


def entry_is_rule34(entry: dict) -> bool:
    for value in [
        entry.get("site"),
        entry.get("source_url"),
        entry.get("media_url"),
        entry.get("path"),
        entry.get("thumb_url"),
    ]:
        if "rule34" in str(value or "").lower():
            return True
    return False


def entry_skips_dapi_tag_lookup(entry: dict) -> bool:
    # Realbooru's DAPI tag lookup is unreliable/rate-limited - always skip it.
    # Rule34.xxx's page=dapi&s=tag lookup (unlike its post search, which works fine
    # with a real key) ignores its own names= filter entirely - confirmed by
    # querying it with several different tag names and getting back the exact same
    # unrelated tag list every time, authenticated or not. fetch_missing_tag_categories
    # already filters out anything that doesn't match a requested name, so it can't
    # corrupt data, but it can also never usefully succeed - always skip it and rely
    # on extract_tag_categories_from_html (HTML-scraped, confirmed complete/accurate).
    if entry_is_realbooru(entry) or entry_is_rule34(entry):
        return True
    return False


class GUID(ctypes.Structure):
    _fields_ = [
        ("Data1", wintypes.DWORD),
        ("Data2", wintypes.WORD),
        ("Data3", wintypes.WORD),
        ("Data4", ctypes.c_ubyte * 8),
    ]


class SIZE(ctypes.Structure):
    _fields_ = [("cx", ctypes.c_long), ("cy", ctypes.c_long)]


class RGBQUAD(ctypes.Structure):
    _fields_ = [
        ("rgbBlue", ctypes.c_byte),
        ("rgbGreen", ctypes.c_byte),
        ("rgbRed", ctypes.c_byte),
        ("rgbReserved", ctypes.c_byte),
    ]


class BITMAP(ctypes.Structure):
    _fields_ = [
        ("bmType", ctypes.c_long),
        ("bmWidth", ctypes.c_long),
        ("bmHeight", ctypes.c_long),
        ("bmWidthBytes", ctypes.c_long),
        ("bmPlanes", ctypes.c_ushort),
        ("bmBitsPixel", ctypes.c_ushort),
        ("bmBits", ctypes.c_void_p),
    ]


class BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [
        ("biSize", wintypes.DWORD),
        ("biWidth", ctypes.c_long),
        ("biHeight", ctypes.c_long),
        ("biPlanes", wintypes.WORD),
        ("biBitCount", wintypes.WORD),
        ("biCompression", wintypes.DWORD),
        ("biSizeImage", wintypes.DWORD),
        ("biXPelsPerMeter", ctypes.c_long),
        ("biYPelsPerMeter", ctypes.c_long),
        ("biClrUsed", wintypes.DWORD),
        ("biClrImportant", wintypes.DWORD),
    ]


class BITMAPINFO(ctypes.Structure):
    _fields_ = [("bmiHeader", BITMAPINFOHEADER), ("bmiColors", RGBQUAD * 1)]


