def load_site_accounts() -> dict[str, str]:
    """Read the user's site accounts and make them the ones requests use.
    An environment variable, when set, wins over the file."""
    global GELBOORU_USER_ID, GELBOORU_API_KEY, RULE34_USER_ID, RULE34_API_KEY
    try:
        data = json.loads(site_accounts_file().read_text(encoding="utf-8"))
    except (OSError, ValueError):
        data = {}
    if not isinstance(data, dict):
        data = {}
    values = {field: str(data.get(field) or "").strip() for field in SITE_ACCOUNT_FIELDS}
    GELBOORU_USER_ID = os.environ.get("DISTANT_VIEWER_GELBOORU_USER_ID") or values["gelbooru_user_id"]
    GELBOORU_API_KEY = os.environ.get("DISTANT_VIEWER_GELBOORU_API_KEY") or values["gelbooru_api_key"]
    RULE34_USER_ID = os.environ.get("DISTANT_VIEWER_RULE34_USER_ID") or values["rule34_user_id"]
    RULE34_API_KEY = os.environ.get("DISTANT_VIEWER_RULE34_API_KEY") or values["rule34_api_key"]
    return values


def save_site_accounts(values: dict[str, str]):
    clean = {field: str(values.get(field) or "").strip() for field in SITE_ACCOUNT_FIELDS}
    write_json_file(site_accounts_file(), clean)
    load_site_accounts()


