class SoftErrorPage(RuntimeError):
    """The site answered 200 OK with an error page instead of the real content."""


# Realbooru serves this ~97-byte body with a 200 status when a post will not load:
# "There was an error loading this page. If you think this is a mistake, try
# refreshing momentarily." Nothing about the HTTP layer says anything went wrong, so
# a scrape of it looks exactly like a post that genuinely has no tags and no date -
# and the repair jobs were recording those files as "checked, nothing to do" and
# never looking at them again. The page itself asks to be retried, and there is no
# way to tell "gone for good" from "erroring right now", so it must stay retryable.
_SOFT_ERROR_MARKERS = (
    "there was an error loading this page",
    "try refreshing momentarily",
)


def looks_like_soft_error_page(html_text: str) -> bool:
    if not html_text:
        return True
    sample = html_text[:2000].lower()
    return any(marker in sample for marker in _SOFT_ERROR_MARKERS)


def repair_failure_is_permanent(exc: BaseException) -> bool:
    """Whether a repair failure is worth remembering rather than retrying.

    A deleted post (404/410) will never come back, so re-requesting it on every
    future run is pure waste - on a library this size that is thousands of pointless
    requests. Everything else, and 503 in particular, is exactly the transient
    rate-limiting these sites throw constantly, and must stay retryable."""
    if isinstance(exc, urllib.error.HTTPError):
        return exc.code in {404, 410}
    return False


# The maintenance jobs on the Repair tab. Each one walks the saved library, so they
# all need to remember what they have already fixed - otherwise every run starts from
# scratch, which on a library this size means hours of redone work. Only *successes*
# are remembered: a file that failed (a 503, a video that would not decode) stays in
# the queue so the next run retries it.
REPAIR_JOBS = ("missing_info", "tags", "thumbs")
# Position of the Repair tab in SettingsPage's tab list - keep in step with the
# builder list in SettingsPage.__init__.
SETTINGS_REPAIR_TAB_INDEX = 4


def explore_log_file() -> Path:
    return app_folder() / "explore_debug.log"


def app_log_file() -> Path:
    return app_folder() / "app_debug.log"


def safe_log_text(value: object) -> str:
    text = str(value)
    text = re.sub(r"api_key=([^&\s]+)", "api_key=<hidden>", text, flags=re.IGNORECASE)
    text = re.sub(r"user_id=([^&\s]+)", "user_id=<hidden>", text, flags=re.IGNORECASE)
    return text


def write_explore_log(message: object):
    write_debug_log(explore_log_file(), message)


def write_app_log(message: object):
    write_debug_log(app_log_file(), message)


def write_debug_log(path: Path, message: object):
    try:
        line = f"{time.strftime('%Y-%m-%d %H:%M:%S')} {safe_log_text(message)}\n"
        if path.exists() and path.stat().st_size > 512_000:
            path.write_text("", encoding="utf-8")
        with path.open("a", encoding="utf-8") as handle:
            handle.write(line)
    except Exception:
        pass


_THUMBNAIL_FOLDER_CACHE: Path | None = None
_EXPLORE_CACHE_FOLDER_CACHE: Path | None = None


def thumbnail_folder() -> Path:
    # Cached for the same reason as app_folder() - this is called once per file
    # while indexing a library (via thumb_path_for), so a mkdir() on every call
    # is a real, measured bottleneck at tens of thousands of files.
    global _THUMBNAIL_FOLDER_CACHE
    if _THUMBNAIL_FOLDER_CACHE is not None:
        return _THUMBNAIL_FOLDER_CACHE
    folder = app_folder() / "thumbnails"
    folder.mkdir(parents=True, exist_ok=True)
    _THUMBNAIL_FOLDER_CACHE = folder
    return folder


def explore_cache_folder() -> Path:
    global _EXPLORE_CACHE_FOLDER_CACHE
    if _EXPLORE_CACHE_FOLDER_CACHE is not None:
        return _EXPLORE_CACHE_FOLDER_CACHE
    folder = app_folder() / "explore"
    folder.mkdir(parents=True, exist_ok=True)
    _EXPLORE_CACHE_FOLDER_CACHE = folder
    return folder


def touch_cache_file(path: Path):
    """Bump a cached file's mtime so it reads as recently-used for LRU cache pruning."""
    try:
        os.utime(path, None)
    except OSError:
        pass


def folder_size_bytes(folder: Path) -> int:
    total = 0
    try:
        for entry in folder.iterdir():
            try:
                if entry.is_file():
                    total += entry.stat().st_size
            except OSError:
                continue
    except OSError:
        pass
    return total


def prune_cache_folder(folder: Path, max_bytes: int, keep_last=None) -> tuple[int, int]:
    """Delete least-recently-used files in folder until its total size is under max_bytes.

    Uses file mtime as the "last used" signal: cache reads call touch_cache_file() to
    bump mtime on reuse, so freshly-downloaded/just-viewed files are pruned last.
    Returns (files_deleted, bytes_freed).
    """
    if max_bytes <= 0:
        return 0, 0
    try:
        files = []
        total = 0
        for entry in folder.iterdir():
            try:
                if not entry.is_file():
                    continue
                stat = entry.stat()
            except OSError:
                continue
            total += stat.st_size
            files.append((stat.st_mtime, entry, stat.st_size))
    except OSError:
        return 0, 0
    if total <= max_bytes:
        return 0, 0
    # keep_last() names the files still in use (thumbnails of the saved
    # library). Everything else goes first, oldest first: plain oldest-first
    # deleted in-use thumbnails of older files - while the thumbnails orphaned
    # by moves, often newer, survived - and the next scroll rebuilt them all.
    keep = keep_last() if keep_last is not None else None
    if keep:
        files.sort(key=lambda item: (item[1].name in keep, item[0]))
    else:
        files.sort(key=lambda item: item[0])
    deleted = 0
    freed = 0
    for _mtime, entry, size in files:
        if total <= max_bytes:
            break
        try:
            entry.unlink()
        except OSError:
            continue
        total -= size
        freed += size
        deleted += 1
    return deleted, freed


def clear_cache_folder(folder: Path) -> tuple[int, int]:
    """Delete every file in folder, regardless of age. Returns (files_deleted, bytes_freed)."""
    deleted = 0
    freed = 0
    try:
        entries = list(folder.iterdir())
    except OSError:
        return 0, 0
    for entry in entries:
        try:
            if not entry.is_file():
                continue
            size = entry.stat().st_size
            entry.unlink()
        except OSError:
            continue
        deleted += 1
        freed += size
    return deleted, freed


def collect_files_recursive(root: Path) -> list[Path]:
    if not root.exists():
        return []
    return [path for path in root.rglob("*") if path.is_file()]


def move_file_safely(source: Path, target: Path, wait: float = 2.0):
    """Move a file without ever leaving it in both places.

    On the same drive this is a rename, retried for a moment while something
    still holds the file - the viewer keeps the image that was on screen open
    for ~150ms after it is told to let go. shutil.move() instead fell straight
    back to copy-then-delete: the copy worked, the delete hit the same lock,
    and the file ended up in Filtered AND Unfiltered with "Failed 1" reported.
    Across drives it copies, then deletes the source; if that delete keeps
    failing, the new copy is removed again and the error raised."""
    deadline = time.monotonic() + wait

    def pause() -> bool:
        if time.monotonic() >= deadline:
            return False
        app = QApplication.instance()
        if app is not None and QThread.currentThread() is app.thread():
            app.processEvents()
        time.sleep(0.05)
        return True

    while True:
        try:
            os.rename(source, target)
            return
        except FileExistsError:
            raise
        except OSError as exc:
            if getattr(exc, "winerror", None) == 17:  # ERROR_NOT_SAME_DEVICE
                break
            if getattr(exc, "winerror", None) not in (5, 32, 33) or not pause():
                raise
    if os.path.exists(target):
        raise FileExistsError(errno.EEXIST, "File exists", str(target))
    shutil.copy2(source, target)
    while True:
        try:
            os.unlink(source)
            return
        except OSError:
            if pause():
                continue
            try:
                os.unlink(target)
            except OSError:
                pass
            raise


def reveal_in_explorer(path: Path):
    """Open the file's folder in Explorer with the file selected and scrolled
    into view.

    `explorer /select, <path>` (the old way) opened the folder but, in a big
    folder, often selected nothing - leaving you at the top of 50,000 files.
    SHOpenFolderAndSelectItems is what Explorer itself uses for "show in
    folder". Done on a thread: Explorer can take a moment on a huge folder."""
    path = Path(path)

    def run():
        try:
            ole32 = ctypes.WinDLL("ole32")
            shell32 = ctypes.WinDLL("shell32")
            ole32.CoInitializeEx(None, 2)   # COINIT_APARTMENTTHREADED
            try:
                shell32.ILCreateFromPathW.restype = ctypes.c_void_p
                shell32.ILCreateFromPathW.argtypes = [wintypes.LPCWSTR]
                shell32.SHOpenFolderAndSelectItems.argtypes = [ctypes.c_void_p, wintypes.UINT, ctypes.c_void_p, wintypes.DWORD]
                shell32.ILFree.argtypes = [ctypes.c_void_p]
                pidl = shell32.ILCreateFromPathW(str(path))
                if pidl:
                    try:
                        if shell32.SHOpenFolderAndSelectItems(pidl, 0, None, 0) == 0:
                            return
                    finally:
                        shell32.ILFree(pidl)
            finally:
                ole32.CoUninitialize()
        except Exception as exc:
            write_app_log(f"reveal in explorer failed path={path} error={exc!r}")
        # Fallback: one correctly quoted argument, which explorer.exe needs.
        try:
            subprocess.Popen(f'explorer.exe /select,"{path}"')
        except OSError:
            pass

    threading.Thread(target=run, name="reveal-in-explorer", daemon=True).start()


def copy_media_to_clipboard(paths: list[Path], still_image: Path | None = None):
    """Put files on the clipboard so they paste anywhere: as the files
    themselves (a folder, Discord, a mail - GIFs stay animated, videos work),
    and for a single still image also as a picture (Paint, chat boxes)."""
    mime = QMimeData()
    mime.setUrls([QUrl.fromLocalFile(str(path)) for path in paths])
    if still_image is not None:
        reader = QImageReader(str(still_image))
        reader.setAutoTransform(True)
        image = reader.read()
        if not image.isNull():
            mime.setImageData(image)
    QApplication.clipboard().setMimeData(mime)


def unlink_file_safely(path: Path, wait: float = 1.0):
    """Delete a file, retrying for a moment while something still has it open.

    The viewer keeps the image it was just showing open for a split second
    after it is told to let go; a delete in that window failed outright, so a
    delete in the pop-out sometimes simply didn't happen."""
    deadline = time.monotonic() + wait
    while True:
        try:
            path.unlink()
            return
        except FileNotFoundError:
            raise
        except OSError as exc:
            if getattr(exc, "winerror", None) not in (5, 32, 33) or time.monotonic() >= deadline:
                raise
        app = QApplication.instance()
        if app is not None and QThread.currentThread() is app.thread():
            app.processEvents(QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents)
        time.sleep(0.05)


def move_files_between_buckets(jobs, destination: Path, hq_side: int, progress=None, lock_wait: float = 2.0) -> dict:
    """Move each (source, entry) in `jobs` into `destination`. Safe on any thread.

    Returns {source: "moved" | "exists" | "missing" | "failed"}. One rename per
    file, tried once; files something still has open are retried together for
    at most `lock_wait` seconds in total, not per file. The file's thumbnails
    go with it - they are keyed by path, so a move used to orphan them and
    rebuild every one. `progress`, a one-item list, counts files handled."""
    results: dict = {}
    lock_errors = (5, 32, 33)

    def attempt(source: Path, entry) -> bool:
        target = destination / source.name
        try:
            move_file_safely(source, target, wait=0)
        except FileExistsError:
            results[source] = "exists"
            return True
        except FileNotFoundError:
            results[source] = "missing"
            return True
        except OSError as exc:
            if getattr(exc, "winerror", None) in lock_errors:
                return False
            results[source] = "failed"
            return True
        results[source] = "moved"
        if entry is not None:
            mtime, size = entry.get("mtime"), entry.get("size")
            old_thumb = entry.get("thumb")
            if old_thumb:
                new_thumb = thumb_path_for(target, mtime, size)
                try:
                    os.replace(old_thumb, new_thumb)
                    KNOWN_THUMBNAILS.add(new_thumb)
                except OSError:
                    pass
            try:
                os.replace(
                    full_quality_thumb_path_for(source, mtime, size, hq_side),
                    full_quality_thumb_path_for(target, mtime, size, hq_side),
                )
            except OSError:
                pass
        return True

    locked = []
    for done, (source, entry) in enumerate(jobs, start=1):
        if not attempt(source, entry):
            locked.append((source, entry))
        if progress is not None:
            progress[0] = done
    deadline = time.monotonic() + lock_wait
    while locked and time.monotonic() < deadline:
        time.sleep(0.05)
        locked = [job for job in locked if not attempt(*job)]
    for source, _entry in locked:
        results[source] = "failed"
    return results


# Background build pacing for build_saved_path_lookup() (see load_json_object_incremental()).
SAVED_LOOKUP_BUILD_BACKOFF = 1.0


def build_saved_path_lookup(snapshots, key_for, pace=None) -> tuple[dict[str, str], dict[str, list[str]], dict[str, dict]]:
    """Explore-post -> saved-file lookup, its reverse (path -> keys), and any
    folder metadata it had to load itself (folder -> dict).

    `snapshots` is [(folder, [(name, meta), ...] or None)]; None means that
    folder's metadata isn't loaded yet and is read here. One directory listing
    per folder replaces the per-file exists()/is_file() calls, and the
    metadata comes from memory instead of re-parsing both ~100MB files - the
    old rebuild did all of that on the UI thread and took 10-13s on this
    library, after every single delete or move. `pace` is a one-item list
    (sleep factor), so a caller that starts waiting can set it to 0."""
    lookup: dict[str, str] = {}
    loaded: dict[str, dict] = {}
    batch = 0
    batch_started = time.perf_counter()
    for folder, items in snapshots:
        try:
            with os.scandir(folder) as iterator:
                present = {e.name for e in iterator if os.path.splitext(e.name)[1].lower() in MEDIA_EXTENSIONS}
        except OSError:
            present = set()
        if items is None:
            data = load_saved_metadata_in_background(Path(folder))
            loaded[str(folder)] = data
            items = list(data.items())
        base = os.path.join(str(folder), "")
        for name, meta in items:
            if name not in present or not isinstance(meta, dict):
                continue
            file_path = base + name
            source_url = unescape(meta.get("source_url") or "")
            if source_url:
                lookup[f"source:{source_url}"] = file_path
            lookup[f"entry:{key_for(meta)}"] = file_path
            if pace is not None and pace[0]:
                batch += 1
                if batch >= 1000:
                    worked = time.perf_counter() - batch_started
                    time.sleep(min(0.05, worked * pace[0]))
                    batch = 0
                    batch_started = time.perf_counter()
        for name in present:
            stem = os.path.splitext(name)[0]
            if "_" in stem:
                site, post_id = stem.split("_", 1)
                lookup.setdefault(f"entry:{site.lower()}|{post_id}", base + name)
    reverse: dict[str, list[str]] = {}
    for key, file_path in lookup.items():
        reverse.setdefault(file_path, []).append(key)
    return lookup, reverse, loaded


def live_saved_thumbnail_names(folders, hq_side: int) -> set[str] | None:
    """File names of the thumbnails the saved library uses right now (plain,
    plus sharp ones at the current gallery size). None if a folder can't be
    listed - then nothing is treated as an orphan."""
    names: set[str] = set()
    for folder in folders:
        try:
            with os.scandir(folder) as iterator:
                for direntry in iterator:
                    if os.path.splitext(direntry.name)[1].lower() not in MEDIA_EXTENSIONS:
                        continue
                    try:
                        stat = direntry.stat()
                    except OSError:
                        continue
                    file_path = Path(direntry.path)
                    names.add(os.path.basename(thumb_path_for(file_path, stat.st_mtime, stat.st_size)))
                    names.add(os.path.basename(full_quality_thumb_path_for(file_path, stat.st_mtime, stat.st_size, hq_side)))
        except OSError:
            return None
    return names


def remove_empty_tree(root: Path):
    if not root.exists():
        return
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        directory = Path(dirpath)
        try:
            if not any(directory.iterdir()):
                directory.rmdir()
        except OSError:
            continue


def resource_path(name: str) -> Path:
    base = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent))
    return base / name


def url_with_scheme(url: str | None) -> str:
    if not url:
        return ""
    url = str(url).strip()
    if url.startswith("//"):
        return "https:" + url
    if url.startswith("http://") or url.startswith("https://"):
        return url
    return url


def url_suffix(url: str) -> str:
    suffix = Path(urllib.parse.urlparse(url).path).suffix.lower()
    return suffix if suffix else ".jpg"


def media_type_from_url(url: str) -> str:
    suffix = url_suffix(url)
    if suffix in GIF_EXTENSIONS:
        return "gif"
    if suffix in VIDEO_EXTENSIONS:
        return "video"
    return "image"


def suffix_from_content_type(content_type: str | None) -> str:
    content_type = (content_type or "").split(";")[0].strip().lower()
    return {
        "video/mp4": ".mp4",
        "video/webm": ".webm",
        "image/gif": ".gif",
        "image/jpeg": ".jpg",
        "image/jpg": ".jpg",
        "image/png": ".png",
        "image/webp": ".webp",
        "image/bmp": ".bmp",
        "image/tiff": ".tiff",
    }.get(content_type, "")


def first_video_candidate(entry: dict) -> str:
    for url in entry.get("candidate_media_urls") or []:
        if media_type_from_url(str(url)) == "video":
            return str(url)
    return ""


def video_candidates_for_entry(entry: dict, preferred_url: str = "") -> list[str]:
    candidates = []
    stored_candidates = list(entry.get("candidate_media_urls") or [])[:45]
    raw_candidates = [preferred_url, entry.get("media_url"), entry.get("path"), *stored_candidates]
    for url in raw_candidates:
        url = str(url or "").strip()
        raw_suffix = Path(urllib.parse.urlparse(url).path).suffix.lower()
        possible_extensionless_video = entry.get("type") == "video" and raw_suffix not in IMAGE_EXTENSIONS and raw_suffix not in GIF_EXTENSIONS
        if not url:
            continue
        if media_type_from_url(url) == "video" or possible_extensionless_video:
            candidates.append(url)
        if entry.get("type") == "video" and media_type_from_url(url) != "video":
            candidates.extend(
                guess for guess in original_url_guesses(url)
                if media_type_from_url(guess) == "video"
            )
    seen = set()
    unique = [
        url for url in candidates
        if url and (media_type_from_url(url) == "video" or entry.get("type") == "video") and not (url in seen or seen.add(url))
    ]
    return unique[:16]


def image_candidates_for_entry(entry: dict, preferred_url: str = "") -> list[str]:
    candidates = [
        preferred_url,
        entry.get("media_url"),
        entry.get("path"),
        *(entry.get("candidate_media_urls") or []),
        entry.get("thumb_url"),
    ]
    expanded = []
    for url in candidates:
        url = str(url or "").strip()
        if not url:
            continue
        if looks_like_preview_media_url(url):
            expanded.extend(original_url_guesses(url))
        expanded.append(url)
    candidates = expanded
    filtered = []
    for url in candidates:
        url = str(url or "").strip()
        if not url:
            continue
        raw_suffix = Path(urllib.parse.urlparse(url).path).suffix.lower()
        if media_type_from_url(url) in {"image", "gif"} or raw_suffix not in VIDEO_EXTENSIONS:
            filtered.append(url)
    seen = set()
    return [url for url in filtered if not (url in seen or seen.add(url))]


def looks_like_video_file(path: Path) -> bool:
    try:
        with path.open("rb") as handle:
            head = handle.read(64)
    except OSError:
        return False
    if b"ftyp" in head[:16]:
        return True
    if head.startswith(b"\x1a\x45\xdf\xa3"):
        return True
    if head.startswith(b"RIFF") and b"AVI" in head[:16]:
        return True
    if head.startswith(b"\x30\x26\xb2\x75"):
        return True
    if path.suffix.lower() == ".webm":
        return head.startswith(b"\x1a\x45\xdf\xa3")
    if path.suffix.lower() in {".mp4", ".m4v", ".mov"}:
        return b"ftyp" in head[:16]
    if path.suffix.lower() in {".avi"}:
        return head.startswith(b"RIFF") and b"AVI" in head[:16]
    if path.suffix.lower() in {".mkv"}:
        return head.startswith(b"\x1a\x45\xdf\xa3")
    if path.suffix.lower() in {".wmv"}:
        return head.startswith(b"\x30\x26\xb2\x75")
    return media_type(path) == "video"


def explore_thumb_path(url: str) -> str:
    raw = f"explore-thumb|{url}".encode("utf-8", errors="ignore")
    return str(explore_cache_folder() / f"{hashlib.sha1(raw).hexdigest()}.jpg")


def explore_media_path(url: str) -> Path:
    suffix = url_suffix(url)
    raw = f"explore-media|{url}".encode("utf-8", errors="ignore")
    return explore_cache_folder() / f"{hashlib.sha1(raw).hexdigest()}{suffix}"


def saved_metadata_path(folder: Path | None = None) -> Path:
    return (folder or SAVED_LIBRARY_FOLDER) / SAVED_METADATA_FILE


_JSON_WHITESPACE = re.compile(r"[ \t\n\r]*")
_JSON_DECODER = json.JSONDecoder()


def load_json_object_incremental(text: str, pace: float = 0.0) -> dict:
    """json.loads() for a big top-level object, one member at a time.

    json.loads() parses the whole ~100MB saved-metadata file in a single C call
    that never releases the GIL, so loading it on a background thread still froze
    the UI for ~0.8s. Decoding member by member returns to the interpreter between
    entries, so the UI thread keeps getting its turn. Same result; a little slower
    in total, which nothing is waiting on.

    Returning to the interpreter is not enough on its own when the UI thread is
    busy: it gets the GIL back only every few milliseconds, so a long parse still
    made a view switch take ~1s instead of ~0.1s. With `pace`, every few hundred
    entries the parse sleeps for `pace` times as long as it just worked."""
    match = _JSON_WHITESPACE.match
    batch = 0
    batch_started = time.perf_counter()
    decode = _JSON_DECODER.raw_decode
    index = match(text, 0).end()
    if text[index:index + 1] != "{":
        raise ValueError("not a JSON object")
    index = match(text, index + 1).end()
    result: dict = {}
    if text[index:index + 1] == "}":
        return result
    while True:
        key, index = decode(text, index)
        index = match(text, index).end()
        if text[index:index + 1] != ":":
            raise ValueError("expected ':'")
        value, index = decode(text, match(text, index + 1).end())
        result[key] = value
        if pace:
            batch += 1
            if batch >= 400:
                worked = time.perf_counter() - batch_started
                time.sleep(min(0.05, worked * pace))
                batch = 0
                batch_started = time.perf_counter()
        index = match(text, index).end()
        character = text[index:index + 1]
        if character == ",":
            index = match(text, index + 1).end()
        elif character == "}":
            return result
        else:
            raise ValueError("expected ',' or '}'")


def parse_saved_metadata_text(text: str, pace: float = 0.0) -> dict:
    # Collection is paused for the parse: allocating ~50k entries otherwise sets
    # off full GC passes over the whole heap partway through (100ms+ each). The
    # result is long-lived (it becomes the app's metadata cache), so it is frozen
    # before collection resumes - otherwise the very next collection walks all of
    # it at once and the pause only moves the freeze.
    enabled = gc.isenabled()
    gc.disable()
    try:
        try:
            return load_json_object_incremental(text, pace)
        except (ValueError, IndexError):
            return json.loads(text)
    finally:
        gc.freeze()
        if enabled:
            gc.enable()


def load_saved_metadata(folder: Path | None = None) -> dict:
    """The folder's metadata as it really is: the last full write plus every change
    journaled since (see append_saved_metadata_journal). Taken under the metadata
    lock so a write that lands mid-read cannot pair a new file with a stale journal
    or the reverse."""
    folder = folder or SAVED_LIBRARY_FOLDER
    with SAVED_METADATA_LOCK:
        try:
            data = parse_saved_metadata_text(saved_metadata_path(folder).read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                data = {}
        except (OSError, ValueError):
            data = {}
        replay_saved_metadata_journal(folder, data)
    return data


# How long a streaming JSON write sleeps per unit of work (see write_json_file).
JSON_WRITE_BACKOFF = 1.0
# Switched off once the app is on its way out: pacing only exists to keep the
# UI smooth, and at that pace a ~100MB metadata write takes ~40s - longer than
# the exit waited, so the last changes were left for the journal to replay.
JSON_WRITE_PACED = True


def write_json_file(path: Path, data, streaming: bool = False):
    """Write `data` as JSON, atomically.

    `streaming=True` encodes through JSONEncoder.iterencode() instead of
    json.dumps(). That matters for the big files here (this library's saved
    metadata is ~88MB and its media cache ~75MB): json.dumps() does the entire
    encode inside one C call and never releases the GIL, so doing it on a
    "background" thread still froze the UI thread solid for the whole encode -
    about half a second, on every save, delete, move and repair-job flush.
    iterencode() returns to the interpreter between chunks, which turns that
    into a worst case of about 5ms. It is slower in total, which is fine:
    nothing waits on these writes, but the UI does.

    Either way the bytes land in a temp file that is renamed into place, so an
    interrupted write can never leave a half-written file behind - the encode
    now spans seconds, which makes that a real possibility rather than a
    theoretical one."""
    path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = path.with_name(path.name + ".tmp")
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            if streaming:
                # Paced: iterencode hands the GIL back between chunks, but a busy
                # writer still takes it straight back, and a 70-100MB write stole
                # enough of it to make scrolling stutter for its whole length.
                # Sleeping in proportion to the work just done gives the UI thread
                # the larger share; the write simply takes a bit longer.
                started = time.perf_counter()
                for number, chunk in enumerate(json.JSONEncoder().iterencode(data)):
                    handle.write(chunk)
                    if number & 1023 == 0:
                        worked = time.perf_counter() - started
                        if worked > 0.004 and JSON_WRITE_PACED:
                            time.sleep(min(0.05, worked * JSON_WRITE_BACKOFF))
                            started = time.perf_counter()
            else:
                handle.write(json.dumps(data))
        os.replace(temp_path, path)
    except BaseException:
        try:
            temp_path.unlink()
        except OSError:
            pass
        raise


def write_saved_metadata(data: dict, folder: Path | None = None, streaming: bool = False):
    folder = folder or SAVED_LIBRARY_FOLDER
    folder.mkdir(parents=True, exist_ok=True)
    # No indent: with tens of thousands of saved entries this file gets large enough
    # (40-50MB+) that pretty-printing measurably slows down every single save/delete/move.
    write_json_file(saved_metadata_path(folder), data, streaming=streaming)


# --- saved-metadata durability -------------------------------------------------------
#
# Each saved folder's metadata is one big JSON file (~100MB here) that takes seconds
# to write. Tags used to exist only in memory until the next full write finished, and
# that write ran on a throwaway daemon thread: closing the app, restarting it for an
# update, or a crash during those seconds killed the write and silently dropped every
# save since the last one that landed (hundreds of files at a time came back with only
# their file name as a tag). Separate threads could also finish out of order, putting
# an older snapshot on disk after a newer one.
#
# Now every change is appended to a small journal next to the metadata file the
# moment it happens, and loading replays it - so nothing is lost even if a full write
# never completes. Full writes go through one ordered writer thread, and each finished
# write trims the journal entries it now contains.

SAVED_METADATA_JOURNAL_FILE = ".distant_tags.journal"
SAVED_METADATA_JOURNAL_LOCK = threading.Lock()
# Absolute journal offsets already trimmed away, per folder, so a trim measured
# before an earlier trim still removes exactly the right bytes.
_SAVED_METADATA_JOURNAL_BASE: dict[str, int] = {}


def saved_metadata_journal_path(folder: Path | None = None) -> Path:
    return (folder or SAVED_LIBRARY_FOLDER) / SAVED_METADATA_JOURNAL_FILE


def append_saved_metadata_journal(folder: Path, changes: dict):
    """Record entries as they are now (None = removed). Cheap: a few hundred bytes
    appended per changed file."""
    if not changes:
        return
    payload = "".join(
        json.dumps({"n": str(name), "m": meta if isinstance(meta, dict) else None}, ensure_ascii=False) + "\n"
        for name, meta in changes.items()
    ).encode("utf-8")
    path = saved_metadata_journal_path(folder)
    with SAVED_METADATA_JOURNAL_LOCK:
        try:
            with open(path, "a+b") as handle:
                handle.seek(0, os.SEEK_END)
                if handle.tell():
                    # A crash can leave a torn last line; never glue onto it.
                    handle.seek(-1, os.SEEK_END)
                    if handle.read(1) != b"\n":
                        handle.write(b"\n")
                handle.write(payload)
        except OSError as exc:
            write_app_log(f"saved metadata journal append failed folder={folder} error={exc}")


def replay_saved_metadata_journal(folder: Path, data: dict) -> int:
    path = saved_metadata_journal_path(folder)
    with SAVED_METADATA_JOURNAL_LOCK:
        try:
            raw = path.read_bytes()
        except OSError:
            return 0
    return apply_saved_metadata_journal_bytes(raw, data)


# Background preload pacing - see load_json_object_incremental().
SAVED_METADATA_PRELOAD_BACKOFF = 1.0


def load_saved_metadata_in_background(folder: Path) -> dict:
    """load_saved_metadata() for a thread nothing is waiting on.

    The file and the journal are read together under the lock - so they match,
    exactly as load_saved_metadata() guarantees - but the slow part, parsing
    ~100MB, happens after the lock is released and paced, so neither a save or
    move on the UI thread nor the UI itself waits on it."""
    with SAVED_METADATA_LOCK:
        try:
            text = saved_metadata_path(folder).read_text(encoding="utf-8")
        except OSError:
            text = ""
        with SAVED_METADATA_JOURNAL_LOCK:
            try:
                raw = saved_metadata_journal_path(folder).read_bytes()
            except OSError:
                raw = b""
    data: dict = {}
    if text:
        try:
            parsed = parse_saved_metadata_text(text, SAVED_METADATA_PRELOAD_BACKOFF)
        except ValueError:
            parsed = {}
        if isinstance(parsed, dict):
            data = parsed
    apply_saved_metadata_journal_bytes(raw, data)
    return data


def apply_saved_metadata_journal_bytes(raw: bytes, data: dict) -> int:
    applied = 0
    for line in raw.split(b"\n"):
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except ValueError:
            continue    # torn line from an interrupted append
        name = record.get("n") if isinstance(record, dict) else None
        if not isinstance(name, str):
            continue
        meta = record.get("m")
        if isinstance(meta, dict):
            data[name] = meta
        else:
            data.pop(name, None)
        applied += 1
    return applied


def saved_metadata_journal_mark(folder: Path) -> int:
    """Absolute end offset of the journal right now - everything before it is
    already applied to the in-memory dict being snapshotted."""
    key = str(folder)
    with SAVED_METADATA_JOURNAL_LOCK:
        try:
            size = saved_metadata_journal_path(folder).stat().st_size
        except OSError:
            size = 0
        return _SAVED_METADATA_JOURNAL_BASE.get(key, 0) + size


def trim_saved_metadata_journal(folder: Path, upto: int):
    """Drop journal entries up to absolute offset `upto` once a full write that
    contains them has landed."""
    key = str(folder)
    path = saved_metadata_journal_path(folder)
    with SAVED_METADATA_JOURNAL_LOCK:
        base = _SAVED_METADATA_JOURNAL_BASE.get(key, 0)
        drop = upto - base
        if drop <= 0:
            return
        try:
            raw = path.read_bytes()
        except OSError:
            return
        drop = min(drop, len(raw))
        rest = raw[drop:]
        try:
            if rest.strip():
                temp_path = path.with_name(path.name + ".tmp")
                temp_path.write_bytes(rest)
                os.replace(temp_path, path)
            else:
                path.unlink()
        except OSError as exc:
            write_app_log(f"saved metadata journal trim failed folder={folder} error={exc}")
            return
        _SAVED_METADATA_JOURNAL_BASE[key] = base + drop


class SavedMetadataWriter:
    """The one thread that writes saved-metadata files, strictly in order. A newer
    snapshot for a folder replaces an older one still waiting, so a burst of saves
    costs one write, and a write can never land on top of a newer one."""

    def __init__(self):
        self._condition = threading.Condition()
        self._pending: dict[str, tuple[dict, int]] = {}
        self._busy: set[str] = set()
        self._thread: threading.Thread | None = None

    def submit(self, folder_key: str, snapshot: dict, journal_upto: int):
        with self._condition:
            self._pending[folder_key] = (snapshot, journal_upto)
            if self._thread is None or not self._thread.is_alive():
                self._thread = threading.Thread(target=self._run, name="saved-metadata-writer", daemon=True)
                self._thread.start()
            self._condition.notify_all()

    def is_busy(self, folder_key: str) -> bool:
        with self._condition:
            return folder_key in self._busy or folder_key in self._pending

    def wait_idle(self, timeout: float) -> bool:
        with self._condition:
            return self._condition.wait_for(lambda: not self._pending and not self._busy, timeout)

    def _run(self):
        while True:
            with self._condition:
                while not self._pending:
                    self._condition.wait()
                folder_key = next(iter(self._pending))
                snapshot, journal_upto = self._pending.pop(folder_key)
                self._busy.add(folder_key)
            folder = Path(folder_key)
            try:
                with SAVED_METADATA_LOCK:
                    # Streaming encode so this never holds the GIL for long; see
                    # write_json_file(). The trim happens under the same lock, so
                    # a reader never sees the old file with an already-trimmed
                    # journal.
                    write_saved_metadata(snapshot, folder, streaming=True)
                    trim_saved_metadata_journal(folder, journal_upto)
            except BaseException as exc:
                # The journal still holds everything, so nothing is lost; the next
                # change to this folder writes it again.
                write_app_log(f"saved metadata write failed folder={folder} error={exc!r}")
            finally:
                with self._condition:
                    self._busy.discard(folder_key)
                    self._condition.notify_all()


def safe_filename(value: str) -> str:
    value = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', "_", value).strip(" ._")
    return value[:180] or hashlib.sha1(value.encode("utf-8", errors="ignore")).hexdigest()[:12]


def remote_post_id(entry: dict, media_url: str = "") -> str:
    source_url = unescape(entry.get("source_url") or "")
    parsed = urllib.parse.urlparse(source_url)
    query = urllib.parse.parse_qs(parsed.query)
    post_id = (query.get("id") or query.get("amp;id") or [""])[0]
    if not post_id and "/posts/" in parsed.path:
        post_id = parsed.path.rstrip("/").split("/")[-1]
    if not post_id:
        post_id = str(entry.get("post_id") or "")
    if not post_id:
        post_id = hashlib.sha1((media_url or entry.get("path") or entry.get("name") or "").encode("utf-8", errors="ignore")).hexdigest()[:12]
    return safe_filename(post_id)


def remote_save_name(entry: dict, media_url: str) -> str:
    site = safe_filename(str(entry.get("site") or "explore").lower())
    return f"{site}_{remote_post_id(entry, media_url)}{url_suffix(media_url)}"


def post_id_from_source_url(source_url: str) -> str:
    """Like remote_post_id but returns "" instead of a hash when no real post id
    is found in the URL - used where a made-up id would just waste a network
    request against the wrong post."""
    parsed = urllib.parse.urlparse(unescape(source_url or ""))
    query = urllib.parse.parse_qs(parsed.query)
    post_id = (query.get("id") or query.get("amp;id") or [""])[0]
    if not post_id and "/posts/" in parsed.path:
        post_id = parsed.path.rstrip("/").split("/")[-1]
    return post_id.strip()


def parse_upload_date_string(value: object) -> float | None:
    """Parse a post "created/uploaded" timestamp from any of the booru API
    formats this app talks to: Gelbooru-family Ruby-style strings
    ("Sun Jun 14 12:17:00 -0500 2026"), e621's ISO8601 strings, or a raw
    unix-epoch number (some Gelbooru forks only expose a "change" timestamp)."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value) if value > 0 else None
    text = str(value).strip()
    if not text:
        return None
    if text.isdigit():
        try:
            return float(int(text))
        except ValueError:
            return None
    try:
        return datetime.datetime.strptime(text, "%a %b %d %H:%M:%S %z %Y").timestamp()
    except ValueError:
        pass
    try:
        return datetime.datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
    except ValueError:
        pass
    return None


_SITE_LABEL_BASE_URLS = {label.lower(): base for label, base in LEGACY_BOORU_SITES.values()}
# Realbooru's server rate-limits/blocks aggressive concurrent connections (same reason
# REALBOORU_PARALLEL_SAVE_LIMIT is 1 elsewhere) - cap it here too regardless of how many
# worker threads the caller uses, so a batch backfill can't hammer it.
_UPLOAD_DATE_SITE_LOCKS = {"realbooru": threading.Semaphore(1)}
_UPLOAD_DATE_DEFAULT_SEMAPHORE = threading.Semaphore(4)


# How these sites print the upload date on the post page itself. Realbooru writes
# "Posted at Aug, 20 2022 by <user>"; the gelbooru-family templates use an ISO-ish
# "Posted: 2022-08-20 12:34:56". Day precision is plenty for sorting.
_POSTED_DATE_PATTERNS = [
    (r"Posted\s*(?:at)?[:\s]+([A-Z][a-z]{2},?\s+\d{1,2}\s+\d{4})", ["%b, %d %Y", "%b %d %Y"]),
    (r"Posted\s*(?:at)?[:\s]+(\d{4}-\d{2}-\d{2}(?:\s+\d{2}:\d{2}(?::\d{2})?)?)",
     ["%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d"]),
]


def parse_posted_date_from_html(html_text: str) -> float | None:
    text = unescape(html_text or "")
    for pattern, formats in _POSTED_DATE_PATTERNS:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if not match:
            continue
        raw = " ".join(match.group(1).split())
        for fmt in formats:
            try:
                return datetime.datetime.strptime(raw, fmt).timestamp()
            except ValueError:
                continue
    return None


# --- saved-file info recovery ("Fix missing info" repair job) --------------------------

# Saved files are named "<site>_<post id>.<ext>" (remote_save_name), so a file whose
# metadata was lost still says exactly which post it came from.
SAVED_NAME_POST_URLS = {
    "gelbooru": ("Gelbooru", "https://gelbooru.com/index.php?page=post&s=view&id={id}"),
    "realbooru": ("Realbooru", "https://realbooru.com/index.php?page=post&s=view&id={id}"),
    "rule34.xxx": ("Rule34.xxx", "https://rule34.xxx/index.php?page=post&s=view&id={id}"),
    "rule34xxx": ("Rule34.xxx", "https://rule34.xxx/index.php?page=post&s=view&id={id}"),
    "e621": ("e621", "https://e621.net/posts/{id}"),
}
# A post that fails this many separate runs in a row is given up on (shown as
# "unavailable") instead of being retried forever. Realbooru in particular has
# posts whose page permanently answers with its "try refreshing" placeholder.
MISSING_INFO_MAX_FAILED_RUNS = 3
# e621 groups tags by category in its API; map its names onto this app's.
E621_TAG_GROUPS = {
    "artist": "artist", "character": "character", "copyright": "series",
    "general": "general", "species": "general", "meta": "general", "lore": "general", "invalid": "general",
}


def saved_name_post_source(filename: str) -> tuple[str, str] | None:
    """(site label, post page URL) from a saved file's name, or None if the name
    doesn't carry a real post id (e.g. a hashed fallback name)."""
    stem = os.path.splitext(os.path.basename(str(filename)))[0]
    prefix, _separator, post_id = stem.rpartition("_")
    known = SAVED_NAME_POST_URLS.get(prefix.lower())
    if not known or not post_id.isdigit():
        return None
    label, template = known
    return label, template.format(id=post_id)


def fetch_api_upload_date(site_label: str, post_id: str) -> float | None:
    """A post's upload date from a Gelbooru-family DAPI (not Realbooru, whose API
    is switched off)."""
    base_url = _SITE_LABEL_BASE_URLS.get(str(site_label or "").lower())
    if not base_url or not post_id or entry_is_realbooru({"site": site_label}):
        return None
    params = with_gelbooru_auth(base_url, {"page": "dapi", "s": "post", "q": "index", "json": "1", "id": post_id})
    rows = post_rows(fetch_json(f"{base_url}/index.php?{urllib.parse.urlencode(params)}", timeout=10))
    if not rows:
        return None
    return parse_upload_date_string(rows[0].get("created_at") or rows[0].get("change"))


def fetch_saved_post_info(site_label: str, source_url: str) -> dict:
    """Tags, tag categories and upload date for one already-saved post, from a
    single request where possible.

    The post page carries all three (tags with their category classes, and
    "Posted ..."), so one fetch replaces what used to be separate tag and date
    jobs. e621 is read from its JSON API instead. Raises when the post could not
    be fetched, so the caller can tell "the site had nothing" (settle it) from
    "we never got an answer" (retry it)."""
    source_url = unescape(str(source_url or ""))
    site_label = str(site_label or "")
    post_id = post_id_from_source_url(source_url)
    if not source_url or not post_id:
        raise ValueError("No post to look up")
    if site_label.lower() == "e621" or "e621.net" in source_url:
        data = fetch_json(f"https://e621.net/posts/{post_id}.json", timeout=15)
        post = data.get("post") if isinstance(data, dict) else None
        if not isinstance(post, dict):
            raise RuntimeError("e621 returned no post")
        categories: dict[str, str] = {}
        for group, names in (post.get("tags") or {}).items():
            for name in names or []:
                categories[str(name).lower()] = E621_TAG_GROUPS.get(str(group), "general")
        return {
            "tags": sorted(categories),
            "tag_categories": categories,
            "uploaded_at": parse_upload_date_string(post.get("created_at")),
        }
    lock = _UPLOAD_DATE_SITE_LOCKS.get(site_label.lower(), _UPLOAD_DATE_DEFAULT_SEMAPHORE)
    html_text = ""
    last_error: BaseException | None = None
    with lock:
        for attempt in range(3):
            try:
                html_text = fetch_url_bytes(source_url, timeout=16, referer=source_url).decode("utf-8", errors="replace")
                if looks_like_soft_error_page(html_text):
                    html_text = ""
                    raise SoftErrorPage(source_url)
                break
            except Exception as exc:
                last_error = exc
                if repair_failure_is_permanent(exc):
                    break
                if attempt < 2:
                    time.sleep(1.5 * (attempt + 1))
    if not html_text:
        raise last_error or RuntimeError("Could not fetch the post page")
    categories = extract_tag_categories_from_html(html_text)
    uploaded_at = parse_posted_date_from_html(html_text)
    if not uploaded_at:
        try:
            uploaded_at = fetch_api_upload_date(site_label, post_id)
        except Exception:
            uploaded_at = None
    return {"tags": sorted(categories), "tag_categories": categories, "uploaded_at": uploaded_at}


def open_network_request(request, timeout: int):
    for attempt in range(3):
        try:
            return DIRECT_OPENER.open(request, timeout=timeout)
        except urllib.error.HTTPError as direct_error:
            if direct_error.code == 429 and attempt < 2:
                # Some sites (Rule34.xxx/Realbooru especially) rate-limit aggressive
                # scraping with a 429 instead of a clean failure. A short backoff clears
                # most of these rather than falling through to fragile HTML scraping
                # or a degraded/placeholder result.
                time.sleep(1.5 * (attempt + 1))
                continue
            try:
                return urllib.request.urlopen(request, timeout=timeout)
            except Exception:
                raise direct_error
        except urllib.error.URLError as direct_error:
            try:
                return urllib.request.urlopen(request, timeout=timeout)
            except Exception:
                raise direct_error


def download_url_to_path(
    url: str,
    target: Path,
    referer: str | None = None,
    timeout: int = 120,
    progress=None,
    progress_label: str = "Downloading media",
) -> Path:
    target.parent.mkdir(parents=True, exist_ok=True)
    parsed = urllib.parse.urlparse(url)
    referer = referer or f"{parsed.scheme}://{parsed.netloc}/"
    headers = {
        "User-Agent": EXPLORE_USER_AGENT,
        "Accept": "image/avif,image/webp,image/apng,image/*,video/mp4,video/webm,video/*,*/*;q=0.8",
        "Accept-Language": "en-US,en;q=0.9",
        "Referer": referer,
    }
    temp_target = target.with_name(target.name + ".download")
    last_error = None
    for attempt in range(2):
        try:
            if temp_target.exists():
                temp_target.unlink()
            request = urllib.request.Request(url, headers=headers)
            with open_network_request(request, timeout=timeout) as response, temp_target.open("wb") as handle:
                total = int(response.headers.get("Content-Length") or 0)
                response_suffix = suffix_from_content_type(response.headers.get("Content-Type"))
                downloaded = 0
                last_percent = -1
                while True:
                    chunk = response.read(1024 * 512)
                    if not chunk:
                        break
                    handle.write(chunk)
                    downloaded += len(chunk)
                    if progress and total:
                        percent = min(99, int(downloaded * 100 / total))
                        if percent != last_percent:
                            last_percent = percent
                            progress(percent, progress_label)
            if temp_target.exists() and temp_target.stat().st_size > 0:
                final_target = target
                if response_suffix and response_suffix != target.suffix.lower():
                    final_target = target.with_suffix(response_suffix)
                    try:
                        if target.exists() and target != final_target:
                            target.unlink()
                    except OSError:
                        pass
                temp_target.replace(final_target)
                if progress:
                    progress(100, "Downloaded media")
                return final_target
            raise RuntimeError("Downloaded file was empty.")
        except Exception as exc:
            last_error = exc
            try:
                if temp_target.exists():
                    temp_target.unlink()
            except OSError:
                pass
            if attempt == 0:
                time.sleep(0.4)
    raise RuntimeError(str(last_error) if last_error else "Download failed.")


def cached_video_path_for_entry(entry: dict, media_url: str, referer: str | None = None, progress=None, timeout: int = 120) -> tuple[str, Path]:
    last_error = ""
    for url in video_candidates_for_entry(entry, media_url):
        target = explore_media_path(url)
        try:
            if target.exists() and not looks_like_video_file(target):
                target.unlink()
            if not target.exists():
                target = download_url_to_path(url, target, referer, timeout=timeout, progress=progress)
            if looks_like_video_file(target):
                touch_cache_file(target)
                return url, target
            last_error = "Downloaded file was not a playable video."
            try:
                target.unlink()
            except OSError:
                pass
        except Exception as exc:
            last_error = f"{url}: {exc}"
    raise RuntimeError(last_error or "No playable video source was found for this result.")


def verified_video_stream_for_entry(entry: dict, media_url: str, referer: str | None = None, progress=None, timeout: int = 12) -> tuple[str, Path | None]:
    last_error = ""
    for url in video_candidates_for_entry(entry, media_url):
        target = explore_media_path(url)
        if target.exists() and looks_like_video_file(target):
            touch_cache_file(target)
            return url, target
        try:
            parsed = urllib.parse.urlparse(url)
            request = urllib.request.Request(
                url,
                headers={
                    "User-Agent": EXPLORE_USER_AGENT,
                    "Accept": "video/mp4,video/webm,video/*,*/*;q=0.8",
                    "Accept-Language": "en-US,en;q=0.9",
                    "Referer": referer or f"{parsed.scheme}://{parsed.netloc}/",
                    "Range": "bytes=0-255",
                },
            )
            if progress:
                progress(15, "Opening video stream")
            with open_network_request(request, timeout=timeout) as response:
                content_type = (response.headers.get("Content-Type") or "").lower()
                head = response.read(256)
            if "video/" in content_type or b"ftyp" in head[:32] or head.startswith(b"\x1a\x45\xdf\xa3"):
                if progress:
                    progress(100, "Streaming video")
                return url, None
            last_error = f"{url}: response was not a video"
        except Exception as exc:
            last_error = f"{url}: {exc}"
    raise RuntimeError(last_error or "No playable video source was found for this result.")


def fetch_url_bytes(url: str, timeout: int = 25, referer: str | None = None) -> bytes:
    parsed = urllib.parse.urlparse(url)
    referer = referer or f"{parsed.scheme}://{parsed.netloc}/"
    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": EXPLORE_USER_AGENT,
            "Accept": "text/html,application/xhtml+xml,application/xml,application/json,image/avif,image/webp,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.9",
            "Referer": referer,
        },
    )
    with open_network_request(request, timeout=timeout) as response:
        return response.read()


def fetch_json(url: str, timeout: int = 10) -> object:
    last_error = None
    for attempt in range(2):
        try:
            data = fetch_url_bytes(url, timeout=timeout)
            text = data.decode("utf-8-sig", errors="replace").strip()
            if not text:
                raise ValueError("The site returned an empty response")
            if text[0] not in "[{":
                raise ValueError("The site returned a web page instead of JSON")
            return json.loads(text)
        except (ValueError, json.JSONDecodeError) as exc:
            last_error = exc
            if attempt == 0:
                time.sleep(0.25)
    raise last_error or ValueError("The site returned no JSON data")


# ---------------------------------------------------------------------------
# Waifu page: who is in the saved library, and what the web knows about them.
#
# Everything here is plain Python with no Qt, so it can run on worker threads
# and inside the index-builder child process (see waifu_index_cli).
# ---------------------------------------------------------------------------

WAIFU_INDEX_VERSION = 3
# The app reads the index in chunks of this many lines, sleeping after each
# one for WAIFU_READ_BACKOFF x the time it took (see WaifuIndexWorker.read_index).
WAIFU_READ_CHUNK = 400
# While the page is open it notices newly saved files by itself, re-scanning
# at most this often so a running batch of downloads does not keep it busy.
WAIFU_BACKGROUND_RESCAN_SECONDS = 60
WAIFU_READ_BACKOFF = 1.5
WAIFU_PORTRAIT_VERSION = 1
WAIFU_WEB_CACHE_VERSION = 1
