def waifu_folder() -> Path:
    folder = app_folder() / "waifu"
    folder.mkdir(parents=True, exist_ok=True)
    return folder


def waifu_index_path() -> Path:
    return waifu_folder() / "index.jsonl"


def waifu_files_path() -> Path:
    return waifu_folder() / "files.jsonl"


def waifu_choices_path() -> Path:
    return waifu_folder() / "choices.json"


def waifu_web_cache_path() -> Path:
    return waifu_folder() / "web_profiles.json"


def waifu_portrait_folder() -> Path:
    folder = waifu_folder() / "portraits"
    folder.mkdir(parents=True, exist_ok=True)
    return folder


def waifu_index_signature(folders: list[Path]) -> list:
    """Cheap fingerprint of the saved library: each folder's metadata file and
    the folder itself (whose mtime moves whenever a file is added or removed).
    Four stat() calls - cheap enough to check every time the page is shown."""
    signature = []
    for folder in folders:
        try:
            meta = saved_metadata_path(folder).stat()
            meta_part = [meta.st_mtime_ns, meta.st_size]
        except OSError:
            meta_part = [0, 0]
        try:
            folder_part = folder.stat().st_mtime_ns
        except OSError:
            folder_part = 0
        signature.append([str(folder), *meta_part, folder_part])
    return signature


def waifu_prettify_tag(tag: str) -> str:
    """cammy_white -> Cammy White, rebecca_(cyberpunk) -> Rebecca, chun-li -> Chun-Li."""
    text = re.sub(r"(_\([^()]*\))+$", "", str(tag)).replace("_", " ").strip() or str(tag).replace("_", " ")
    words = []
    for word in text.split(" "):
        if word:
            words.append("-".join(part[:1].upper() + part[1:] for part in word.split("-")))
    return " ".join(words)


def waifu_fold(text: str) -> str:
    """Lowercase, accent-free, alphanumerics only - for comparing names across
    sources that romanise differently (Shihouin / Shihōin)."""
    import unicodedata

    text = unicodedata.normalize("NFKD", str(text)).encode("ascii", "ignore").decode("ascii").lower()
    text = text.replace("ou", "o").replace("uu", "u")
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


def waifu_subject_kind(tag: str, category: str, count: int, vtuber_files: int, real_files: int,
                       series_counts: dict) -> str:
    if category != "character":
        return category
    if "(vtuber)" in tag or vtuber_files >= max(1, count * 0.4):
        return "vtuber"
    fictional = sum(amount for name, amount in series_counts.items() if name not in WAIFU_REAL_SERIES)
    # Mostly photos, and not tied to a fictional franchise - a cosplay of Harley
    # Quinn still carries dc_comics and stays a character.
    if real_files >= max(1, count * 0.5) and fictional < count * 0.3:
        return "model"
    return "character"


def waifu_variant_base(tag: str, stats: dict) -> str:
    """The plain character an outfit/variant tag belongs to, or "".

    Booru tags split outfits into their own tags - iori_(swimsuit)_(blue_archive),
    shylily_(bikini) - which would otherwise each get their own card. A variant is
    only folded into a base that exists and shares its franchise, so rebecca_(cyberpunk)
    never merges into an unrelated plain "rebecca"."""
    candidates = []
    match = re.match(r"^(.+?)_\(([^()]+)\)_\(([^()]+)\)$", tag)
    if match:
        candidates.append(f"{match.group(1)}_({match.group(3)})")
    match = re.match(r"^(.+)_\(([^()]+)\)$", tag)
    if match:
        candidates.append(match.group(1))
    own = stats[tag]
    own_series = own["series"].most_common(1)
    for candidate in candidates:
        base = stats.get(candidate)
        if candidate == tag or base is None or base["cat"] != "character":
            continue
        if own_series and base["series"] and own_series[0][0] not in base["series"]:
            continue
        return candidate
    return ""


def build_waifu_index(folders: list[Path]) -> tuple[dict, dict]:
    """Every character, VTuber, artist and series found in the saved library's
    tag metadata, counting only files that still exist on disk.

    Returns (index, files): the index is what the page lists; files maps each
    subject to the files it appears in (best portrait candidates first), which
    is only needed by the picture picker and so is kept in a separate file."""
    signature = waifu_index_signature(folders)
    stats: dict[str, dict] = {}
    refs: dict[str, list] = collections.defaultdict(list)
    for folder_index, folder in enumerate(folders):
        present: set[str] = set()
        try:
            with os.scandir(folder) as iterator:
                for direntry in iterator:
                    if os.path.splitext(direntry.name)[1].lower() in MEDIA_EXTENSIONS:
                        present.add(direntry.name)
        except OSError:
            continue
        metadata = load_saved_metadata(folder)
        for name, meta in metadata.items():
            if not isinstance(meta, dict):
                continue
            base_name = os.path.basename(str(name))
            if base_name not in present:
                continue
            categories = meta.get("tag_categories")
            if not isinstance(categories, dict) or not categories:
                continue
            subjects = []
            series = []
            for tag, category in categories.items():
                if category == "general":
                    continue
                category = normalized_tag_category(str(category))
                if category in ("character", "artist", "series"):
                    tag = str(tag).lower()
                    subjects.append((tag, category))
                    if category == "series" and tag not in WAIFU_REAL_SERIES:
                        series.append(tag)
            if not subjects:
                continue
            tags = categories.keys()
            extension = os.path.splitext(base_name)[1].lower()
            character_count = sum(1 for _tag, category in subjects if category == "character")
            vtuber = bool(WAIFU_VTUBER_MARKER_TAGS.intersection(tags)) or any(
                category == "series" and tag.startswith(WAIFU_VTUBER_SERIES_PREFIXES) for tag, category in subjects
            )
            real = bool(WAIFU_REAL_MARKER_TAGS.intersection(tags)) or base_name.startswith("realbooru_")
            score = 0
            if extension in WAIFU_STILL_EXTENSIONS:
                score += 4
            elif extension in GIF_EXTENSIONS:
                score += 1
            if "solo" in categories:
                score += 4
            if character_count == 1:
                score += 3
            if WAIFU_PORTRAIT_TAGS.intersection(tags):
                score += 3
            if "looking_at_viewer" in categories:
                score += 2
            score += len(WAIFU_GOOD_PORTRAIT_TAGS.intersection(tags))
            score -= 5 * len(WAIFU_BAD_PORTRAIT_TAGS.intersection(tags))
            score -= 2 * len(WAIFU_WEAK_PORTRAIT_TAGS.intersection(tags))
            if "1boy" in categories and "1girl" in categories:
                score -= 3
            saved_at = str(meta.get("saved_at") or "")
            reference = (score, saved_at, folder_index, base_name)
            for tag, category in subjects:
                entry = stats.get(tag)
                if entry is None:
                    entry = stats[tag] = {
                        "cat": category, "vt": 0, "real": 0, "series": collections.Counter(),
                    }
                if category == "character":
                    entry["vt"] += vtuber
                    entry["real"] += real
                    entry["series"].update(series)
                refs[tag].append(reference)
    for tag, entry in stats.items():
        entry["count"] = len(refs[tag])
    # Fold outfit/variant tags into their base character (transitively).
    members: dict[str, list[str]] = {tag: [tag] for tag in stats}
    parent: dict[str, str] = {}
    for tag, entry in stats.items():
        if entry["cat"] == "character":
            base = waifu_variant_base(tag, stats)
            if base:
                parent[tag] = base
    for tag in list(parent):
        root, hops = parent[tag], 0
        while root in parent and hops < 8:
            root, hops = parent[root], hops + 1
        if root != tag:
            members[root].append(tag)
            members.pop(tag, None)
    subjects_out = []
    files_out: dict[str, list] = {}
    for tag, group in members.items():
        entry = stats[tag]
        if len(group) == 1:
            references = refs[tag]
            vt, real_count = entry["vt"], entry["real"]
            series_counts = entry["series"]
        else:
            unique: dict[tuple, tuple] = {}
            series_counts = collections.Counter()
            vt = real_count = 0
            for member in group:
                member_entry = stats[member]
                vt += member_entry["vt"]
                real_count += member_entry["real"]
                series_counts.update(member_entry["series"])
                for reference in refs[member]:
                    unique[(reference[2], reference[3])] = reference
            references = list(unique.values())
        count = len(references)
        raw_total = sum(stats[member]["count"] for member in group)
        scale = count / raw_total if raw_total else 1.0
        kind = waifu_subject_kind(tag, entry["cat"], count, int(vt * scale), int(real_count * scale), series_counts)
        references.sort(key=lambda item: (item[0], item[1]), reverse=True)
        folder_counts = [0] * len(folders)
        latest = ""
        for reference in references:
            folder_counts[reference[2]] += 1
            if reference[1] > latest:
                latest = reference[1]
        # Only franchises that make up a real share of this subject's files:
        # crossover fan art otherwise had Iori "from Blue Archive, Vocaloid,
        # Hololive" and made a search for hololive list her.
        series_top = []
        for name, amount in series_counts.most_common(3):
            if not series_top or amount >= max(2, count * 0.15):
                series_top.append(name)
        aliases = sorted(member for member in group if member != tag)
        display = waifu_prettify_tag(tag)
        subjects_out.append({
            "k": tag,
            "t": kind,
            "n": count,
            "f": folder_counts,
            "s": series_top,
            "a": aliases,
            "p": [[reference[2], reference[3]] for reference in references[:WAIFU_PORTRAIT_CANDIDATES]],
            "d": latest,
            # Precomputed here, in the builder process, so the app's reader
            # thread only has to parse - see WaifuIndexWorker.read_index().
            "nm": display,
            "sl": waifu_prettify_tag(series_top[0]) if series_top else "",
            "h": " ".join([tag, *series_top, *aliases]).replace("_", " ").lower(),
        })
        files_out[tag] = [[reference[2], reference[3]] for reference in references[:WAIFU_PICKER_FILE_LIMIT]]
    # Written in "Most images" order, with each subject's position in the other
    # two orders, so the app never sorts 65k records itself.
    subjects_out.sort(key=lambda subject: (-subject["n"], subject["nm"].lower()))
    for rank, subject in enumerate(sorted(subjects_out, key=lambda subject: subject["nm"].lower())):
        subject["r1"] = rank

    def saved_time(subject: dict) -> float:
        try:
            return float(subject["d"] or 0)
        except (TypeError, ValueError):
            return 0.0

    for rank, subject in enumerate(sorted(subjects_out, key=lambda subject: (-saved_time(subject), subject["nm"].lower()))):
        subject["r2"] = rank
    index = {
        "version": WAIFU_INDEX_VERSION,
        "signature": signature,
        "folders": [str(folder) for folder in folders],
        "built_at": time.time(),
        "subjects": subjects_out,
    }
    return index, {"version": WAIFU_INDEX_VERSION, "folders": index["folders"], "files": files_out}


def write_waifu_index(out_dir: Path, index: dict, files: dict):
    """Written as JSON Lines - a header line, then one subject per line - so the
    app can read it a line at a time. One json.loads() over the whole ~12MB
    would hold the GIL for ~200ms and stall the UI while the page opens."""
    out_dir.mkdir(parents=True, exist_ok=True)

    def write_lines(path: Path, lines):
        temp_path = path.with_name(path.name + ".tmp")
        with open(temp_path, "w", encoding="utf-8") as handle:
            for line in lines:
                handle.write(line)
                handle.write("\n")
        os.replace(temp_path, path)

    # files first: the app treats a new index file as "the build is finished".
    write_lines(
        out_dir / "files.jsonl",
        (json.dumps([key, refs], ensure_ascii=False) for key, refs in files["files"].items()),
    )
    header = {key: value for key, value in index.items() if key != "subjects"}
    header["count"] = len(index["subjects"])
    write_lines(
        out_dir / "index.jsonl",
        [json.dumps(header, ensure_ascii=False)]
        + [json.dumps(subject, ensure_ascii=False) for subject in index["subjects"]],
    )


def read_waifu_index_header(path: Path) -> dict | None:
    try:
        with open(path, encoding="utf-8") as handle:
            header = json.loads(handle.readline())
    except (OSError, ValueError):
        return None
    if not isinstance(header, dict) or header.get("version") != WAIFU_INDEX_VERSION:
        return None
    return header


def read_waifu_subject_files(path: Path, key: str) -> list:
    """One subject's file list, parsing only its own line."""
    prefix = json.dumps([key], ensure_ascii=False)[:-1] + ","
    try:
        with open(path, encoding="utf-8") as handle:
            for line in handle:
                if line.startswith(prefix):
                    value = json.loads(line)
                    return value[1] if isinstance(value, list) and len(value) == 2 else []
    except (OSError, ValueError):
        pass
    return []


def waifu_index_cli(argv: list[str]) -> int:
    """Entry point for `DistantViewer.py --build-waifu-index <out_dir> <folder>...`.

    Parsing ~190MB of saved metadata takes a few seconds, and json.loads never
    releases the GIL - on a thread in the app it would freeze the UI for all of
    it. A child process has its own GIL, so the app stays fully responsive."""
    try:
        position = argv.index("--build-waifu-index")
        out_dir = Path(argv[position + 1])
        folders = [Path(value) for value in argv[position + 2:]]
    except (ValueError, IndexError):
        return 2
    started = time.monotonic()
    try:
        index, files = build_waifu_index(folders)
        write_waifu_index(out_dir, index, files)
    except Exception as exc:
        write_app_log(f"waifu index build failed error={exc!r}\n{traceback.format_exc()}")
        return 1
    write_app_log(
        f"waifu index built subjects={len(index['subjects'])} seconds={time.monotonic() - started:.1f}"
    )
    return 0


def waifu_index_command(out_dir: Path, folders: list[Path]) -> list[str]:
    script = running_script_path()
    command = [sys.executable]
    if script is not None:
        command.append(str(script))
    return [*command, "--build-waifu-index", str(out_dir), *[str(folder) for folder in folders]]


# --- portraits ----------------------------------------------------------------

def waifu_video_frame(source: Path) -> Image.Image | None:
    """One full-size frame ~30% into a video, for videos-only subjects."""
    cv2 = optional_module("cv2")
    if cv2 is not None:
        capture = None
        try:
            with CV2_VIDEO_DECODE_LOCK:
                capture = cv2.VideoCapture(str(source))
                if capture.isOpened():
                    total = int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
                    if total > 0:
                        capture.set(cv2.CAP_PROP_POS_FRAMES, max(0, min(total - 1, int(total * 0.3))))
                    ok, frame = capture.read()
                    if ok and frame is not None:
                        return Image.fromarray(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB))
        except Exception:
            pass
        finally:
            if capture is not None:
                try:
                    capture.release()
                except Exception:
                    pass
    return windows_shell_thumbnail(source)


def waifu_open_source_image(source: Path, crop: list | None = None, target_side: int = 0) -> Image.Image | None:
    """RGB image for a portrait source - a still, a GIF's first frame, or a
    video frame. With target_side, JPEGs are decoded at a reduced scale that is
    still large enough for the crop, which is most of the cost on big files."""
    if media_type(source) == "video":
        return waifu_video_frame(source)
    image = Image.open(source)
    if target_side and image.format == "JPEG":
        fraction = max(0.05, float(crop[2])) if crop else 1.0
        wanted = int(target_side / fraction) + 1
        image.draft("RGB", (wanted, wanted))
    image = ImageOps.exif_transpose(image)
    if getattr(image, "is_animated", False):
        image.seek(0)
    return image.convert("RGB")


def waifu_auto_crop(width: int, height: int) -> list[float]:
    """A square that keeps the face in frame for typical booru art: portrait-
    orientation images have the head near the top, landscape ones centred."""
    width, height = max(1, int(width)), max(1, int(height))
    if height > width * 1.05:
        side = width
        x0 = 0
        if height > width * 1.6:
            # Tall full-body shots: a slightly tighter square around the top.
            side = int(width * 0.82)
            x0 = (width - side) // 2
        y0 = int(min(height - side, height * 0.03))
    else:
        side = height
        x0 = (width - side) // 2
        y0 = 0
    return [x0 / width, y0 / height, side / width, side / height]


def waifu_crop_box(crop: list | None, width: int, height: int) -> tuple[int, int, int, int]:
    if not crop or len(crop) != 4:
        crop = waifu_auto_crop(width, height)
    x0 = int(round(float(crop[0]) * width))
    y0 = int(round(float(crop[1]) * height))
    side = int(round(float(crop[2]) * width))
    side = max(8, min(side, width, height))
    x0 = max(0, min(x0, width - side))
    y0 = max(0, min(y0, height - side))
    return x0, y0, x0 + side, y0 + side


def waifu_portrait_cache_path(source: Path, crop: list | None, side: int) -> Path | None:
    try:
        stat = source.stat()
    except OSError:
        return None
    crop_key = ",".join(f"{float(value):.5f}" for value in crop) if crop else "auto"
    raw = f"{WAIFU_PORTRAIT_VERSION}|{side}|{source}|{stat.st_mtime_ns}|{stat.st_size}|{crop_key}"
    return waifu_portrait_folder() / f"{hashlib.sha1(raw.encode('utf-8', errors='ignore')).hexdigest()}.jpg"


def render_waifu_portrait(source: Path, crop: list | None, side: int) -> Path | None:
    """Cropped square portrait for `source`, rendered once and then served from
    the on-disk cache. Returns None if the file is gone or cannot be decoded."""
    destination = waifu_portrait_cache_path(source, crop, side)
    if destination is None:
        return None
    if destination.exists():
        return destination
    image = waifu_open_source_image(source, crop, side)
    if image is None:
        return None
    box = waifu_crop_box(crop, image.width, image.height)
    portrait = image.crop(box).resize((side, side), Image.Resampling.LANCZOS)
    temp_path = destination.with_name(destination.name + f".{threading.get_ident()}.tmp")
    portrait.save(temp_path, "JPEG", quality=88)
    os.replace(temp_path, destination)
    return destination


def prune_waifu_portraits(limit: int = WAIFU_PORTRAIT_CACHE_MAX_FILES):
    """Keep the portrait cache bounded - oldest renders go first."""
    try:
        with os.scandir(waifu_portrait_folder()) as iterator:
            files = [(entry.stat().st_mtime, entry.path) for entry in iterator if entry.is_file()]
    except OSError:
        return
    if len(files) <= limit:
        return
    files.sort()
    for _mtime, path in files[: len(files) - int(limit * 0.8)]:
        try:
            os.remove(path)
        except OSError:
            pass


# --- web profile lookup -------------------------------------------------------

WAIFU_WEB_USER_AGENT = f"DistantViewer/{APP_VERSION} (personal media browser; profile lookup)"
WAIFU_WEB_TIMEOUT = 15
# Profile facts pulled to the top of the info panel, in display order. Matched
# against each wiki row's id and visible label, since every wiki names these
# differently ("threesizes", "measurements", "3sizes"...).
WAIFU_BODY_FIELD_PATTERNS = [
    ("Height", r"\bheight\b"),
    ("Weight", r"\bweight\b"),
    ("Measurements", r"measurement|three ?sizes?|\b3 ?sizes?\b|\bbwh\b|b/w/h"),
    ("Bust", r"\bbust\b|\bcup size\b"),
    ("Age", r"\bage\b"),
    ("Birthday", r"birthday|birthdate|birth date|date of birth|\bborn\b|\bdob\b"),
    ("Gender", r"\bgender\b|\bsex\b"),
    ("Species", r"\bspecies\b|\brace\b"),
    ("Hair", r"\bhair\b"),
    ("Eyes", r"\beyes?\b"),
    ("Blood type", r"\bblood"),
]
WAIFU_LORE_SECTIONS = (
    "appearance", "personality", "background", "biography", "history", "story", "lore",
    "profile", "overview", "plot", "abilities", "powers", "trivia", "characteristics",
)
WAIFU_LORE_MAX_PARAGRAPHS = 4
# Collapsed info panel: how much lore / how many detail rows show before "Show more".
WAIFU_LORE_PREVIEW_CHARS = 320
WAIFU_DETAILS_PREVIEW_ROWS = 5
WAIFU_LORE_SECTION_LIMIT = 6
WAIFU_DETAIL_FIELD_LIMIT = 24
WAIFU_ANILIST_CHARACTER_QUERY = (
    "query($s:String){Page(perPage:8){characters(search:$s){name{full native alternative} age gender "
    "dateOfBirth{year month day} bloodType description siteUrl media(perPage:6){nodes{title{romaji english}}}}}}"
)
WAIFU_ANILIST_MEDIA_QUERY = (
    "query($s:String){Media(search:$s){title{romaji english} description format startDate{year} "
    "episodes chapters genres siteUrl}}"
)
WAIFU_SERIES_WORD_STOPLIST = frozenset({"the", "no", "series", "game", "anime", "manga", "of", "and", "a", "wo", "ga", "wa"})


def waifu_http_json(url: str, payload: dict | None = None, timeout: int = WAIFU_WEB_TIMEOUT):
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    headers = {"User-Agent": WAIFU_WEB_USER_AGENT, "Accept": "application/json"}
    if data is not None:
        headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=headers)
    with urllib.request.urlopen(request, timeout=timeout) as response:
        text = response.read().decode("utf-8", errors="replace").strip()
    if not text or text[0] not in "[{":
        raise ValueError("not JSON")
    return json.loads(text)


def waifu_tidy_text(value: str) -> str:
    value = str(value).replace("\xa0", " ")
    value = re.sub(r"[ \t\r\f\v]+", " ", value)
    value = re.sub(r" *\n *", "\n", value)
    value = re.sub(r"\s+([,.;:!?)\]])", r"\1", value)
    value = re.sub(r"([(\[])\s+", r"\1", value)
    return value.strip(" ;\n")


def danbooru_dtext_to_text(body: str, limit: int = 2400) -> str:
    """Danbooru wiki markup -> plain paragraphs. Keeps the prose, drops the
    costume/post galleries and the external-links block."""
    text = str(body).replace("\r\n", "\n")
    text = re.split(
        r"\nh[1-6]\.\s*(?:external links|see also|costumes?|outfits?|skins?|gallery|posts|official art|appearance\s*\n\s*\*\s*!)",
        text,
        flags=re.IGNORECASE,
    )[0]
    text = re.sub(r"^\s*\*+\s*!(?:post|asset) #\d+.*$", "", text, flags=re.MULTILINE)
    text = re.sub(r"^\s*!(?:post|asset) #\d+.*$", "", text, flags=re.MULTILINE)
    text = re.sub(r"\[\[([^\]|]+)\|([^\]]+)\]\]", r"\2", text)
    text = re.sub(r"\[\[([^\]|]+)\|\]\]", lambda match: re.sub(r"\s*\([^)]*\)$", "", match.group(1)), text)
    text = re.sub(r"\[\[([^\]]+)\]\]", r"\1", text)
    text = re.sub(r"\{\{([^}|]+)(?:\|([^}]+))?\}\}", lambda match: match.group(2) or match.group(1), text)
    text = re.sub(r'"([^"]+)":\s*\[?(https?://[^\s\]]+)\]?', r"\1", text)
    text = re.sub(r"\[/?(?:b|i|u|s|tn|spoilers?|quote|expand[^\]]*|code|nodtext|section[^\]]*)\]", "", text, flags=re.IGNORECASE)
    text = re.sub(r"^h[1-6]\.\s*", "", text, flags=re.MULTILINE)
    text = re.sub(r"^\*+\s*", "• ", text, flags=re.MULTILINE)
    paragraphs = [waifu_tidy_text(part) for part in re.split(r"\n\s*\n", text)]
    out, used = [], 0
    for paragraph in paragraphs:
        if not paragraph:
            continue
        if used + len(paragraph) > limit and out:
            break
        out.append(paragraph)
        used += len(paragraph)
    return "\n\n".join(out)


class FandomPageParser(HTMLParser):
    """Pulls the portable infobox and the prose paragraphs (grouped under their
    section headings) out of a rendered MediaWiki/Fandom page. Works on the
    standard Fandom "portable infobox" markup, which is what nearly every
    character wiki uses - including the horizontal "smart" rows Genshin uses."""

    SKIP_TAGS = {"sup", "style", "script", "table", "figure", "noscript", "math"}
    SKIP_CLASS_WORDS = (
        "quote", "navbox", "toc", "notice", "reference", "mw-editsection", "gallery", "caption",
        "hatnote", "dablink", "audio", "mw-ext-",
    )
    VOID_TAGS = {"br", "img", "hr", "meta", "link", "input", "wbr", "source", "col", "area", "base", "embed", "param", "track"}

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._labels: dict[str, str] = {}
        self._values: dict[str, str] = {}
        self._order: list[str] = []
        self.infobox_title = ""
        self.sections: list[tuple[str, list[str]]] = [("", [])]
        self._stack: list[tuple[str, str]] = []
        self._skip_depth = 0
        self._capture: list[str] | None = None
        self._capture_role = ""
        self._capture_source = ""
        self._capture_depth = 0
        self._aside_depth = 0
        self._source_stack: list[str] = []

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        classes = (attributes.get("class") or "").lower()
        if tag in self.VOID_TAGS:
            if tag == "br" and self._capture is not None:
                self._capture.append("\n")
            return
        if self._skip_depth:
            self._skip_depth += 1
            self._stack.append((tag, "skip"))
            return
        role = ""
        in_aside = self._aside_depth > 0
        if tag == "aside" and "portable-infobox" in classes:
            self._aside_depth += 1
            role = "aside"
        elif tag == "sup" or (not in_aside and (tag in self.SKIP_TAGS or any(word in classes for word in self.SKIP_CLASS_WORDS))):
            self._skip_depth = 1
            self._stack.append((tag, "skip"))
            return
        source = attributes.get("data-source") or ""
        if self._aside_depth and source:
            self._source_stack.append(source)
            role = role or "source"
        in_aside = self._aside_depth > 0
        if self._capture is None:
            current_source = source or (self._source_stack[-1] if self._source_stack else "")
            if in_aside and tag in {"h2", "h3"} and "pi-title" in classes:
                self._begin("title", "")
            elif in_aside and tag == "h3" and "pi-data-label" in classes:
                self._begin("label", current_source)
            elif in_aside and "pi-data-value" in classes:
                self._begin("value", current_source)
            elif not in_aside and tag in {"h2", "h3"}:
                self._begin("heading", tag)
            elif not in_aside and tag == "p":
                self._begin("para", "")
            elif not in_aside and tag == "li" and self.sections[-1][0]:
                self._begin("para", "li")
        else:
            self._capture_depth += 1
            if tag in {"p", "div", "li"} and self._capture_role == "value":
                self._capture.append("\n")
        self._stack.append((tag, role))

    def _begin(self, role: str, source: str):
        self._capture = []
        self._capture_role = role
        self._capture_source = source
        self._capture_depth = 1

    def handle_endtag(self, tag):
        if tag in self.VOID_TAGS:
            return
        if not any(open_tag == tag for open_tag, _role in self._stack):
            return
        while self._stack:
            open_tag, role = self._stack.pop()
            if role == "skip":
                self._skip_depth = max(0, self._skip_depth - 1)
            else:
                if self._capture is not None:
                    self._capture_depth -= 1
                    if self._capture_depth <= 0:
                        self._finish()
                if role == "source" and self._source_stack:
                    self._source_stack.pop()
                if role == "aside":
                    self._aside_depth = max(0, self._aside_depth - 1)
            if open_tag == tag:
                break

    def handle_data(self, data):
        if self._skip_depth or self._capture is None:
            return
        self._capture.append(data)

    def _finish(self):
        text = waifu_tidy_text("".join(self._capture or []))
        role, source = self._capture_role, self._capture_source
        self._capture = None
        if role == "title":
            self.infobox_title = self.infobox_title or text.split("\n")[0].strip()
        elif role == "label" and source:
            self._labels.setdefault(source, text.replace("­", ""))
            if source not in self._order:
                self._order.append(source)
        elif role == "value" and source:
            if text and source not in self._values:
                self._values[source] = re.sub(r"(;\s*)+", "; ", text.replace("\n", "; ")).strip("; ")
                if source not in self._order:
                    self._order.append(source)
        elif role == "heading":
            heading = re.sub(r"\[\s*edit\s*\]", "", text, flags=re.IGNORECASE).strip()
            if heading:
                self.sections.append((heading, []))
        elif role == "para":
            if re.match(r"^https?://\S+$", text):
                return
            if len(text) >= 40 or (source == "li" and len(text) >= 12):
                self.sections[-1][1].append(("• " if source == "li" else "") + text)

    def result(self) -> dict:
        fields = []
        for source in self._order:
            value = self._values.get(source, "")
            if not value:
                continue
            label = self._labels.get(source) or source.replace("_", " ").title()
            fields.append({"source": source, "label": label, "value": value})
        return {"title": self.infobox_title, "fields": fields, "sections": self.sections}


def parse_fandom_page(html_text: str) -> dict:
    parser = FandomPageParser()
    try:
        parser.feed(html_text)
        parser.close()
    except Exception:
        pass
    return parser.result()


def waifu_split_fields(fields: list[dict]) -> tuple[list[dict], list[dict]]:
    """Separate the body/profile facts (height, measurements...) from the rest."""
    body: list[dict] = []
    used: set[int] = set()
    for label, pattern in WAIFU_BODY_FIELD_PATTERNS:
        for index, field in enumerate(fields):
            if index in used:
                continue
            haystack = f"{field['source']} {field['label']}".lower().replace("_", " ")
            if re.search(pattern, haystack):
                body.append({"label": label, "value": field["value"]})
                used.add(index)
                break
    rest = []
    for index, field in enumerate(fields):
        if index in used:
            continue
        # Game-stat rows (Hp1, Atk100...) are noise in a character profile.
        if re.fullmatch(r"[A-Za-z]{1,5}\d+", field["label"].strip()) or len(field["label"]) > 48:
            continue
        rest.append({"label": field["label"], "value": field["value"]})
    return body, rest[:WAIFU_DETAIL_FIELD_LIMIT]


def waifu_lore_from_sections(sections: list, limit: int = WAIFU_LORE_SECTION_LIMIT) -> list[dict]:
    lore: list[dict] = []
    intro = [text for text in sections[0][1] if not text.startswith("•")] if sections else []
    if intro:
        lore.append({"heading": "", "paragraphs": intro[:WAIFU_LORE_MAX_PARAGRAPHS]})
    for heading, paragraphs in sections[1:]:
        if len(lore) >= limit:
            break
        key = heading.lower().strip()
        if not paragraphs or not any(key == name or key.startswith(name) for name in WAIFU_LORE_SECTIONS):
            continue
        lore.append({"heading": heading, "paragraphs": paragraphs[:WAIFU_LORE_MAX_PARAGRAPHS]})
    return lore


def waifu_names_match(candidate: str, names: list[str]) -> bool:
    candidate_tokens = set(waifu_fold(candidate).split())
    if not candidate_tokens:
        return False
    for name in names:
        tokens = set(waifu_fold(name).split())
        if tokens and (tokens <= candidate_tokens or candidate_tokens <= tokens):
            return True
    return False


def waifu_fandom_page(wiki: str, title: str) -> dict | None:
    query = urllib.parse.urlencode({
        "action": "parse", "page": title, "prop": "text", "redirects": 1, "format": "json",
        "disableeditsection": 1, "disabletoc": 1,
    })
    data = waifu_http_json(f"https://{wiki}.fandom.com/api.php?{query}")
    parse = data.get("parse") if isinstance(data, dict) else None
    if not isinstance(parse, dict):
        return None
    html_text = (parse.get("text") or {}).get("*") or ""
    page = parse_fandom_page(html_text)
    page_title = str(parse.get("title") or title)
    page["page_title"] = page_title
    page["url"] = f"https://{wiki}.fandom.com/wiki/{urllib.parse.quote(page_title.replace(' ', '_'))}"
    return page


def waifu_fandom_search(wiki: str, query: str) -> list[str]:
    params = urllib.parse.urlencode({
        "action": "query", "list": "search", "srsearch": query, "srlimit": 8, "srnamespace": 0, "format": "json",
    })
    data = waifu_http_json(f"https://{wiki}.fandom.com/api.php?{params}")
    hits = ((data or {}).get("query") or {}).get("search") or []
    return [str(hit.get("title") or "") for hit in hits if hit.get("title")]


def waifu_fandom_pick(wiki: str, names: list[str]) -> str:
    """The wiki page for a character, or "". Subpages (Name/Gallery) are
    skipped, and an exact name match beats a partial one - searching "Mita"
    must land on Mita, not on the first page that merely mentions her
    ("Short-haired Mita")."""
    name_sets = [set(waifu_fold(name).split()) for name in names if waifu_fold(name)]
    if not name_sets:
        return ""

    def rank(title: str):
        tokens = set(waifu_fold(title).split())
        if not tokens:
            return None
        if any(tokens == name for name in name_sets):
            return 0
        if any(tokens <= name for name in name_sets):
            return 1                      # "Cammy" for "Cammy White"
        extra = [len(tokens - name) for name in name_sets if name <= tokens]
        return 2 + min(extra) if extra else None   # "Shiromi Iori" for "Iori"

    for query in names[:2]:
        try:
            titles = waifu_fandom_search(wiki, query)
        except Exception:
            return ""
        ranked = []
        for position, title in enumerate(titles):
            if "/" in title:
                continue
            score = rank(title)
            if score is not None:
                ranked.append((score, position, title))
        if ranked:
            return min(ranked)[2]
    return ""


def waifu_guess_wikis(series_tag: str) -> list[str]:
    base = re.sub(r"_\((?:series|game|video_game|anime|manga|franchise|copyright)\)$", "", series_tag.lower())
    candidates = []
    for variant in (base, base.split(":")[0], re.sub(r"_?\d+$", "", base.split(":")[0])):
        words = [word for word in re.split(r"[^a-z0-9]+", variant) if word]
        if not words:
            continue
        for candidate in ("".join(words), "-".join(words)):
            if candidate and candidate not in candidates:
                candidates.append(candidate)
    return candidates


def waifu_wiki_exists(wiki: str) -> bool:
    try:
        data = waifu_http_json(f"https://{wiki}.fandom.com/api.php?action=query&meta=siteinfo&format=json", timeout=8)
    except Exception:
        return False
    return isinstance(data, dict) and "query" in data


def waifu_wiki_for_series(series_tag: str, wiki_cache: dict) -> str:
    """The Fandom wiki for a franchise, found once and remembered (including
    "no wiki"): the franchise's own Danbooru wiki links first, then names
    guessed from the tag, then its English title from AniList."""
    if series_tag in wiki_cache:
        return wiki_cache[series_tag]
    candidates: list[str] = []
    try:
        page = waifu_http_json(f"https://danbooru.donmai.us/wiki_pages/{urllib.parse.quote(series_tag)}.json")
        for match in re.finditer(r"https?://([a-z0-9-]+)\.fandom\.com", str(page.get("body") or "")):
            if match.group(1) not in candidates:
                candidates.append(match.group(1))
    except Exception:
        pass
    candidates.extend(candidate for candidate in waifu_guess_wikis(series_tag) if candidate not in candidates)
    for wiki in candidates[:6]:
        if waifu_wiki_exists(wiki):
            wiki_cache[series_tag] = wiki
            return wiki
    try:
        media = waifu_anilist_media(series_tag)
    except Exception:
        media = None
    if media:
        english = ((media.get("title") or {}).get("english") or "").lower()
        words = [word for word in re.split(r"[^a-z0-9]+", english) if word]
        for wiki in ("".join(words), "-".join(words)):
            if wiki and wiki not in candidates and waifu_wiki_exists(wiki):
                wiki_cache[series_tag] = wiki
                return wiki
    wiki_cache[series_tag] = ""
    return ""


def waifu_series_tokens(series_tags: list[str]) -> set[str]:
    tokens = set()
    for tag in series_tags:
        for word in waifu_fold(re.sub(r"_\([^()]*\)$", "", tag).replace("_", " ")).split():
            if len(word) >= 3 and word not in WAIFU_SERIES_WORD_STOPLIST:
                tokens.add(word)
    return tokens


def waifu_anilist_markdown(text: str) -> str:
    text = re.sub(r"~!.*?!~", "", str(text), flags=re.DOTALL)          # spoilers
    text = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", text)                    # images
    text = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", text)                # links
    text = re.sub(r"<br\s*/?>", "\n", text, flags=re.IGNORECASE)
    text = re.sub(r"<[^>]+>", "", text)
    text = text.replace("__", "").replace("**", "")
    return unescape(text)


def waifu_anilist_character(names: list[str], series_tags: list[str]) -> dict | None:
    data = waifu_http_json(
        "https://graphql.anilist.co",
        {"query": WAIFU_ANILIST_CHARACTER_QUERY, "variables": {"s": names[0]}},
    )
    characters = (((data or {}).get("data") or {}).get("Page") or {}).get("characters") or []
    series_tokens = waifu_series_tokens(series_tags)
    for character in characters:
        name = character.get("name") or {}
        candidates = [name.get("full") or ""] + list(name.get("alternative") or [])
        if not any(waifu_names_match(candidate, names) for candidate in candidates if candidate):
            continue
        if series_tokens:
            titles = " ".join(
                f"{(node.get('title') or {}).get('romaji') or ''} {(node.get('title') or {}).get('english') or ''}"
                for node in ((character.get("media") or {}).get("nodes") or [])
            )
            if not series_tokens & set(waifu_fold(titles).split()):
                continue
        return character
    return None


def waifu_anilist_media(series_tag: str) -> dict | None:
    query = waifu_prettify_tag(re.sub(r"_\((?:series|game|anime|manga)\)$", "", series_tag))
    data = waifu_http_json(
        "https://graphql.anilist.co", {"query": WAIFU_ANILIST_MEDIA_QUERY, "variables": {"s": query}}
    )
    media = ((data or {}).get("data") or {}).get("Media")
    if not isinstance(media, dict):
        return None
    titles = f"{(media.get('title') or {}).get('romaji') or ''} {(media.get('title') or {}).get('english') or ''}"
    if not waifu_series_tokens([series_tag]) & set(waifu_fold(titles).split()):
        return None
    return media


def waifu_anilist_profile_parts(character: dict) -> tuple[list[dict], list[str]]:
    """AniList puts facts at the top of the description as "__Height:__ 157 cm"
    lines; split those out from the prose."""
    fields: list[dict] = []
    prose: list[str] = []
    description = str(character.get("description") or "")
    for line in description.split("\n"):
        match = re.match(r"^\s*__([^_]{1,40}?):?__:?\s*(.+)$", line)
        if match:
            fields.append({"source": match.group(1), "label": match.group(1).strip(), "value": waifu_anilist_markdown(match.group(2)).strip()})
    body_text = "\n".join(line for line in description.split("\n") if not re.match(r"^\s*__[^_]{1,40}?:?__", line))
    for paragraph in re.split(r"\n\s*\n", waifu_anilist_markdown(body_text)):
        paragraph = waifu_tidy_text(paragraph)
        if len(paragraph) >= 30:
            prose.append(paragraph)
    if character.get("age"):
        fields.append({"source": "age", "label": "Age", "value": str(character["age"]).rstrip("-")})
    if character.get("gender"):
        fields.append({"source": "gender", "label": "Gender", "value": str(character["gender"])})
    birth = character.get("dateOfBirth") or {}
    if birth.get("month") and birth.get("day"):
        month = datetime.date(2000, int(birth["month"]), 1).strftime("%B")
        fields.append({"source": "birthday", "label": "Birthday", "value": f"{month} {int(birth['day'])}" + (f", {birth['year']}" if birth.get("year") else "")})
    if character.get("bloodType"):
        fields.append({"source": "blood", "label": "Blood type", "value": str(character["bloodType"])})
    return fields, prose


def waifu_add_body_fields(profile: dict, fields: list[dict]):
    body, rest = waifu_split_fields(fields)
    have = {field["label"] for field in profile["body"]}
    for field in body:
        if field["label"] not in have:
            profile["body"].append(field)
            have.add(field["label"])
    order = [label for label, _pattern in WAIFU_BODY_FIELD_PATTERNS]
    profile["body"].sort(key=lambda field: order.index(field["label"]) if field["label"] in order else len(order))
    if not profile["details"]:
        profile["details"] = rest


def fetch_waifu_profile(subject: dict, wiki_cache: dict) -> dict:
    """Everything the web knows about one subject, from (in order of trust):
    the franchise's Fandom wiki (infobox facts + lore sections), the Danbooru
    wiki for the exact tag, AniList, and Wikipedia. Each source is optional -
    whatever answers is used, and a source failing never fails the lookup."""
    key = str(subject.get("k") or "")
    kind = str(subject.get("t") or "character")
    series_tags = [str(tag) for tag in subject.get("s") or []]
    display = waifu_prettify_tag(key)
    profile = {
        "key": key, "name": display, "other_names": [], "body": [], "details": [], "lore": [],
        "links": [], "sources": [], "fetched_at": time.time(), "version": WAIFU_WEB_CACHE_VERSION,
    }
    quoted = urllib.parse.quote(key)
    danbooru_lore: list[str] = []
    fandom_targets: list[tuple[str, str]] = []
    wikipedia_title = ""
    try:
        wiki_page = waifu_http_json(f"https://danbooru.donmai.us/wiki_pages/{quoted}.json")
    except Exception:
        wiki_page = None
    if isinstance(wiki_page, dict) and wiki_page.get("body"):
        body = str(wiki_page["body"])
        profile["sources"].append({"label": "Danbooru wiki", "url": f"https://danbooru.donmai.us/wiki_pages/{quoted}"})
        profile["other_names"] = [str(name).replace("_", " ") for name in wiki_page.get("other_names") or [] if name][:14]
        for label, url in re.findall(r'"([^"]+)":\s*\[?(https?://[^\s\]"]+)', body):
            profile["links"].append({"label": label, "url": url})
            fandom = re.match(r"https?://([a-z0-9-]+)\.fandom\.com/wiki/([^?#]+)", url)
            if fandom:
                fandom_targets.append((fandom.group(1), urllib.parse.unquote(fandom.group(2)).replace("_", " ")))
            wikipedia = re.match(r"https?://en\.wikipedia\.org/wiki/([^?#]+)", url)
            if wikipedia and not wikipedia_title:
                wikipedia_title = urllib.parse.unquote(wikipedia.group(1))
        danbooru_lore = [part for part in danbooru_dtext_to_text(body).split("\n\n") if part]
    if kind == "artist":
        try:
            artists = waifu_http_json(
                f"https://danbooru.donmai.us/artists.json?search[name]={quoted}&only=name,other_names,group_name,is_banned,urls"
            )
        except Exception:
            artists = None
        if isinstance(artists, list) and artists and isinstance(artists[0], dict):
            artist = artists[0]
            names = [str(name).replace("_", " ") for name in artist.get("other_names") or [] if name]
            profile["other_names"] = list(dict.fromkeys(profile["other_names"] + names))[:14]
            if artist.get("group_name"):
                profile["details"].append({"label": "Group", "value": str(artist["group_name"]).replace("_", " ")})
            seen = {link["url"] for link in profile["links"]}
            for url_entry in artist.get("urls") or []:
                url = str(url_entry.get("url") or "")
                if url and url_entry.get("is_active", True) and url not in seen:
                    domain = urllib.parse.urlparse(url).netloc.replace("www.", "")
                    profile["links"].append({"label": domain or url, "url": url})
                    seen.add(url)
            profile["sources"].append({"label": "Danbooru artist entry", "url": f"https://danbooru.donmai.us/artists?search[name]={quoted}"})
        if danbooru_lore:
            profile["lore"] = [{"heading": "", "paragraphs": danbooru_lore[:8]}]
        return profile
    if kind == "series":
        try:
            media = waifu_anilist_media(key)
        except Exception:
            media = None
        if media:
            title = media.get("title") or {}
            profile["name"] = title.get("english") or title.get("romaji") or display
            for label, value in (
                ("Format", media.get("format")),
                ("Year", (media.get("startDate") or {}).get("year")),
                ("Episodes", media.get("episodes")),
                ("Chapters", media.get("chapters")),
                ("Genres", ", ".join(media.get("genres") or [])),
            ):
                if value:
                    profile["details"].append({"label": label, "value": str(value).replace("_", " ").title() if label == "Format" else str(value)})
            prose = [waifu_tidy_text(part) for part in re.split(r"\n\s*\n", waifu_anilist_markdown(media.get("description") or ""))]
            prose = [part for part in prose if len(part) >= 30]
            if prose:
                profile["lore"].append({"heading": "", "paragraphs": prose[:WAIFU_LORE_MAX_PARAGRAPHS]})
            if media.get("siteUrl"):
                profile["sources"].append({"label": "AniList", "url": media["siteUrl"]})
        if danbooru_lore:
            profile["lore"].append({"heading": "From the Danbooru wiki" if profile["lore"] else "", "paragraphs": danbooru_lore[:6]})
        return profile
    # Characters, VTubers, real people.
    names = [display]
    for other in profile["other_names"]:
        if re.fullmatch(r"[A-Za-z0-9 .'\-]+", other) and other.lower() != display.lower() and len(names) < 4:
            names.append(other)
    page = None
    for wiki, title in fandom_targets[:2]:
        try:
            page = waifu_fandom_page(wiki, title)
        except Exception:
            page = None
        if page and (page["fields"] or any(paragraphs for _heading, paragraphs in page["sections"])):
            page["wiki"] = wiki
            break
        page = None
    if page is None and kind != "model":
        wikis = ["virtualyoutuber"] if kind == "vtuber" else []
        for series_tag in series_tags[:2]:
            try:
                wiki = waifu_wiki_for_series(series_tag, wiki_cache)
            except Exception:
                wiki = ""
            if wiki and wiki not in wikis:
                wikis.append(wiki)
        for wiki in wikis:
            title = waifu_fandom_pick(wiki, names)
            if not title:
                continue
            try:
                page = waifu_fandom_page(wiki, title)
            except Exception:
                page = None
            if page:
                page["wiki"] = wiki
                break
    if page:
        infobox_title = page.get("title") or ""
        profile["name"] = infobox_title if infobox_title and waifu_names_match(infobox_title, names + [page["page_title"]]) else page["page_title"]
        body, rest = waifu_split_fields(page["fields"])
        profile["body"], profile["details"] = body, rest
        profile["lore"] = waifu_lore_from_sections(page["sections"])
        if len(profile["lore"]) <= 1:
            # Game wikis (Genshin, Honkai, ZZZ...) keep the story on a subpage.
            for subpage in ("Lore", "Story"):
                try:
                    extra = waifu_fandom_page(page["wiki"], f"{page['page_title']}/{subpage}")
                except Exception:
                    extra = None
                if not extra:
                    continue
                extra_lore = [
                    {"heading": heading, "paragraphs": paragraphs[:WAIFU_LORE_MAX_PARAGRAPHS]}
                    for heading, paragraphs in extra["sections"]
                    if paragraphs and heading
                ][:WAIFU_LORE_SECTION_LIMIT]
                if extra_lore:
                    profile["lore"].extend(extra_lore)
                    break
        profile["sources"].insert(0, {"label": f"{page['wiki']} wiki (Fandom)", "url": page["url"]})
    if kind == "character" and (not profile["body"] or not profile["lore"]):
        try:
            character = waifu_anilist_character(names, series_tags)
        except Exception:
            character = None
        if character:
            fields, prose = waifu_anilist_profile_parts(character)
            waifu_add_body_fields(profile, fields)
            if not profile["lore"] and prose:
                profile["lore"] = [{"heading": "", "paragraphs": prose[:WAIFU_LORE_MAX_PARAGRAPHS + 2]}]
            if not page and (character.get("name") or {}).get("full"):
                profile["name"] = character["name"]["full"]
            if character.get("siteUrl"):
                profile["sources"].append({"label": "AniList", "url": character["siteUrl"]})
    if not profile["lore"] and wikipedia_title:
        try:
            summary = waifu_http_json(f"https://en.wikipedia.org/api/rest_v1/page/summary/{urllib.parse.quote(wikipedia_title)}")
        except Exception:
            summary = None
        if isinstance(summary, dict) and summary.get("extract"):
            profile["lore"] = [{"heading": "", "paragraphs": [waifu_tidy_text(summary["extract"])]}]
            profile["sources"].append({"label": "Wikipedia", "url": f"https://en.wikipedia.org/wiki/{urllib.parse.quote(wikipedia_title)}"})
    if danbooru_lore:
        if not profile["lore"]:
            profile["lore"] = [{"heading": "", "paragraphs": danbooru_lore[:6]}]
        elif len(profile["lore"]) <= 2:
            profile["lore"].append({"heading": "From the Danbooru wiki", "paragraphs": danbooru_lore[:3]})
    return profile


class VideoStreamProxy:
    def __init__(self):
        self.entries: dict[str, dict] = {}
        self.lock = threading.Lock()
        self.server = ThreadingHTTPServer(("127.0.0.1", 0), self._handler_class())
        self.server.daemon_threads = True
        self.server.proxy_service = self
        self.thread = threading.Thread(target=self.server.serve_forever, name="DistantViewerVideoStream", daemon=True)
        self.thread.start()
        write_app_log(f"video stream bridge started port={self.server.server_port}")

    @staticmethod
    def _handler_class():
        class StreamHandler(BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.1"

            def log_message(self, _format, *_args):
                return

            def do_HEAD(self):
                self.serve_media(send_body=False)

            def do_GET(self):
                self.serve_media(send_body=True)

            def serve_media(self, send_body: bool):
                service = self.server.proxy_service
                token = urllib.parse.urlparse(self.path).path.rsplit("/", 1)[-1]
                with service.lock:
                    stored = service.entries.get(token) or {}
                    config = dict(stored)
                    # dict() is a shallow copy, so config["urls"] would be the very
                    # list mark_selected() reorders under the lock. This server is
                    # threaded and the media player issues overlapping range
                    # requests, so another handler could mutate the list while the
                    # loop below iterates it. Copy the list too.
                    config["urls"] = list(stored.get("urls") or [])
                if not config:
                    self.send_error(404)
                    return

                client_range = self.headers.get("Range")
                upstream_range = client_range or ("bytes=0-0" if not send_body else None)
                response = None
                selected_url = ""
                last_error = ""
                for url in config.get("urls", []):
                    try:
                        parsed = urllib.parse.urlparse(url)
                        headers = {
                            "User-Agent": EXPLORE_USER_AGENT,
                            "Accept": "video/mp4,video/webm,video/*,*/*;q=0.8",
                            "Accept-Language": "en-US,en;q=0.9",
                            "Referer": config.get("referer") or f"{parsed.scheme}://{parsed.netloc}/",
                            "Connection": "close",
                        }
                        if upstream_range:
                            headers["Range"] = upstream_range
                        request = urllib.request.Request(url, headers=headers)
                        response = open_network_request(request, timeout=30)
                        selected_url = url
                        break
                    except Exception as exc:
                        last_error = str(exc)
                if response is None:
                    write_app_log(f"video stream bridge could not open post={config.get('post_id')} error={last_error}")
                    self.send_error(502, "Remote video could not be opened")
                    return

                try:
                    content_type = response.headers.get("Content-Type") or "video/mp4"
                    content_range = response.headers.get("Content-Range") or ""
                    content_length = response.headers.get("Content-Length") or ""
                    if not send_body:
                        total_match = re.search(r"/(\d+)$", content_range)
                        if total_match:
                            content_length = total_match.group(1)
                        self.send_response(200)
                    else:
                        self.send_response(response.getcode() or (206 if client_range else 200))
                    self.send_header("Content-Type", content_type)
                    self.send_header("Accept-Ranges", "bytes")
                    if content_range and send_body:
                        self.send_header("Content-Range", content_range)
                    if content_length:
                        self.send_header("Content-Length", content_length)
                    self.send_header("Cache-Control", "no-store")
                    self.send_header("Connection", "close")
                    self.end_headers()
                    if send_body:
                        while True:
                            chunk = response.read(1024 * 256)
                            if not chunk:
                                break
                            self.wfile.write(chunk)
                    service.mark_selected(token, selected_url)
                except (BrokenPipeError, ConnectionResetError):
                    pass
                except Exception as exc:
                    write_app_log(f"video stream bridge transfer failed post={config.get('post_id')} error={exc}")
                finally:
                    try:
                        response.close()
                    except Exception:
                        pass

        return StreamHandler

    def register(self, entry: dict, preferred_url: str = "") -> str:
        candidates = video_candidates_for_entry(entry, preferred_url)
        if not candidates:
            return ""
        token_source = f"{entry.get('post_id')}|{candidates[0]}|{time.time_ns()}"
        token = hashlib.sha1(token_source.encode("utf-8", errors="ignore")).hexdigest()
        with self.lock:
            self.entries[token] = {
                "urls": candidates[:8],
                "referer": entry.get("source_url") or "",
                "post_id": entry.get("post_id") or "",
            }
            while len(self.entries) > 80:
                self.entries.pop(next(iter(self.entries)))
        write_app_log(f"video stream registered post={entry.get('post_id')} candidates={len(candidates[:8])}")
        return f"http://127.0.0.1:{self.server.server_port}/video/{token}"

    def mark_selected(self, token: str, selected_url: str):
        with self.lock:
            config = self.entries.get(token)
            if config and selected_url in config.get("urls", []):
                config["urls"].remove(selected_url)
                config["urls"].insert(0, selected_url)

    def stop(self):
        try:
            self.server.shutdown()
            self.server.server_close()
        except Exception:
            pass


VIDEO_STREAM_PROXY: VideoStreamProxy | None = None
VIDEO_STREAM_PROXY_LOCK = threading.Lock()


def get_video_stream_proxy() -> VideoStreamProxy | None:
    global VIDEO_STREAM_PROXY
    with VIDEO_STREAM_PROXY_LOCK:
        if VIDEO_STREAM_PROXY is None:
            try:
                VIDEO_STREAM_PROXY = VideoStreamProxy()
            except Exception as exc:
                write_app_log(f"video stream bridge failed to start error={exc}")
                return None
        return VIDEO_STREAM_PROXY


def stop_video_stream_proxy():
    global VIDEO_STREAM_PROXY
    with VIDEO_STREAM_PROXY_LOCK:
        proxy = VIDEO_STREAM_PROXY
        VIDEO_STREAM_PROXY = None
    if proxy is not None:
        proxy.stop()


def friendly_network_error(error: str) -> str:
    # Exceptions raised with no message stringify to "", and callers do things
    # like .splitlines()[0] on the result - which raised IndexError *inside* the
    # error handler and turned a failed search into an unhandled crash dialog.
    text = str(error).strip() or "The site did not say what went wrong."
    if "WinError 10061" in text or "actively refused" in text:
        return text + "\n\nThe connection was refused before the app reached the site. This is usually a blocked/dead proxy, firewall rule, VPN filter, or security app blocking Distant Viewer."
    if "WinError 10013" in text or "access permissions" in text:
        return text + "\n\nWindows or a security app blocked Distant Viewer from opening the network connection."
    return text


def with_gelbooru_auth(base_url: str, params: dict) -> dict:
    netloc = urllib.parse.urlparse(base_url).netloc.lower()
    if "gelbooru.com" in netloc:
        if GELBOORU_USER_ID and GELBOORU_API_KEY:
            params = dict(params)
            params["user_id"] = GELBOORU_USER_ID
            params["api_key"] = GELBOORU_API_KEY
    elif "rule34.xxx" in netloc:
        if RULE34_USER_ID and RULE34_API_KEY:
            params = dict(params)
            params["user_id"] = RULE34_USER_ID
            params["api_key"] = RULE34_API_KEY
    return params


def raise_if_legacy_api_error(data: object):
    """Some gelbooru-clone sites (Rule34.xxx as of mid-2026) now return HTTP 200
    with an {"error": "..."} / <error>...</error> body instead of a real result
    when the DAPI/XML endpoint needs an API key it wasn't given. That looks like
    a normal, parseable response, so callers would otherwise treat it as "zero
    results" and silently fall through to the much more fragile HTML scraper for
    every request - raise so it's treated as the real failure it is."""
    if isinstance(data, dict):
        error_text = data.get("error")
        if error_text:
            raise RuntimeError(f"API error: {error_text}")


def raise_if_legacy_xml_api_error(root) -> None:
    if str(getattr(root, "tag", "")).strip().lower() == "error":
        raise RuntimeError(f"API error: {(root.text or '').strip()}")


def post_rows(data: object) -> list[dict]:
    if isinstance(data, dict):
        rows = data.get("post", data.get("posts", []))
    else:
        rows = data
    if isinstance(rows, dict):
        rows = [rows]
    if not isinstance(rows, list):
        return []
    flattened = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        attrs = row.get("@attributes") or row.get("attributes")
        if isinstance(attrs, dict):
            merged = dict(attrs)
            merged.update({key: value for key, value in row.items() if key not in {"@attributes", "attributes"}})
            flattened.append(merged)
        else:
            flattened.append(row)
    return flattened


def fetch_xml_root(url: str, timeout: int = 10) -> ET.Element:
    data = fetch_url_bytes(url, timeout=timeout)
    return ET.fromstring(data.decode("utf-8", errors="replace"))


def explore_search_urls(
    site_key: str,
    tags: str,
    page: int = 1,
    per_page: int = EXPLORE_LIMIT,
    offset_override: int | None = None,
) -> list[str]:
    encoded = urllib.parse.quote_plus(" ".join(tags.split()))
    keys = ["gelbooru", "e621", "realbooru", "rule34xxx"] if site_key == "all" else [site_key]
    page = max(1, page)
    offset = max(0, int(offset_override)) if offset_override is not None else max(0, (page - 1) * max(1, per_page))
    urls = []
    for key in keys:
        if key == "e621":
            urls.append(f"https://e621.net/posts?page={page}&tags={encoded}")
        elif key in {"realbooru", "rule34xxx"}:
            base_url = LEGACY_BOORU_SITES.get(key, LEGACY_BOORU_SITES["gelbooru"])[1]
            pid_values = [offset] if offset_override is not None else [offset, page - 1]
            for pid in dict.fromkeys(pid_values):
                urls.append(f"{base_url}/index.php?page=post&s=list&pid={pid}&tags={encoded}")
        else:
            pid_values = [offset] if offset_override is not None else [offset, page - 1]
            for pid in dict.fromkeys(pid_values):
                urls.append(f"https://gelbooru.com/index.php?page=post&s=list&pid={pid}&tags={encoded}")
    return urls


def absolute_url(base_url: str, url: str | None) -> str:
    if not url:
        return ""
    return urllib.parse.urljoin(base_url, url_with_scheme(url))


def html_attrs(tag: str) -> dict:
    return {
        key.lower(): unescape(value)
        for key, value in re.findall(r'([a-zA-Z0-9_:-]+)\s*=\s*["\']([^"\']*)["\']', tag)
    }


def srcset_urls(value: str | None) -> list[str]:
    if not value:
        return []
    urls = []
    for part in value.split(","):
        url = part.strip().split(" ")[0].strip()
        if url:
            urls.append(url)
    return urls


def text_tags(value: str | None) -> list[str]:
    if not value:
        return []
    clean = re.sub(r"<[^>]+>", " ", value)
    return [part for part in re.split(r"[\s,]+", clean.strip()) if part]


def unique_tags(tags) -> list[str]:
    cleaned = []
    seen = set()
    for raw_tag in tags or []:
        tag = str(raw_tag).strip()
        key = tag.lower()
        if not tag or key in seen:
            continue
        seen.add(key)
        cleaned.append(tag)
    return cleaned


def first_media_url_from_html(base_url: str, html_text: str) -> str:
    urls = media_urls_from_html(base_url, html_text)
    return urls[0] if urls else ""


def media_urls_from_html(base_url: str, html_text: str) -> list[str]:
    html_text = unescape(html_text).replace(r"\/", "/").replace(r"\/", "/")
    html_text = unescape(html_text).replace("\\/", "/")
    candidates = []
    for tag in re.findall(r"<meta\b[^>]*>", html_text, flags=re.IGNORECASE):
        attrs = html_attrs(tag)
        key = (attrs.get("property") or attrs.get("name") or attrs.get("itemprop") or "").lower()
        if key in {"og:image", "twitter:image", "image"} and attrs.get("content"):
            candidates.append(attrs.get("content"))
    for tag in re.findall(r"<img\b[^>]*>", html_text, flags=re.IGNORECASE):
        attrs = html_attrs(tag)
        marker = " ".join([attrs.get("id", ""), attrs.get("class", ""), attrs.get("alt", "")]).lower()
        image_values = [
            attrs.get("data-file-url"),
            attrs.get("data-large-file-url"),
            attrs.get("data-original-file-url"),
            attrs.get("data-original"),
            attrs.get("data-full"),
            attrs.get("data-src"),
            attrs.get("src"),
        ]
        image_values.extend(srcset_urls(attrs.get("srcset")))
        image_values.extend(srcset_urls(attrs.get("data-srcset")))
        if "image" in marker or any(value and media_url_score(absolute_url(base_url, value)) > 0 for value in image_values):
            candidates.extend([value for value in image_values if value])
    for tag in re.findall(r"<(?:video|source)\b[^>]*>", html_text, flags=re.IGNORECASE):
        attrs = html_attrs(tag)
        source_values = [
            attrs.get("src"),
            attrs.get("data-src"),
            attrs.get("data-file-url"),
            attrs.get("data-large-file-url"),
            attrs.get("data-original-file-url"),
        ]
        source_values.extend(srcset_urls(attrs.get("srcset")))
        source_values.extend(srcset_urls(attrs.get("data-srcset")))
        candidates.extend([value for value in source_values if value])
    for href, text in re.findall(r'<a\b([^>]*)>(.*?)</a>', html_text, flags=re.IGNORECASE | re.DOTALL):
        attrs = html_attrs(href)
        url = attrs.get("href")
        label = re.sub(r"<[^>]+>", " ", text).strip().lower()
        if url and (
            any(word in label for word in ["original", "download", "full", "view image", "image only"])
            or url_suffix(url) in MEDIA_EXTENSIONS
        ):
            candidates.append(url)
    priority_patterns = [
        r'href=["\']([^"\']+)["\'][^>]*>\s*(?:Original image|Original|Download|View original|Full size|Full resolution)',
        r'(?:file_url|file-url|large-file-url|data-file-url|data-large-file-url|data-original-file-url|data-original|data-full|data-normalized-source|srcset|data-srcset)\s*[:=]\s*["\']([^"\']+)["\']',
        r'<img[^>]+id=["\']image["\'][^>]+(?:src|data-src|data-original)=["\']([^"\']+)["\']',
        r'<video[^>]+(?:src|data-src)=["\']([^"\']+)["\']',
        r'<source[^>]+(?:src|data-src)=["\']([^"\']+)["\']',
        r'<meta[^>]+(?:property|name)=["\'](?:og:image|twitter:image)["\'][^>]+content=["\']([^"\']+)["\']',
    ]
    for pattern in priority_patterns:
        for match in re.findall(pattern, html_text, flags=re.IGNORECASE | re.DOTALL):
            candidates.extend(srcset_urls(match) if " " in match or "," in match else [match])
    json_patterns = [
        r'["\'](?:file_url|large_file_url|sample_url|preview_url|source)["\']\s*:\s*["\']([^"\']+)["\']',
        r'&quot;(?:file_url|large_file_url|sample_url|preview_url|source)&quot;\s*:\s*&quot;([^&]+)&quot;',
    ]
    for pattern in json_patterns:
        candidates.extend(re.findall(pattern, html_text, flags=re.IGNORECASE | re.DOTALL))
    for attr in ["src", "href", "content", "data-src", "srcset", "data-srcset", "data-file-url", "data-large-file-url", "data-original-file-url", "data-original", "data-full"]:
        for value in re.findall(attr + r'\s*=\s*["\']([^"\']+)["\']', html_text, flags=re.IGNORECASE):
            candidates.extend(srcset_urls(value) if attr.endswith("srcset") else [value])
    direct_patterns = [
        r'https?://[^"\'<>\s]+?\.(?:jpe?g|png|webp|gif|mp4|webm)(?:\?[^"\'<>\s]*)?',
        r'//[^"\'<>\s]+?\.(?:jpe?g|png|webp|gif|mp4|webm)(?:\?[^"\'<>\s]*)?',
    ]
    for pattern in direct_patterns:
        candidates.extend(re.findall(pattern, html_text, flags=re.IGNORECASE))
    valid = [absolute_url(base_url, url) for url in candidates]
    valid = [url for url in valid if url_suffix(url) in MEDIA_EXTENSIONS]
    seen = set()
    valid = [url for url in valid if not (url in seen or seen.add(url))]
    valid = sorted(valid, key=media_url_score, reverse=True)[:64]
    expanded = []
    for url in valid:
        expanded.append(url)
        expanded.extend(original_url_guesses(url))
    valid = expanded
    valid = [url for url in valid if url_suffix(url) in MEDIA_EXTENSIONS]
    seen = set()
    valid = [url for url in valid if not (url in seen or seen.add(url))]
    if valid:
        return sorted(valid, key=media_url_score, reverse=True)[:48]
    return []


def declared_media_urls_from_html(base_url: str, html_text: str) -> list[str]:
    """Return exact media URLs declared by the post page, without filename guessing."""
    text = unescape(html_text).replace(r"\/", "/").replace(r"\/", "/")
    values = []
    patterns = (
        r'<(?:video|source)\b[^>]*(?:src|data-src)\s*=\s*["\']([^"\']+)["\']',
        r'["\'](?:src|file_url|file-url|original_url|original-url)["\']\s*:\s*["\']([^"\']+)["\']',
        r'\b(?:src|file_url|file-url|original_url|original-url)\s*[:=]\s*["\']([^"\']+)["\']',
        r'<a\b[^>]*href\s*=\s*["\']([^"\']+\.(?:mp4|webm|gif)(?:\?[^"\']*)?)["\']',
    )
    for pattern in patterns:
        values.extend(re.findall(pattern, text, flags=re.IGNORECASE | re.DOTALL))
    direct_patterns = (
        r'https?://[^"\'< >\s]+?\.(?:jpe?g|png|webp|gif|mp4|webm)(?:\?[^"\'< >\s]*)?',
        r'//[^"\'< >\s]+?\.(?:jpe?g|png|webp|gif|mp4|webm)(?:\?[^"\'< >\s]*)?',
    )
    for pattern in direct_patterns:
        values.extend(re.findall(pattern, text, flags=re.IGNORECASE))
    urls = [absolute_url(base_url, value.strip()) for value in values]
    seen = set()
    urls = [url for url in urls if url_suffix(url) in MEDIA_EXTENSIONS and not (url in seen or seen.add(url))]
    # Unlike media_urls_from_html, this used to return matches in raw document order
    # with no quality filtering at all - so a page-wide branding/ad image (e.g.
    # Rule34.xxx's "r34chibi.png", which lives under /images/ just like real content)
    # could outrank the actual post if it happened to appear earlier in the HTML.
    # Score-sort so real content wins regardless of where it sits in the page.
    urls = [url for url in urls if media_url_score(url) > -300]
    return sorted(urls, key=media_url_score, reverse=True)


_CONTENT_HASH_FILENAME_RE = re.compile(r"^[0-9a-f]{24,40}$", re.IGNORECASE)
_NON_CONTENT_URL_MARKERS = (
    "/static/",
    "/cdn-cgi/",
    "/script/",
    "icame.png",
    "chibi",
    "_merch",
    "favicon",
)


def looks_like_content_hash_filename(url: str) -> bool:
    stem = Path(urllib.parse.urlparse(url).path).stem
    return bool(_CONTENT_HASH_FILENAME_RE.match(stem))


def registrable_domain(netloc: str) -> str:
    host = (netloc or "").split("@")[-1].split(":")[0].lower()
    labels = [label for label in host.split(".") if label]
    return ".".join(labels[-2:]) if len(labels) >= 2 else host


def same_site_family(url: str, reference_url: str) -> bool:
    """True if url's host is the reference's own domain (any subdomain of it) -
    used to stop a post-resolution HTML scrape from ever trusting a same-shaped
    (hash-named, /images/-pathed) media URL that actually points at a different
    site than the one being resolved."""
    url_domain = registrable_domain(urllib.parse.urlparse(url).netloc)
    reference_domain = registrable_domain(urllib.parse.urlparse(reference_url).netloc)
    return bool(url_domain) and url_domain == reference_domain


def media_url_score(url: str) -> int:
    lower = url.lower()
    score = 0
    if "/images/" in lower or "/image/" in lower or "/img/" in lower:
        score += 200
    if "/files/" in lower or "/data/" in lower:
        score += 180
    if "original" in lower or "full" in lower:
        score += 50
    if "/samples/" in lower or "sample" in lower:
        score -= 80
    if "/thumbnail" in lower or "/thumbnails/" in lower or "thumb" in lower or "preview" in lower:
        score -= 260
    if looks_like_content_hash_filename(url):
        # These gelbooru-clone sites name real uploaded media "<md5-hash>.<ext>". A
        # site-chrome/branding asset living under the same /images/ path (e.g. a fixed
        # mascot or ad graphic like Rule34.xxx's "r34chibi.png") won't have this shape,
        # so this is a much stronger positive signal than the path alone.
        score += 300
    if any(marker in lower for marker in _NON_CONTENT_URL_MARKERS):
        score -= 500
    if any(ext in lower for ext in [".jpg", ".jpeg", ".png", ".webp", ".gif"]):
        score += 6
    if url_suffix(lower) in VIDEO_EXTENSIONS:
        score += 10
    return score


def looks_like_thumbnail_url(url: str) -> bool:
    lower = (url or "").lower()
    return any(part in lower for part in ["/thumbnail", "/thumbnails/", "thumbnail_", "/preview", "preview_", "thumb"])


def looks_like_preview_media_url(url: str) -> bool:
    lower = (url or "").lower()
    return looks_like_thumbnail_url(lower) or "/samples/" in lower or "sample_" in lower


def original_url_guesses(url: str) -> list[str]:
    guesses = []
    if not url:
        return guesses
    parsed = urllib.parse.urlparse(url)
    path = parsed.path
    replacements = []
    if "/thumbnails/" in path:
        replacements.append(path.replace("/thumbnails/", "/images/").replace("/thumbnail_", "/"))
        replacements.append(path.replace("/thumbnails/", "/image/").replace("/thumbnail_", "/"))
    if "/thumbnail/" in path:
        replacements.append(path.replace("/thumbnail/", "/images/").replace("/thumbnail_", "/"))
        replacements.append(path.replace("/thumbnail/", "/image/").replace("/thumbnail_", "/"))
    if "/samples/" in path:
        replacements.append(path.replace("/samples/", "/images/").replace("/sample_", "/"))
        replacements.append(path.replace("/samples/", "/image/").replace("/sample_", "/"))
    if "thumbnail_" in path:
        replacements.append(path.replace("thumbnail_", ""))
    if "sample_" in path:
        replacements.append(path.replace("sample_", ""))
    host = parsed.netloc.lower()
    host_guesses = [parsed.netloc]
    if host.startswith("gelbooru.com") or host.startswith("www.gelbooru.com"):
        host_guesses.extend(["img2.gelbooru.com", "img3.gelbooru.com", "img4.gelbooru.com", "video-cdn1.gelbooru.com", "video-cdn2.gelbooru.com"])
    if "img" in host and "gelbooru.com" in host:
        host_guesses.extend(["img2.gelbooru.com", "img3.gelbooru.com", "img4.gelbooru.com", "video-cdn1.gelbooru.com", "video-cdn2.gelbooru.com"])
    if "video-cdn" in host and "gelbooru.com" in host:
        host_guesses.extend(["video-cdn1.gelbooru.com", "video-cdn2.gelbooru.com", "img2.gelbooru.com", "img3.gelbooru.com", "img4.gelbooru.com"])
    suffixes = [Path(path).suffix.lower()]
    for extra in [".jpg", ".jpeg", ".png", ".webp", ".gif", ".mp4", ".webm"]:
        if extra not in suffixes:
            suffixes.append(extra)
    if not replacements:
        replacements.append(path)
    for candidate_path in replacements:
        root = posixpath.splitext(candidate_path)[0]
        for suffix in suffixes:
            if suffix:
                for host_guess in dict.fromkeys(host_guesses):
                    guesses.append(urllib.parse.urlunparse(parsed._replace(netloc=host_guess, path=root + suffix)))
    return guesses


def better_media_url(current_url: str, candidate_url: str) -> str:
    if not candidate_url:
        return current_url
    if not current_url:
        return candidate_url
    if looks_like_thumbnail_url(current_url) and not looks_like_thumbnail_url(candidate_url):
        return candidate_url
    return candidate_url if media_url_score(candidate_url) > media_url_score(current_url) else current_url


def tag_category_color(category: str) -> str:
    category = normalized_tag_category(category)
    if category == "artist":
        return "#ff5b6e"
    if category == "character":
        return "#ffd35c"
    if category == "series":
        return "#bfaaff"
    return "#ffffff"


def inferred_tag_category(tag: str, explicit_category: str = "", index: int = 0) -> str:
    explicit = normalized_tag_category(explicit_category)
    if explicit != "general":
        return explicit
    return "general"


def normalized_tag_category(category: str) -> str:
    category = (category or "").lower().strip().replace("-", "_").replace(" ", "_")
    if category in {"1", "artist", "artists", "tag_type_artist", "tag_type_1"}:
        return "artist"
    # "model" is Realbooru's name for the person depicted - its closest equivalent
    # in the other sites' vocabulary (and in this app's colouring) is "character".
    if category in {"4", "character", "characters", "model", "models", "tag_type_character", "tag_type_4"}:
        return "character"
    if category in {"3", "copyright", "copyrights", "series", "franchise", "tag_type_copyright", "tag_type_3"}:
        return "series"
    return "general"


# Category class names these sites put directly on the tag link itself, rather than
# on a wrapping <li class="tag-type-x">. Realbooru's post pages are built this way -
# <a class="model" href="...tags=hannah_owo">hannah owo</a> with no list wrapper at
# all - which is why the <li>-only scrape below found nothing for it and left almost
# every saved Realbooru post with no tag categories.
TAG_ANCHOR_CATEGORY_CLASSES = {
    "artist", "artists", "character", "characters", "model", "models",
    "copyright", "copyrights", "series", "franchise", "general", "metadata",
    "meta", "studio", "circle", "tag",
}


def extract_tag_categories_from_html(html_text: str) -> dict[str, str]:
    categories: dict[str, str] = {}
    html_text = unescape(html_text)
    for class_value, block in re.findall(
        r'<li[^>]+class=["\']([^"\']*(?:tag-type-|tag_type_|category-)[^"\']*)["\'][^>]*>(.*?)</li>',
        html_text,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        category_match = re.search(r'(?:tag-type-|tag_type_|category-)([a-z0-9_ -]+)', class_value, flags=re.IGNORECASE)
        # A class like `tag-type- ` captures only whitespace, and "".split() is
        # the empty list - indexing [0] on it crashed the scrape on real markup.
        category_words = category_match.group(1).strip().split() if category_match else []
        raw_category = category_words[0] if category_words else ""
        category = normalized_tag_category(raw_category)
        tag_matches = re.findall(r'[?&]tags=([^"\'&]+)', block, flags=re.IGNORECASE)
        if tag_matches:
            for raw_tag in tag_matches:
                tag = urllib.parse.unquote_plus(raw_tag).strip()
                if tag:
                    categories[tag.lower()] = category
            continue
        text = re.sub(r"<[^>]+>", " ", block)
        parts = [part for part in re.split(r"\s+", text.strip()) if part]
        if parts:
            categories[parts[-1].lower()] = category
    for heading, block in re.findall(
        r'<(?:h[1-6]|strong|b)[^>]*>\s*(Artists?|Characters?|Copyrights?|Series|Franchise)\s*</(?:h[1-6]|strong|b)>(.*?)(?=<h[1-6]|</ul>|</section>|</div>)',
        html_text,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        category = normalized_tag_category(heading)
        for raw_tag in re.findall(r'[?&]tags=([^"\'&]+)', block, flags=re.IGNORECASE):
            tag = urllib.parse.unquote_plus(raw_tag).strip()
            if tag:
                categories[tag.lower()] = category
    # Tag links that carry their category on the anchor itself with no list wrapper
    # (Realbooru's post-page layout - see TAG_ANCHOR_CATEGORY_CLASSES). Runs last and
    # never overwrites what the wrapper-based passes above already resolved, so the
    # sites that do use <li class="tag-type-x"> keep their existing behaviour.
    for class_value, raw_tag in re.findall(
        r'<a\b[^>]*\bclass=["\']([^"\']+)["\'][^>]*\bhref=["\'][^"\']*[?&]tags=([^"\'&]+)["\']',
        html_text,
        flags=re.IGNORECASE,
    ):
        classes = [part for part in re.split(r"\s+", class_value.strip()) if part]
        raw_category = ""
        for name in classes:
            stripped = re.sub(r"^(?:tag-type-|tag_type_|category-)", "", name, flags=re.IGNORECASE)
            if stripped.lower() in TAG_ANCHOR_CATEGORY_CLASSES:
                raw_category = stripped
                break
        if not raw_category:
            continue
        tag = urllib.parse.unquote_plus(raw_tag).strip()
        if tag and tag.lower() not in categories:
            categories[tag.lower()] = normalized_tag_category(raw_category)
    return categories


def merge_scraped_tags(existing, scraped) -> list[str]:
    """Prefer canonical tag names scraped from a post's own tag links.

    The HTML search-listing scraper can only read a thumbnail's title/alt text,
    where these sites print the *display* form of each tag with underscores turned
    into spaces - so `text_tags()` splitting that on whitespace shatters every
    multi-word tag. A real Realbooru post shows this exactly: `hannah_owo`,
    `aesthetically_hannah`, `twitch_streamer`, `on_back`, `on_bed` and
    `small_breasts` all arrived as loose single words, which then sat in the tag
    list next to the genuinely-separate tags `hannahowo` and `aestheticallyhannah`
    - the same tag apparently listed twice, and none of the real multi-word tags
    clickable or searchable.

    The `tags=` link targets are the exact canonical names, so when we have them
    they win. Anything the scrape did not mention is still kept, unless it is just
    a word of a scraped tag (i.e. one of those shattered fragments)."""
    scraped = unique_tags(scraped)
    if not scraped:
        return unique_tags(existing)
    known = set()
    for tag in scraped:
        known.add(tag.lower())
        for word in re.split(r"[_\s-]+", tag.lower()):
            if word:
                known.add(word)
    leftovers = [tag for tag in (existing or []) if str(tag).strip().lower() not in known]
    return unique_tags([*scraped, *leftovers])


# Files downloaded from a booru are named "<site>_<postid>.<ext>" by
# remote_save_name(). file_tags() turns a filename into tags (deliberately - a local
# library's filenames carry real meaning), but for these auto-generated names that
# just injects a junk tag like "realbooru_804464" into every single downloaded
# file's tag list. Matching is deliberately anchored to the actual site prefixes
# remote_save_name can emit rather than a loose "<word>_<id>" shape: a real tag like
# "small_breasts" or "on_back" must never be mistaken for a generated filename.
@functools.lru_cache(maxsize=1)
def auto_save_name_prefixes() -> frozenset[str]:
    """Pure function of module constants, so it is computed once per process.
    It used to be rebuilt (5 safe_filename() regex passes) once per file while
    indexing, which was ~1.9s of the time to open a 46k-file saved library."""
    names = {"explore", *EXPLORE_SITE_LABELS.values(), *EXPLORE_SITES.values()}
    return frozenset(safe_filename(str(name).lower()) for name in names if str(name).strip())


def looks_like_auto_save_name(stem: str) -> bool:
    stem = (stem or "").strip().lower()
    prefix, separator, suffix = stem.rpartition("_")
    if not separator or not prefix or not suffix:
        return False
    if prefix not in auto_save_name_prefixes():
        return False
    return suffix.isdigit() or (len(suffix) >= 4 and all(char in "0123456789abcdef" for char in suffix))


def tags_without_auto_save_name(tags, path: Path) -> list[str]:
    stem = path.stem.strip().lower()
    if not stem or not looks_like_auto_save_name(stem):
        return list(tags)
    return [tag for tag in tags if str(tag).strip().lower() != stem]


def save_remote_thumbnail(url: str, destination: Path, referer: str | None = None, timeout: int = 7):
    destination.parent.mkdir(parents=True, exist_ok=True)
    data = fetch_url_bytes(url, timeout=timeout, referer=referer)
    with Image.open(io.BytesIO(data)) as image:
        image = ImageOps.exif_transpose(image)
        if getattr(image, "is_animated", False):
            image.seek(0)
        image = image.convert("RGB")
        image.thumbnail((THUMB_SIZE, THUMB_SIZE), Image.Resampling.LANCZOS)
        canvas = Image.new("RGB", (THUMB_SIZE, THUMB_SIZE), "#101013")
        canvas.paste(image, ((THUMB_SIZE - image.width) // 2, (THUMB_SIZE - image.height) // 2))
        canvas.save(destination, "JPEG", quality=88)


def file_tags(path: Path) -> set[str]:
    tags = set()
    for part in path.stem.split(" "):
        clean = part.strip().lower()
        if not clean:
            continue
        tags.add(clean)
        if "." in clean:
            tags.add(clean.split(".", 1)[0])
    return tags


def media_type(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix in GIF_EXTENSIONS:
        return "gif"
    if suffix in VIDEO_EXTENSIONS:
        return "video"
    return "image"


def is_media(path: Path) -> bool:
    return path.is_file() and path.suffix.lower() in MEDIA_EXTENSIONS


def format_size(size: int) -> str:
    units = ["B", "KB", "MB", "GB", "TB"]
    value = float(size)
    for unit in units:
        if value < 1024 or unit == units[-1]:
            return f"{value:.1f} {unit}" if unit != "B" else f"{int(value)} B"
        value /= 1024
    return f"{size} B"


def entry_size(entry: dict) -> int:
    try:
        size = int(entry.get("size") or 0)
    except (TypeError, ValueError):
        size = 0
    if size <= 0:
        try:
            size = Path(entry.get("path") or "").stat().st_size
        except OSError:
            size = 0
    return size


_FILE_FULL_DIRECTORY_INFO = 14
_FILE_FULL_DIRECTORY_RESTART_INFO = 15
_FILE_BASIC_INFO = 0
_WINDOWS_EPOCH_OFFSET = 116444736000000000


def _windows_handle_api():
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create = kernel32.CreateFileW
    create.restype = wintypes.HANDLE
    create.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, wintypes.LPVOID,
                       wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE]
    query = kernel32.GetFileInformationByHandleEx
    query.restype = wintypes.BOOL
    query.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p, wintypes.DWORD]
    close = kernel32.CloseHandle
    close.argtypes = [wintypes.HANDLE]
    return create, query, close


def _filetime_to_unix(value: int) -> float:
    return (value - _WINDOWS_EPOCH_OFFSET) / 1e7 if value > _WINDOWS_EPOCH_OFFSET else 0.0


def folder_change_times(folder: Path) -> dict[str, float]:
    """NTFS change time of every file in a folder, in one directory read.

    A move or rename stamps a file's change time (creation and modified times
    travel with the file unchanged), so for a saved file it says when it landed
    in the folder it is in now - how files moved before the app recorded
    "moved_at" still sort by when they were moved. ~0.4s for 117k files.
    Empty on failure (not NTFS, not Windows)."""
    times: dict[str, float] = {}
    try:
        create, query, close = _windows_handle_api()
        # FILE_LIST_DIRECTORY, share everything, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS
        handle = create(str(folder), 0x0001, 0x7, None, 3, 0x02000000, None)
        if handle is None or handle == wintypes.HANDLE(-1).value:
            return times
    except Exception:
        return times
    try:
        buffer = ctypes.create_string_buffer(256 * 1024)
        info_class = _FILE_FULL_DIRECTORY_RESTART_INFO
        while query(handle, info_class, buffer, len(buffer)):
            info_class = _FILE_FULL_DIRECTORY_INFO
            raw = buffer.raw
            offset = 0
            while True:
                next_offset = int.from_bytes(raw[offset:offset + 4], "little")
                change = int.from_bytes(raw[offset + 32:offset + 40], "little")
                name_length = int.from_bytes(raw[offset + 60:offset + 64], "little")
                name = raw[offset + 68:offset + 68 + name_length].decode("utf-16-le", errors="replace")
                stamp = _filetime_to_unix(change)
                if stamp:
                    times[name] = stamp
                if not next_offset:
                    break
                offset += next_offset
    except Exception:
        pass
    finally:
        close(handle)
    return times


def file_change_time(path: Path) -> float:
    """folder_change_times() for a single file; 0.0 when unknown."""
    try:
        create, query, close = _windows_handle_api()
        # FILE_READ_ATTRIBUTES, share everything, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS
        handle = create(str(path), 0x0080, 0x7, None, 3, 0x02000000, None)
        if handle is None or handle == wintypes.HANDLE(-1).value:
            return 0.0
    except Exception:
        return 0.0
    try:
        buffer = ctypes.create_string_buffer(40)
        if not query(handle, _FILE_BASIC_INFO, buffer, len(buffer)):
            return 0.0
        return _filetime_to_unix(int.from_bytes(buffer.raw[24:32], "little"))
    except Exception:
        return 0.0
    finally:
        close(handle)


def entry_moved_at(entry: dict) -> float:
    """When the entry's file was moved into its folder: the recorded in-app move,
    else the file's change time, else when it was saved."""
    for field in ("moved_at", "saved_at", "mtime"):
        try:
            value = float(entry.get(field) or 0)
        except (TypeError, ValueError):
            value = 0.0
        if value > 0:
            return value
    return 0.0


def normalized_entry(path: Path, stat, cached: dict | None = None) -> dict:
    entry = dict(cached or {})
    mtime = stat.st_mtime
    size = stat.st_size
    # thumb_path_for() is a SHA1 over (version, path, mtime, size), so when the
    # cached entry was written for this same file at this same mtime/size and
    # under this same THUMB_VERSION, the hash is guaranteed to come out
    # identical - recomputing it is pure work. That mattered: it was ~2.2s of
    # the time to open a 46k-file saved library, once per file per open.
    # "type" is likewise a pure function of the suffix. Tags are deliberately
    # NOT reused: the cached entry holds the *merged* saved-metadata tags, not
    # the raw filename tags this function is supposed to produce.
    thumb = ""
    kind = ""
    if (
        cached
        and cached.get("mtime") == mtime
        and cached.get("size") == size
        and cached.get("thumb_v") == THUMB_VERSION
    ):
        thumb = str(cached.get("thumb") or "")
        kind = str(cached.get("type") or "")
    entry.update(
        {
            "path": str(path),
            "name": path.name,
            "mtime": mtime,
            "size": size,
            "tags": sorted(file_tags(path)),
            "type": kind or media_type(path),
            "thumb": thumb or thumb_path_for(path, mtime, size),
            "thumb_v": THUMB_VERSION,
        }
    )
    return entry


def thumb_path_for(path: Path, mtime: float, size: int) -> str:
    raw = f"{THUMB_VERSION}|{path}|{mtime}|{size}".encode("utf-8", errors="ignore")
    return str(thumbnail_folder() / f"{hashlib.sha1(raw).hexdigest()}.jpg")


def full_quality_thumb_path_for(path: Path, mtime: float, file_size: int, icon_side: int) -> str:
    side = max(1, int(icon_side))
    raw = f"{FULL_QUALITY_THUMB_VERSION}|{path}|{mtime}|{file_size}|{side}".encode("utf-8", errors="ignore")
    return str(thumbnail_folder() / f"hq_{hashlib.sha1(raw).hexdigest()}.jpg")


def windows_shell_thumbnail(source: Path) -> Image.Image | None:
    if os.name != "nt":
        return None
    shell32 = ctypes.windll.shell32
    gdi32 = ctypes.windll.gdi32
    user32 = ctypes.windll.user32
    ctypes.windll.ole32.CoInitialize(None)
    shell32.SHCreateItemFromParsingName.argtypes = [
        wintypes.LPCWSTR,
        ctypes.c_void_p,
        ctypes.POINTER(GUID),
        ctypes.POINTER(ctypes.c_void_p),
    ]
    shell32.SHCreateItemFromParsingName.restype = ctypes.c_long
    gdi32.GetObjectW.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p]
    gdi32.GetObjectW.restype = ctypes.c_int
    gdi32.GetDIBits.argtypes = [
        wintypes.HDC,
        wintypes.HBITMAP,
        wintypes.UINT,
        wintypes.UINT,
        ctypes.c_void_p,
        ctypes.POINTER(BITMAPINFO),
        wintypes.UINT,
    ]
    gdi32.GetDIBits.restype = ctypes.c_int
    factory = ctypes.c_void_p()
    hr = shell32.SHCreateItemFromParsingName(str(source), None, ctypes.byref(IID_IShellItemImageFactory), ctypes.byref(factory))
    if hr != 0 or not factory:
        return None
    hbitmap = wintypes.HBITMAP()
    try:
        vtable = ctypes.cast(factory, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
        get_image = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p, SIZE, ctypes.c_int, ctypes.POINTER(wintypes.HBITMAP))(vtable[3])
        hr = get_image(
            factory,
            SIZE(THUMB_SIZE, THUMB_SIZE),
            SIIGBF_BIGGERSIZEOK | SIIGBF_RESIZETOFIT | SIIGBF_THUMBNAILONLY,
            ctypes.byref(hbitmap),
        )
        if hr != 0 or not hbitmap:
            return None
        bitmap = BITMAP()
        if not gdi32.GetObjectW(hbitmap, ctypes.sizeof(bitmap), ctypes.byref(bitmap)):
            return None
        width = int(bitmap.bmWidth)
        height = int(bitmap.bmHeight)
        if width <= 0 or height <= 0:
            return None
        info = BITMAPINFO()
        info.bmiHeader.biSize = ctypes.sizeof(BITMAPINFOHEADER)
        info.bmiHeader.biWidth = width
        info.bmiHeader.biHeight = -height
        info.bmiHeader.biPlanes = 1
        info.bmiHeader.biBitCount = 32
        info.bmiHeader.biCompression = BI_RGB
        buffer = ctypes.create_string_buffer(width * height * 4)
        screen = user32.GetDC(None)
        try:
            result = gdi32.GetDIBits(screen, hbitmap, 0, height, buffer, ctypes.byref(info), DIB_RGB_COLORS)
        finally:
            user32.ReleaseDC(None, screen)
        if not result:
            return None
        image = Image.frombuffer("RGBA", (width, height), buffer, "raw", "BGRA", 0, 1).convert("RGB")
        image.thumbnail((THUMB_SIZE, THUMB_SIZE), Image.Resampling.LANCZOS)
        canvas = Image.new("RGB", (THUMB_SIZE, THUMB_SIZE), "#101013")
        canvas.paste(image, ((THUMB_SIZE - image.width) // 2, (THUMB_SIZE - image.height) // 2))
        return canvas
    finally:
        if hbitmap:
            gdi32.DeleteObject(hbitmap)
        if factory:
            release = ctypes.WINFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p)(
                ctypes.cast(factory, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents[2]
            )
            release(factory)


def create_thumbnail(source: Path, destination: Path, kind: str):
    destination.parent.mkdir(parents=True, exist_ok=True)
    if kind == "video":
        create_video_thumbnail(source, destination)
    else:
        with Image.open(source) as image:
            image = ImageOps.exif_transpose(image)
            if getattr(image, "is_animated", False):
                image.seek(0)
            image = image.convert("RGB")
            image.thumbnail((THUMB_SIZE, THUMB_SIZE), Image.Resampling.LANCZOS)
            canvas = Image.new("RGB", (THUMB_SIZE, THUMB_SIZE), "#101013")
            canvas.paste(image, ((THUMB_SIZE - image.width) // 2, (THUMB_SIZE - image.height) // 2))
            # No baked-in badge here - the gallery already draws a crisp, live "GIF"
            # badge on top at display time (animated_border_pixmap). Baking a second
            # one into the cached JPEG produced a blurry duplicate stacked under the
            # sharp live one.
            canvas.save(destination, "JPEG", quality=82)


def create_full_quality_thumbnail(source: Path, destination: Path, kind: str, icon_side: int):
    side = max(96, min(640, int(icon_side)))
    destination.parent.mkdir(parents=True, exist_ok=True)
    with Image.open(source) as image:
        image = ImageOps.exif_transpose(image)
        if getattr(image, "is_animated", False):
            image.seek(0)
        image = image.convert("RGB")
        image.thumbnail((side, side), Image.Resampling.LANCZOS)
        canvas = Image.new("RGB", (side, side), "#101013")
        canvas.paste(image, ((side - image.width) // 2, (side - image.height) // 2))
        canvas.save(destination, "JPEG", quality=90)


def cv2_video_frame_thumbnail(source: Path) -> Image.Image | None:
    """Real-frame fallback for create_video_thumbnail()/media_visual_hash() when
    windows_shell_thumbnail() can't produce one - no thumbnail provider
    registered for that video's codec/container, which used to silently return
    the generic per-file-type icon (a white page with a play button) instead of
    failing. Reads one frame ~30% into the clip (skips black/blank intros) via
    the same optional cv2 dependency the duplicate finder already uses for
    per-frame hashing (see _video_frames_for_hashing)."""
    cv2 = optional_module("cv2")
    if cv2 is None:
        return None
    capture = None
    try:
        with CV2_VIDEO_DECODE_LOCK:
            capture = cv2.VideoCapture(str(source))
            if not capture.isOpened():
                return None
            total = int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
            if total > 0:
                capture.set(cv2.CAP_PROP_POS_FRAMES, max(0, min(total - 1, int(total * 0.3))))
            ok, frame = capture.read()
        if not ok or frame is None:
            return None
        image = Image.fromarray(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB))
        image.thumbnail((THUMB_SIZE, THUMB_SIZE), Image.Resampling.LANCZOS)
        canvas = Image.new("RGB", (THUMB_SIZE, THUMB_SIZE), "#101013")
        canvas.paste(image, ((THUMB_SIZE - image.width) // 2, (THUMB_SIZE - image.height) // 2))
        return canvas
    except Exception:
        return None
    finally:
        if capture is not None:
            try:
                capture.release()
            except Exception:
                pass


def create_video_thumbnail(source: Path, destination: Path):
    canvas = windows_shell_thumbnail(source) or cv2_video_frame_thumbnail(source)
    if canvas is None:
        canvas = Image.new("RGB", (THUMB_SIZE, THUMB_SIZE), "#101013")
        draw = ImageDraw.Draw(canvas)
        for y in range(0, THUMB_SIZE, 10):
            shade = 16 + min(28, y // 8)
            draw.rectangle((0, y, THUMB_SIZE, y + 10), fill=(shade, shade + 2, shade + 8))
    canvas.save(destination, "JPEG", quality=82)


def average_hash_from_image(image: Image.Image, size: int = 8) -> int:
    image = ImageOps.exif_transpose(image).convert("L").resize((size, size), Image.Resampling.LANCZOS)
    pixels = list(image.getdata())
    average = sum(pixels) / max(len(pixels), 1)
    value = 0
    for index, pixel in enumerate(pixels):
        if pixel >= average:
            value |= 1 << index
    return value


def media_visual_hash(path: Path) -> int | None:
    kind = media_type(path)
    try:
        if kind == "video":
            image = windows_shell_thumbnail(path) or cv2_video_frame_thumbnail(path)
            if image is None:
                return None
            return average_hash_from_image(image)
        with Image.open(path) as image:
            if getattr(image, "is_animated", False):
                image.seek(0)
            return average_hash_from_image(image)
    except Exception:
        return None


def hamming_distance(left: int, right: int) -> int:
    return int(left ^ right).bit_count()


_OPTIONAL_MODULES: dict[str, object] = {}


def optional_module(name: str):
    """Import numpy/opencv only when the duplicate finder actually needs them,
    and only once. They are heavy (both import time and RAM) and nothing else in
    the app touches them, so importing at startup would cost every launch for a
    feature most sessions never open. Both are optional - the finder degrades to
    a cheaper hash / single video frame if they are missing."""
    if name not in _OPTIONAL_MODULES:
        try:
            _OPTIONAL_MODULES[name] = importlib.import_module(name)
        except Exception:
            _OPTIONAL_MODULES[name] = None
    return _OPTIONAL_MODULES[name]


def dhash_from_image(image: Image.Image, size: int = 8) -> int:
    """Difference hash: compares each pixel with its right-hand neighbour on a
    tiny grid. Because everything is resized to the same grid first, the result
    is independent of the source resolution, and because it only looks at
    left/right *gradients* it survives re-encoding and brightness shifts."""
    small = ImageOps.exif_transpose(image).convert("L").resize((size + 1, size), Image.Resampling.LANCZOS)
    pixels = list(small.getdata())
    value = 0
    bit = 0
    row_width = size + 1
    for row in range(size):
        base = row * row_width
        for column in range(size):
            if pixels[base + column] > pixels[base + column + 1]:
                value |= 1 << bit
            bit += 1
    return value


_DCT_BASIS_CACHE: dict[int, object] = {}


def _dct_basis(side: int, numpy):
    basis = _DCT_BASIS_CACHE.get(side)
    if basis is None:
        rows = numpy.arange(side).reshape(-1, 1)
        columns = numpy.arange(side).reshape(1, -1)
        basis = numpy.cos(numpy.pi * (2 * columns + 1) * rows / (2 * side))
        basis[0] *= 1 / numpy.sqrt(2)
        basis *= numpy.sqrt(2 / side)
        _DCT_BASIS_CACHE[side] = basis
    return basis


def phash_from_image(image: Image.Image, size: int = 8, factor: int = 4) -> int | None:
    """Perceptual hash: keeps only the lowest-frequency DCT coefficients, i.e.
    the broad shapes a person actually recognises, and throws away the fine
    detail that changes with resolution and compression. Returns None when
    numpy is unavailable - callers fall back to the difference hash."""
    numpy = optional_module("numpy")
    if numpy is None:
        return None
    side = size * factor
    small = ImageOps.exif_transpose(image).convert("L").resize((side, side), Image.Resampling.LANCZOS)
    matrix = numpy.asarray(small, dtype=numpy.float64)
    basis = _dct_basis(side, numpy)
    coefficients = basis @ matrix @ basis.T
    block = coefficients[:size, :size].flatten()
    # Skip the DC term - it only encodes overall brightness, which is exactly
    # the thing we do not want to treat as a difference.
    median = float(numpy.median(block[1:]))
    value = 0
    for index, coefficient in enumerate(block):
        if float(coefficient) > median:
            value |= 1 << index
    return value


# Sampling several frames spread through a clip is what lets a video match the
# same content at a different resolution, container, or frame rate - and lets a
# GIF match the MP4 it was cut from, since both are reduced to the same list of
# still-frame hashes.
DUPLICATE_FRAME_POSITIONS = (0.10, 0.30, 0.50, 0.70, 0.90)


def _video_frames_for_hashing(path: Path) -> list[Image.Image]:
    cv2 = optional_module("cv2")
    if cv2 is None:
        return []
    capture = None
    frames: list[Image.Image] = []
    try:
        with CV2_VIDEO_DECODE_LOCK:
            capture = cv2.VideoCapture(str(path))
            if not capture.isOpened():
                return []
            total = int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
            if total > 0:
                targets = sorted({max(0, min(total - 1, int(total * ratio))) for ratio in DUPLICATE_FRAME_POSITIONS})
                for target in targets:
                    capture.set(cv2.CAP_PROP_POS_FRAMES, target)
                    ok, frame = capture.read()
                    if ok and frame is not None:
                        frames.append(Image.fromarray(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)))
            if not frames:
                # Some containers report no frame count and refuse to seek; just read
                # the first usable frames sequentially instead of giving up.
                for _ in range(len(DUPLICATE_FRAME_POSITIONS)):
                    ok, frame = capture.read()
                    if not ok or frame is None:
                        break
                    frames.append(Image.fromarray(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)))
    except Exception:
        return frames
    finally:
        if capture is not None:
            try:
                capture.release()
            except Exception:
                pass
    return frames


def _animated_frames_for_hashing(path: Path) -> list[Image.Image]:
    frames: list[Image.Image] = []
    with Image.open(path) as image:
        total = int(getattr(image, "n_frames", 1) or 1)
        if total <= 1:
            return [image.convert("RGB").copy()]
        targets = sorted({max(0, min(total - 1, int(total * ratio))) for ratio in DUPLICATE_FRAME_POSITIONS})
        for target in targets:
            try:
                image.seek(target)
                frames.append(image.convert("RGB").copy())
            except (EOFError, OSError):
                break
    return frames


def frames_for_hashing(path: Path, kind: str = "") -> list[Image.Image]:
    kind = kind or media_type(path)
    if kind == "video":
        frames = _video_frames_for_hashing(path)
        if frames:
            return frames
        # No opencv (or an unreadable container) - fall back to the same Windows
        # Shell thumbnail the gallery uses. One frame is weaker but still finds
        # re-encodes of the same clip.
        shell = windows_shell_thumbnail(path)
        return [shell] if shell is not None else []
    if kind == "gif":
        return _animated_frames_for_hashing(path)
    with Image.open(path) as image:
        return [image.convert("RGB").copy()]


def media_signature(path: Path) -> dict | None:
    """A resolution-independent fingerprint: one difference hash and one
    perceptual hash per sampled frame."""
    try:
        frames = frames_for_hashing(path)
    except Exception:
        return None
    difference_hashes: list[int] = []
    perceptual_hashes: list[int] = []
    for frame in frames:
        try:
            difference_hashes.append(dhash_from_image(frame))
        except Exception:
            continue
        try:
            value = phash_from_image(frame)
        except Exception:
            value = None
        if value is not None:
            perceptual_hashes.append(value)
    if not difference_hashes:
        return None
    return {"dhash": difference_hashes, "phash": perceptual_hashes}


def _frame_list_distance(left: list[int], right: list[int]) -> int:
    if not left or not right:
        return 64
    # Match each frame against its closest counterpart in the other clip, both
    # ways, then take the median. Best-match handles clips that are trimmed or
    # start at different points; the median stops one odd frame (a fade, a title
    # card, a black frame) from sinking an otherwise clear match.
    scores = [min(hamming_distance(a, b) for b in right) for a in left]
    scores.extend(min(hamming_distance(b, a) for a in left) for b in right)
    scores.sort()
    return scores[len(scores) // 2]


def signature_distance(left: dict, right: dict) -> int:
    """0 = identical looking, 64 = nothing in common."""
    difference = _frame_list_distance(left.get("dhash") or [], right.get("dhash") or [])
    left_perceptual = left.get("phash") or []
    right_perceptual = right.get("phash") or []
    if left_perceptual and right_perceptual:
        perceptual = _frame_list_distance(left_perceptual, right_perceptual)
        # Averaging the two means a pair has to look alike by both measures.
        # Either one alone produces obvious false positives: the difference hash
        # on flat/low-contrast art, the perceptual hash on recolours.
        return (difference + perceptual + 1) // 2
    return difference


DUPLICATE_SENSITIVITY = {
    "Strict (near-identical)": 2,
    "Balanced (recommended)": 6,
    "Loose (catches more)": 10,
}
DEFAULT_DUPLICATE_SENSITIVITY = "Balanced (recommended)"
DUPLICATE_SCOPES = ["Unfiltered", "Filtered", "Both folders"]
DEFAULT_DUPLICATE_SCOPE = "Unfiltered"
UI_STYLES = ["Classic", "Frosted"]
DEFAULT_UI_STYLE = "Classic"
TOOLBAR_LAYOUTS = ["Top", "Left"]
DEFAULT_TOOLBAR_LAYOUT = "Top"
_HASH_CHUNKS = 4
_HASH_CHUNK_BITS = 16
_CHUNK_FLIP_MASKS: dict[int, tuple[int, ...]] = {}


def _chunk_flip_masks(max_flips: int) -> tuple[int, ...]:
    """Every bit pattern with at most `max_flips` bits set, within one chunk."""
    masks = _CHUNK_FLIP_MASKS.get(max_flips)
    if masks is None:
        found = [0]
        if max_flips >= 1:
            found.extend(1 << bit for bit in range(_HASH_CHUNK_BITS))
        if max_flips >= 2:
            found.extend(
                (1 << a) | (1 << b)
                for a in range(_HASH_CHUNK_BITS)
                for b in range(a + 1, _HASH_CHUNK_BITS)
            )
        if max_flips >= 3:
            found.extend(
                (1 << a) | (1 << b) | (1 << c)
                for a in range(_HASH_CHUNK_BITS)
                for b in range(a + 1, _HASH_CHUNK_BITS)
                for c in range(b + 1, _HASH_CHUNK_BITS)
            )
        masks = tuple(found)
        _CHUNK_FLIP_MASKS[max_flips] = masks
    return masks


def group_similar_signatures(records: list[dict], threshold: int, should_stop=None, progress=None) -> list[list[int]]:
    """Group record indices whose signatures look the same.

    Comparing every file with every other one is O(n^2) and hopeless at library
    scale (20k files is 200 million comparisons). Instead this uses multi-index
    hashing: split each 64-bit hash into 4 chunks of 16 bits, and note that if
    two hashes differ in at most `threshold` bits, then some chunk must differ in
    at most threshold//4 bits. Looking up only those near-matching chunks finds
    every real pair (no missed matches) while touching a tiny fraction of the
    library, and the full signature comparison then confirms each candidate."""
    count = len(records)
    parent = list(range(count))

    def find(node: int) -> int:
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left: int, right: int):
        left_root, right_root = find(left), find(right)
        if left_root != right_root:
            parent[right_root] = left_root

    max_flips = min(3, threshold // _HASH_CHUNKS)
    masks = _chunk_flip_masks(max_flips)
    for field in ("dhash", "phash"):
        if should_stop and should_stop():
            return []
        index: dict[tuple[int, int], list[int]] = {}
        for position, record in enumerate(records):
            for value in record.get(field) or []:
                for chunk in range(_HASH_CHUNKS):
                    key = (chunk, (value >> (chunk * _HASH_CHUNK_BITS)) & 0xFFFF)
                    index.setdefault(key, []).append(position)
        if not index:
            continue
        for position, record in enumerate(records):
            if should_stop and should_stop():
                return []
            if progress and position % 250 == 0:
                progress(position, count)
            candidates: set[int] = set()
            for value in record.get(field) or []:
                for chunk in range(_HASH_CHUNKS):
                    base = (value >> (chunk * _HASH_CHUNK_BITS)) & 0xFFFF
                    for mask in masks:
                        found = index.get((chunk, base ^ mask))
                        if found:
                            candidates.update(found)
            candidates.discard(position)
            for other in candidates:
                if find(position) == find(other):
                    continue
                if signature_distance(record, records[other]) <= threshold:
                    union(position, other)

    groups: dict[int, list[int]] = {}
    for position in range(count):
        groups.setdefault(find(position), []).append(position)
    return [members for members in groups.values() if len(members) > 1]


class HoverButton(QPushButton):
    def __init__(self, text: str = ""):
        super().__init__(text)
        self._animation = QPropertyAnimation(self, b"minimumHeight", self)
        self._animation.setDuration(130)
        self._animation.setEasingCurve(QEasingCurve.OutCubic)
        self.setMinimumHeight(36)

    def enterEvent(self, event):
        self._animation.stop()
        self._animation.setStartValue(self.minimumHeight())
        self._animation.setEndValue(40)
        self._animation.start()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._animation.stop()
        self._animation.setStartValue(self.minimumHeight())
        self._animation.setEndValue(36)
        self._animation.start()
        super().leaveEvent(event)


class ExploreTabWidget(QFrame):
    def __init__(self, label: str, index: int, viewer):
        super().__init__()
        self.index = index
        self.viewer = viewer
        self.setObjectName("exploreTab")
        self.setAttribute(Qt.WA_StyledBackground, True)
        layout = QHBoxLayout(self)
        layout.setContentsMargins(4, 0, 8, 0)
        layout.setSpacing(4)
        self.close_button = QToolButton()
        self.close_button.setText("x")
        self.close_button.setObjectName("tabClose")
        self.close_button.setFixedSize(20, 24)
        self.close_button.hide()
        self.close_button.clicked.connect(lambda: self.viewer.close_search_tab(self.index))
        self.label_button = QPushButton(label or f"New Search {index + 1}")
        self.label_button.setObjectName("tabLabel")
        self.label_button.setMinimumHeight(28)
        self.label_button.clicked.connect(lambda: self.viewer.activate_search_tab(self.index))
        layout.addWidget(self.close_button)
        layout.addWidget(self.label_button)

    def enterEvent(self, event):
        self.close_button.show()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self.close_button.hide()
        super().leaveEvent(event)


class DuplicateGroupBar(QFrame):
    """One collapsed row per duplicate group in the Duplicates overview - a
    thumbnail strip plus a summary line, double-click to drill into that
    group's full set of copies. Every child label is mouse-transparent so a
    double-click anywhere on the row (thumbnails included) always reaches
    this frame instead of being swallowed by whichever label is on top."""

    def __init__(self, group_number: int, viewer):
        super().__init__()
        self.group_number = group_number
        self.viewer = viewer
        self.pinned = False
        self.changed_since_pin = False
        self.last_exited = False
        self.setObjectName("duplicateBar")
        self.setAttribute(Qt.WA_StyledBackground, True)
        self.setCursor(Qt.PointingHandCursor)
        self.setToolTip("Double-click to see every copy in this group\nRight-click to pin it to the top")
        layout = QHBoxLayout(self)
        layout.setContentsMargins(14, 10, 18, 10)
        layout.setSpacing(14)
        self.thumb_row = QHBoxLayout()
        self.thumb_row.setSpacing(6)
        layout.addLayout(self.thumb_row)
        text_col = QVBoxLayout()
        text_col.setSpacing(2)
        self.title_label = QLabel()
        self.title_label.setObjectName("duplicateBarTitle")
        self.title_label.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.detail_label = QLabel()
        self.detail_label.setObjectName("duplicateBarDetail")
        self.detail_label.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        text_col.addWidget(self.title_label)
        text_col.addWidget(self.detail_label)
        layout.addLayout(text_col, 1)
        hint = QLabel("Double-click to open ›")
        hint.setObjectName("muted")
        hint.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        layout.addWidget(hint)

    def set_thumbnails(self, icons: list, side: int, extra_count: int):
        while self.thumb_row.count():
            taken = self.thumb_row.takeAt(0)
            widget = taken.widget()
            if widget:
                widget.deleteLater()
        for icon in icons:
            label = QLabel()
            label.setObjectName("duplicateBarThumb")
            label.setAttribute(Qt.WA_TransparentForMouseEvents, True)
            label.setFixedSize(side, side)
            label.setPixmap(icon.pixmap(QSize(side, side)))
            label.setScaledContents(True)
            self.thumb_row.addWidget(label)
        if extra_count > 0:
            chip = QLabel(f"+{extra_count}")
            chip.setObjectName("duplicateBarExtra")
            chip.setAttribute(Qt.WA_TransparentForMouseEvents, True)
            chip.setAlignment(Qt.AlignCenter)
            chip.setFixedSize(side, side)
            self.thumb_row.addWidget(chip)

    def set_visual_state(self, pinned: bool, changed_since_pin: bool = False, last_exited: bool = False):
        """Priority when more than one state applies: changed-pin (red) >
        plain pin (gold) > last-exited (blue) > default. A pin is the more
        deliberate/durable signal, so it wins the border over the last-exited
        cursor if a group happens to be both."""
        self.pinned = pinned
        self.changed_since_pin = pinned and changed_since_pin
        self.last_exited = last_exited
        if self.changed_since_pin:
            object_name = "duplicateBarPinnedChanged"
        elif pinned:
            object_name = "duplicateBarPinned"
        elif last_exited:
            object_name = "duplicateBarLastExited"
        else:
            object_name = "duplicateBar"
        self.setObjectName(object_name)
        self.style().unpolish(self)
        self.style().polish(self)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.viewer.enter_duplicate_group(self.group_number)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event):
        if event.button() == Qt.RightButton:
            self.viewer.toggle_duplicate_group_pin(self.group_number)
            event.accept()
            return
        super().mousePressEvent(event)


class DuplicateBarList(QListWidget):
    """The Duplicates overview list. Forwards resize/scroll so the viewer can
    lazily build DuplicateGroupBar widgets only for rows near the viewport -
    building one eagerly for every group (each with its own icon decodes) is
    exactly the eager-decode-everything pattern that made startup RAM balloon
    for the main gallery before it was virtualized (see
    refresh_visible_gallery_icons); a library with hundreds/thousands of
    duplicate groups hit the same wall here."""

    def __init__(self, viewer):
        super().__init__()
        self.viewer = viewer

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self.viewer, "queue_duplicate_bar_viewport_refresh"):
            self.viewer.queue_duplicate_bar_viewport_refresh()

    def wheelEvent(self, event):
        if QApplication.keyboardModifiers() & Qt.ControlModifier:
            self.viewer.adjust_duplicate_bar_zoom(event.angleDelta().y() or event.pixelDelta().y())
            event.accept()
            return
        super().wheelEvent(event)


class HudPanel(QFrame):
    # The corner-bracket HUD decoration is painted directly, not styled via QSS,
    # so it used to stay hardcoded purple regardless of the accent colour picked
    # on the Appearance tab. DistantViewer.refresh_theme() updates these class
    # attributes (shared by every panel) and repaints all of them whenever the
    # user's colours change.
    accent_color = "#7d4dff"
    accent_light_color = "#bfaaff"
    dim_color = "#2a2440"

    def __init__(self, tag: str = ""):
        super().__init__()
        self.tag = tag
        self.setAttribute(Qt.WA_StyledBackground, True)

    def paintEvent(self, event):
        super().paintEvent(event)
        rect = self.rect().adjusted(1, 1, -2, -2)
        if rect.width() < 24 or rect.height() < 24:
            return

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)

        purple = QColor(HudPanel.accent_color)
        purple.setAlpha(185)
        violet = QColor(HudPanel.accent_light_color)
        violet.setAlpha(135)
        dim = QColor(HudPanel.dim_color)
        dim.setAlpha(150)

        corner = min(42, max(22, min(rect.width(), rect.height()) // 5))
        painter.setPen(purple)
        painter.drawLine(rect.left() + 10, rect.top() + 2, rect.left() + corner, rect.top() + 2)
        painter.drawLine(rect.left() + 2, rect.top() + 10, rect.left() + 2, rect.top() + corner)
        painter.drawLine(rect.right() - corner, rect.top() + 2, rect.right() - 10, rect.top() + 2)
        painter.drawLine(rect.right() - 2, rect.top() + 10, rect.right() - 2, rect.top() + corner)
        painter.drawLine(rect.left() + 10, rect.bottom() - 2, rect.left() + corner, rect.bottom() - 2)
        painter.drawLine(rect.left() + 2, rect.bottom() - corner, rect.left() + 2, rect.bottom() - 10)
        painter.drawLine(rect.right() - corner, rect.bottom() - 2, rect.right() - 10, rect.bottom() - 2)
        painter.drawLine(rect.right() - 2, rect.bottom() - corner, rect.right() - 2, rect.bottom() - 10)

        painter.setPen(dim)
        for y in range(rect.top() + 58, rect.bottom() - 34, 34):
            painter.drawLine(rect.left() + 8, y, rect.left() + 18, y)
        for x in range(rect.right() - 82, rect.right() - 18, 10):
            painter.fillRect(QRect(x, rect.top() + 8, 4, 18), violet)

        if self.tag:
            font = painter.font()
            font.setPointSize(7)
            font.setBold(True)
            painter.setFont(font)
            painter.setPen(violet)
            painter.drawText(rect.adjusted(18, 8, -18, 0), Qt.AlignRight | Qt.AlignTop, self.tag)
        painter.end()


class GalleryGridDelegate(QStyledItemDelegate):
    """Reports the grid cell as the size of every gallery item.

    The gallery is a fixed grid - setGridSize() already decides the cell - but
    the view still has to be *told* that, and it asks the delegate. Without this
    it measures a row's own contents instead, and because rows are inserted in
    one bulk call carrying only their text (the alternative, adding them one at
    a time with the icon attached, is an order of magnitude slower), what it
    measures is text height. With setUniformItemSizes(True) that wrong height is
    then cached and used for every cell in the grid, so thumbnails render
    clipped to a sliver and hit-testing stops finding rows. Nothing re-measures
    it afterwards - not setIconSize, setGridSize, reset(), doItemsLayout(),
    toggling uniform sizes, or a repaint - so the size has to be correct the
    first time it is asked for, which is what this does.

    Only sizeHint is overridden; painting stays with QStyledItemDelegate, which
    is what the view would have used anyway. uniformItemSizes means this is
    asked once per layout, not once per row, so it costs nothing while
    scrolling."""

    def __init__(self, view: QListWidget):
        super().__init__(view)
        self._view = view

    def sizeHint(self, option, index) -> QSize:
        grid = self._view.gridSize()
        if grid.isValid() and not grid.isEmpty():
            return grid
        return super().sizeHint(option, index)


class MediaGallery(QListWidget):
    def __init__(self, viewer):
        super().__init__()
        self.viewer = viewer
        self.setSelectionMode(QListWidget.ExtendedSelection)
        self.setDragEnabled(False)
        self.setSelectionRectVisible(False)
        self._drag_start = QPoint()
        self._drag_allowed = False
        self._selection_anchor_row = -1

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self.viewer, "queue_gallery_viewport_refresh"):
            self.viewer.queue_gallery_viewport_refresh()

    def item_at_gallery_point(self, point: QPoint):
        item = self.itemAt(point)
        if item:
            return item
        for row in range(self.count()):
            candidate = self.item(row)
            if candidate and self.visualItemRect(candidate).contains(point):
                return candidate
        return None

    def save_explore_item_at(self, point: QPoint) -> bool:
        item = self.item_at_gallery_point(point)
        if not item or not self.viewer.explore_mode:
            return False
        row = self.row(item)
        if not (0 <= row < len(self.viewer.visible_entries)):
            return False

        entry = self.viewer.visible_entries[row]
        keep_group = item.isSelected() and len(self.selectedItems()) > 1
        if not keep_group:
            self.viewer.clear_transfer_group()
            self.clearSelection()
            item.setSelected(True)
            self._selection_anchor_row = row

        self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
        self.viewer.select_media(row)

        if not entry.get("remote"):
            return True

        write_app_log(
            f"explore middle-click save post={entry.get('post_id')} "
            f"selected={len(self.selectedItems())}"
        )
        if self.viewer.saved_path_for_explore_entry(entry):
            self.viewer.statusBar().showMessage("That Explore item is already saved.")
        elif self.viewer.entry_is_saving(entry):
            self.viewer.statusBar().showMessage("That Explore item is already saving.")
        else:
            self.viewer.save_current_explore_entry()
        return True

    def viewportEvent(self, event):
        event_type = event.type()
        if event_type == QEvent.MouseButtonPress:
            self.handle_viewport_press(event)
            return True
        if event_type == QEvent.MouseMove and event.buttons() & Qt.LeftButton:
            self.handle_viewport_move(event)
            return True
        if event_type == QEvent.MouseButtonRelease and event.button() == Qt.LeftButton:
            self._drag_allowed = False
            event.accept()
            return True
        if event_type == QEvent.MouseButtonDblClick and event.button() == Qt.LeftButton:
            point = event.position().toPoint()
            item = self.itemAt(point)
            if item:
                self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
                self.viewer.select_media(self.row(item))
                self.viewer.open_media_popout(self.row(item))
            event.accept()
            return True
        return super().viewportEvent(event)

    def keyPressEvent(self, event):
        if event.matches(QKeySequence.Copy):
            # Copy the selected images themselves, not the item labels.
            self.viewer.copy_selected_media()
            event.accept()
            return
        super().keyPressEvent(event)

    def handle_viewport_press(self, event):
        point = event.position().toPoint()
        item = self.itemAt(point)
        if event.button() == Qt.MiddleButton:
            if self.viewer.explore_mode:
                self.save_explore_item_at(point)
            event.accept()
            return
        if event.button() == Qt.RightButton:
            if item:
                row = self.row(item)
                if not item.isSelected() or len(self.selectedItems()) <= 1:
                    self.viewer.clear_transfer_group()
                    self.clearSelection()
                    item.setSelected(True)
                    self._selection_anchor_row = row
                self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
                self.viewer.select_media(row)
            self.viewer.show_action_bar(event.globalPosition().toPoint())
            event.accept()
            return
        if event.button() != Qt.LeftButton:
            return

        self._drag_start = point
        self._drag_allowed = False
        if not item:
            self.clearSelection()
            self._selection_anchor_row = -1
            event.accept()
            return

        row = self.row(item)
        modifiers = QApplication.keyboardModifiers()
        if modifiers & Qt.ShiftModifier:
            self.select_range(row)
        elif modifiers & Qt.ControlModifier:
            item.setSelected(not item.isSelected())
            self._selection_anchor_row = row
        else:
            if item.isSelected() and len(self.selectedItems()) > 1 and self.point_is_on_icon(item, point):
                self._drag_allowed = True
            else:
                self.viewer.clear_transfer_group()
                self.clearSelection()
                item.setSelected(True)
                self._drag_allowed = self.point_is_on_icon(item, point)
            self._selection_anchor_row = row
        self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
        self.viewer.select_media(row)
        event.accept()

    def handle_viewport_move(self, event):
        if not self._drag_allowed:
            event.accept()
            return
        distance = (event.position().toPoint() - self._drag_start).manhattanLength()
        if distance >= QApplication.startDragDistance() and self.selectedItems():
            self.startDrag(Qt.CopyAction | Qt.MoveAction)
            self._drag_allowed = False
        event.accept()

    def mousePressEvent(self, event):
        if event.button() == Qt.MiddleButton and self.viewer.explore_mode:
            self.save_explore_item_at(event.position().toPoint())
            event.accept()
            return
        if event.button() == Qt.RightButton:
            item = self.itemAt(event.position().toPoint())
            if item and not item.isSelected():
                self.setCurrentItem(item)
            self.viewer.show_action_bar(event.globalPosition().toPoint())
            event.accept()
            return
        self._drag_start = event.position().toPoint()
        item = self.itemAt(self._drag_start)
        self._drag_allowed = bool(item and self.point_is_on_icon(item, self._drag_start))
        modifiers = QApplication.keyboardModifiers()
        if event.button() == Qt.LeftButton:
            if not item:
                self.clearSelection()
                self._selection_anchor_row = -1
                self._drag_allowed = False
                event.accept()
                return
            row = self.row(item)
            if modifiers & Qt.ShiftModifier:
                self.select_range(row)
                self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
                self.viewer.select_media(row)
                self._drag_allowed = False
            elif modifiers & Qt.ControlModifier:
                item.setSelected(not item.isSelected())
                self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
                self.viewer.select_media(row)
                self._selection_anchor_row = row
                self._drag_allowed = False
            else:
                self.viewer.clear_transfer_group()
                self.clearSelection()
                item.setSelected(True)
                self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
                self.viewer.select_media(row)
                self._selection_anchor_row = row
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if event.buttons() & Qt.LeftButton:
            if not self._drag_allowed:
                event.accept()
                return
            distance = (event.position().toPoint() - self._drag_start).manhattanLength()
            if distance >= QApplication.startDragDistance() and self.selectedItems():
                self.startDrag(Qt.CopyAction | Qt.MoveAction)
                return
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._drag_allowed = False
            event.accept()
            return
        self._drag_allowed = False
        super().mouseReleaseEvent(event)

    def select_range(self, row: int):
        if self._selection_anchor_row < 0:
            current = self.currentRow()
            self._selection_anchor_row = current if current >= 0 else row
        start, end = sorted((self._selection_anchor_row, row))
        self.clearSelection()
        for index in range(start, end + 1):
            item = self.item(index)
            if item:
                item.setSelected(True)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.LeftButton:
            item = self.itemAt(event.position().toPoint())
            if item:
                self.setCurrentItem(item, QItemSelectionModel.NoUpdate)
                self.viewer.select_media(self.row(item))
                self.viewer.open_media_popout(self.row(item))
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def wheelEvent(self, event):
        if QApplication.keyboardModifiers() & Qt.ControlModifier:
            self.viewer.adjust_gallery_zoom(event.angleDelta().y() or event.pixelDelta().y())
            event.accept()
            return
        bar = self.verticalScrollBar()
        if not bar:
            super().wheelEvent(event)
            return

        pixel_delta = event.pixelDelta().y()
        angle_delta = event.angleDelta().y()
        if pixel_delta:
            raw_delta = -pixel_delta
        elif angle_delta:
            raw_delta = -(angle_delta / 120) * max(18, bar.singleStep() * 3)
        else:
            super().wheelEvent(event)
            return

        visible_cap = max(32, min(self.gridSize().height() * 1.15, self.viewport().height() * 0.34))
        smooth_delta = max(-visible_cap, min(visible_cap, raw_delta))
        bar.setValue(round(bar.value() + smooth_delta))
        event.accept()

    def point_is_on_icon(self, item: QListWidgetItem, point: QPoint) -> bool:
        rect = self.visualItemRect(item)
        icon_size = self.iconSize()
        left = rect.left() + max(0, (rect.width() - icon_size.width()) // 2)
        top = rect.top() + 8
        icon_rect = QRect(left, top, icon_size.width(), icon_size.height())
        return icon_rect.contains(point)

    def startDrag(self, supported_actions):
        paths = self.viewer.selected_paths()
        if not paths:
            return
        self.viewer.remember_selection(paths)
        mime = QMimeData()
        mime.setData(DRAG_MIME, "\n".join(str(path) for path in paths).encode("utf-8"))
        drag = QDrag(self)
        drag.setMimeData(mime)
        drag.setPixmap(self.drag_badge(len(paths)))
        drag.setHotSpot(QPoint(28, 18))
        drag.exec(Qt.CopyAction | Qt.MoveAction, Qt.MoveAction)

    def drag_badge(self, count: int) -> QPixmap:
        text = f"{count} file" if count == 1 else f"{count} files"
        width = max(92, 22 + len(text) * 8)
        pixmap = QPixmap(width, 42)
        pixmap.fill(Qt.transparent)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.setBrush(QColor(self.viewer.ui_colors.get("accent", DEFAULT_UI_COLORS["accent"])))
        painter.setPen(QColor(self.viewer.ui_colors.get("accent_light", DEFAULT_UI_COLORS["accent_light"])))
        painter.drawRoundedRect(1, 1, width - 2, 40, 9, 9)
        painter.setPen(QColor("white"))
        font = QFont("Segoe UI", 10)
        font.setBold(True)
        painter.setFont(font)
        painter.drawText(pixmap.rect(), Qt.AlignCenter, text)
        painter.end()
        return pixmap


class PreviewScrollArea(QScrollArea):
    def __init__(self, viewer):
        super().__init__()
        self.viewer = viewer
        self._panning = False
        self._pan_start = QPoint()
        self._h_start = 0
        self._v_start = 0
        self.setWidgetResizable(False)
        self.setAlignment(Qt.AlignCenter)
        self.setFrameShape(QFrame.NoFrame)
        self.setObjectName("preview")

    def wheelEvent(self, event):
        if self.viewer.current_index >= 0:
            if event.angleDelta().y() > 0:
                self.viewer.zoom_in()
            else:
                self.viewer.zoom_out()
            event.accept()
            return
        super().wheelEvent(event)

    def mousePressEvent(self, event):
        if event.button() == Qt.RightButton:
            self.viewer.show_action_bar(event.globalPosition().toPoint())
            event.accept()
            return
        if event.button() == Qt.LeftButton and not self.viewer.fit_to_frame:
            self._panning = True
            self._pan_start = event.position().toPoint()
            self._h_start = self.horizontalScrollBar().value()
            self._v_start = self.verticalScrollBar().value()
            self.setCursor(Qt.ClosedHandCursor)
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._panning:
            delta = event.position().toPoint() - self._pan_start
            self.horizontalScrollBar().setValue(self._h_start - delta.x())
            self.verticalScrollBar().setValue(self._v_start - delta.y())
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._panning and event.button() == Qt.LeftButton:
            self._panning = False
            self.setCursor(Qt.ArrowCursor)
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.viewer.toggle_preview_mode()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)


class PinFolderList(QListWidget):
    def __init__(self, viewer):
        super().__init__()
        self.viewer = viewer
        self.setAcceptDrops(True)
        self.viewport().setAcceptDrops(True)
        self.setDragDropMode(QListWidget.DropOnly)
        self.setDefaultDropAction(Qt.MoveAction)
        self.setDropIndicatorShown(False)
        self._hover_row = -1
        self._hover_alpha = 80
        self._hover_direction = 1
        self._pulse_timer = QTimer(self)
        self._pulse_timer.setInterval(35)
        self._pulse_timer.timeout.connect(self.pulse_hover)

    def dragEnterEvent(self, event):
        if event.mimeData().hasFormat(DRAG_MIME):
            event.setDropAction(Qt.MoveAction)
            event.accept()

    def dragMoveEvent(self, event):
        if event.mimeData().hasFormat(DRAG_MIME):
            row = self.row(self.itemAt(event.position().toPoint()))
            self.set_drag_hover_row(row)
            event.setDropAction(Qt.MoveAction)
            event.accept()

    def dragLeaveEvent(self, event):
        self.set_drag_hover_row(-1)
        super().dragLeaveEvent(event)

    def dropEvent(self, event):
        self.set_drag_hover_row(-1)
        item = self.itemAt(event.position().toPoint())
        if not item:
            return
        row = self.row(item)
        if not 0 <= row < len(self.viewer.pinned_folders):
            return
        destination = Path(self.viewer.pinned_folders[row])
        paths = self.paths_from_mime(event.mimeData())
        self.viewer.move_or_copy_paths(paths, destination)
        event.setDropAction(Qt.MoveAction)
        event.accept()

    def paths_from_mime(self, mime) -> list[Path]:
        if mime.hasFormat(DRAG_MIME):
            raw = bytes(mime.data(DRAG_MIME)).decode("utf-8", errors="ignore")
            return [Path(line) for line in raw.splitlines() if line.strip()]
        return []

    def set_drag_hover_row(self, row: int):
        if row == self._hover_row:
            return
        self._hover_row = row
        if 0 <= row < self.count():
            self._hover_alpha = 80
            self._hover_direction = 1
            if not self._pulse_timer.isActive():
                self._pulse_timer.start()
            self.pulse_hover()
        else:
            self._pulse_timer.stop()
            self.viewport().update()

    def pulse_hover(self):
        if not 0 <= self._hover_row < self.count():
            self._pulse_timer.stop()
            return
        self._hover_alpha += self._hover_direction * 8
        if self._hover_alpha >= 190:
            self._hover_alpha = 190
            self._hover_direction = -1
        elif self._hover_alpha <= 80:
            self._hover_alpha = 80
            self._hover_direction = 1
        self.viewport().update()

    def paintEvent(self, event):
        super().paintEvent(event)
        if not 0 <= self._hover_row < self.count():
            return
        item = self.item(self._hover_row)
        rect = self.visualItemRect(item).adjusted(3, 3, -3, -3)
        if not rect.isValid():
            return
        painter = QPainter(self.viewport())
        painter.setRenderHint(QPainter.Antialiasing)
        color = QColor(self.viewer.ui_colors.get("accent", DEFAULT_UI_COLORS["accent"]))
        color.setAlpha(self._hover_alpha)
        painter.setBrush(color)
        painter.setPen(QColor("#bfaaff"))
        painter.drawRoundedRect(rect, 8, 8)
        painter.setPen(QColor("white"))
        painter.drawText(rect.adjusted(10, 0, -10, 0), Qt.AlignVCenter | Qt.AlignLeft, item.text())
        painter.end()


class IndexWorker(QThread):
    progress = Signal(int, int)
    # `object`, not `list`: a list-typed signal makes PySide convert every entry
    # dict to a Qt map and back again - ~3.5s for this library, most of it a
    # solid freeze on the UI thread. An object is handed over by reference.
    finished_index = Signal(str, object)
    index_details = Signal(str, object)
    failed = Signal(str)

    def __init__(self, folder: Path, cache: dict, metadata: dict | None = None):
        super().__init__()
        self.folder = folder
        self.cache = cache
        # The app's own copy of this folder's saved metadata, when it has one.
        # Parsing the ~100MB file again costs ~0.8s with the GIL held - a freeze
        # of the whole UI for that long on every re-index.
        self.metadata = metadata

    def run(self):
        # Same reasoning as parse_saved_metadata_text(): building ~50k entries
        # sets off full GC passes over the whole heap mid-run, each a UI freeze.
        # The entries are long-lived, so they are frozen before collection resumes.
        enabled = gc.isenabled()
        gc.disable()
        try:
            self._run_index()
        finally:
            gc.freeze()
            if enabled:
                gc.enable()

    def _run_index(self):
        try:
            # os.scandir() reuses the stat info Windows already returned as part of
            # the directory listing itself, instead of Path.iterdir() + a separate
            # Path.stat() syscall per file (which also re-runs one inside
            # is_media()'s path.is_file() check) - roughly 15x faster for large
            # folders, which is most of why switching to a big Saved library was slow.
            scanned: list[tuple[Path, object]] = []
            with os.scandir(self.folder) as it:
                for direntry in it:
                    if self.isInterruptionRequested():
                        return
                    try:
                        if not direntry.is_file():
                            continue
                        # splitext on the plain name, not Path(name).suffix: the
                        # Path was constructed and thrown away once per file just
                        # to read an extension, and pathlib's parsing is the most
                        # expensive thing in this loop by a wide margin.
                        if os.path.splitext(direntry.name)[1].lower() not in MEDIA_EXTENSIONS:
                            continue
                        stat = direntry.stat()
                    except OSError:
                        continue
                    scanned.append((Path(direntry.path), stat))
            total = len(scanned)
            entries = []
            folder_key = str(self.folder)
            change_times = folder_change_times(self.folder)
            folder_cache = self.cache.get(folder_key, {})
            loaded_metadata = None
            if self.metadata is not None:
                saved_metadata = self.metadata
            else:
                saved_metadata = loaded_metadata = load_saved_metadata(self.folder)
            # Progress is reported on a wall-clock interval rather than every 50
            # files. Each emit is a queued cross-thread call whose slot repaints
            # the progress row and rewrites the status bar, so on a 46k-file
            # library the old "every 50" rule fired ~920 times and the main
            # thread spent more time drawing progress than this thread spent
            # indexing - which is what made opening Saved feel like a freeze.
            next_report = time.monotonic() + 0.1
            for index, (path, stat) in enumerate(scanned, start=1):
                if self.isInterruptionRequested():
                    return
                key = str(path)
                cached = folder_cache.get(key)
                if cached and cached.get("mtime") == stat.st_mtime and cached.get("size") == stat.st_size:
                    entry = normalized_entry(path, stat, cached)
                else:
                    entry = normalized_entry(path, stat)
                saved_meta = saved_metadata.get(path.name) or saved_metadata.get(key)
                if isinstance(saved_meta, dict):
                    saved_tags = [str(tag) for tag in saved_meta.get("tags", []) if str(tag).strip()]
                    if saved_tags:
                        entry["tags"] = sorted(
                            {*tags_without_auto_save_name(entry.get("tags", []), path), *saved_tags}
                        )
                    categories = saved_meta.get("tag_categories")
                    if isinstance(categories, dict):
                        entry["tag_categories"] = categories
                    for field in ["site", "source_url", "media_url", "saved_at", "uploaded_at"]:
                        if saved_meta.get(field):
                            entry[field] = saved_meta.get(field)
                    entry["saved_remote"] = True
                moved_at = (saved_meta.get("moved_at") if isinstance(saved_meta, dict) else None) or change_times.get(path.name)
                if moved_at:
                    entry["moved_at"] = moved_at
                else:
                    entry.pop("moved_at", None)
                entries.append(entry)
                if index == total or time.monotonic() >= next_report:
                    next_report = time.monotonic() + 0.1
                    self.progress.emit(index, total)
            entries.sort(key=lambda item: item["name"].lower())
            # Handed to the UI so it can keep this parse instead of doing it again.
            self.index_details.emit(folder_key, {"metadata": loaded_metadata})
            self.finished_index.emit(folder_key, entries)
        except Exception as exc:
            self.failed.emit(str(exc))


class SavedMetadataPreloadWorker(QThread):
    """Parses a saved folder's metadata off the UI thread, so the first move
    into that folder doesn't parse a ~100MB file in the middle of the click."""

    loaded = Signal(str, object)

    def __init__(self, folder: Path):
        super().__init__()
        self.folder = folder

    def run(self):
        try:
            data = load_saved_metadata_in_background(self.folder)
        except Exception:
            return
        if isinstance(data, dict) and not self.isInterruptionRequested():
            self.loaded.emit(str(self.folder), data)


SAVED_INDEX_DIRTY_ALL = "all"


def saved_listing_fingerprint(entries) -> int:
    """Order-independent fingerprint of a folder listing: (name, size, mtime) of
    every media file, XOR-combined. Same value from an index's entries or from a
    fresh directory scan when nothing on disk has changed."""
    value = 0
    for name, size, mtime in entries:
        value ^= hash((name, size, mtime))
    return value


class SavedIndexCheckWorker(QThread):
    """Re-lists a saved folder in the background after a cached index was
    reused, to catch changes made outside the app (Explorer, another program).
    One directory scan - no metadata parse, no per-file work."""

    checked = Signal(str, object)

    def __init__(self, folder: Path):
        super().__init__()
        self.folder = folder

    def run(self):
        listing = []
        try:
            with os.scandir(self.folder) as iterator:
                for direntry in iterator:
                    if self.isInterruptionRequested():
                        return
                    try:
                        if not direntry.is_file():
                            continue
                        if os.path.splitext(direntry.name)[1].lower() not in MEDIA_EXTENSIONS:
                            continue
                        stat = direntry.stat()
                    except OSError:
                        continue
                    listing.append((direntry.name, stat.st_size, stat.st_mtime))
        except OSError:
            return
        self.checked.emit(str(self.folder), saved_listing_fingerprint(listing))


# Thumbnail files known to exist, so the ThumbnailWorker started on every view
# switch doesn't stat all ~60k of them again (a Path object and a stat each,
# competing with the UI for the GIL). Cleared whenever the cache is pruned.
KNOWN_THUMBNAILS: set[str] = set()


class ThumbnailWorker(QThread):
    thumb_ready = Signal(str, str)
    progress = Signal(int, int)

    def __init__(self, entries: list[dict]):
        super().__init__()
        self.entries = entries

    def run(self):
        known = KNOWN_THUMBNAILS
        exists = os.path.exists
        pending = []
        for entry in self.entries:
            if self.isInterruptionRequested():
                return
            thumb = entry.get("thumb", "")
            if not thumb or thumb in known:
                continue
            if exists(thumb):
                known.add(thumb)
                continue
            pending.append(entry)
        total = len(pending)
        if not pending:
            self.progress.emit(0, 0)
            return

        def build_thumb(entry: dict) -> tuple[str, str] | None:
            source = Path(entry["path"])
            destination = Path(entry["thumb"])
            try:
                create_thumbnail(source, destination, entry["type"])
                return entry["path"], entry["thumb"]
            except Exception:
                return None

        executor = local_thread_pool(DISK_WORKER_CEILING, pending=len(pending))
        try:
            futures = [executor.submit(build_thumb, entry) for entry in pending]
            for index, future in enumerate(concurrent.futures.as_completed(futures), start=1):
                if self.isInterruptionRequested():
                    executor.shutdown(wait=False, cancel_futures=True)
                    return
                result = future.result()
                if result:
                    KNOWN_THUMBNAILS.add(result[1])
                    self.thumb_ready.emit(result[0], result[1])
                if index % 10 == 0 or index == total:
                    self.progress.emit(index, total)
        finally:
            executor.shutdown(wait=False, cancel_futures=True)


class FullQualityThumbnailWorker(QThread):
    thumb_ready = Signal(str, str)

    def __init__(self, tasks: list[dict]):
        super().__init__()
        self.tasks = [dict(task) for task in tasks]

    def run(self):
        pending = [task for task in self.tasks if not Path(task.get("thumb", "")).exists()]
        if not pending:
            return

        def build_thumb(task: dict) -> tuple[str, str] | None:
            source = Path(task["source"])
            destination = Path(task["thumb"])
            try:
                create_full_quality_thumbnail(source, destination, task.get("type", "image"), int(task.get("side") or THUMB_SIZE))
                return str(source), str(destination)
            except Exception:
                return None

        executor = local_thread_pool(DISK_WORKER_CEILING, pending=len(pending))
        try:
            futures = [executor.submit(build_thumb, task) for task in pending]
            for future in concurrent.futures.as_completed(futures):
                if self.isInterruptionRequested():
                    executor.shutdown(wait=False, cancel_futures=True)
                    return
                result = future.result()
                if result:
                    self.thumb_ready.emit(result[0], result[1])
        finally:
            executor.shutdown(wait=False, cancel_futures=True)


class DuplicateScanWorker(QThread):
    progress = Signal(str, int, int)
    finished_scan = Signal(list, int, int)
    failed = Signal(str)

    def __init__(self, folders: list[Path], threshold: int, allowed_types: set[str]):
        super().__init__()
        self.folders = [Path(folder) for folder in folders]
        self.threshold = int(threshold)
        self.allowed_types = set(allowed_types) or {"image", "gif", "video"}

    def stopping(self) -> bool:
        return self.isInterruptionRequested()

    def load_cache(self) -> dict:
        try:
            data = json.loads(duplicate_hash_file().read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return data if isinstance(data, dict) else {}

    def save_cache(self, cache: dict):
        try:
            duplicate_hash_file().write_text(json.dumps(cache), encoding="utf-8")
        except OSError as exc:
            write_app_log(f"duplicate hash cache save failed error={exc}")

    def collect_files(self) -> list[tuple[Path, object]]:
        found: list[tuple[Path, object]] = []
        seen: set[str] = set()
        for folder in self.folders:
            if not folder.exists():
                continue
            try:
                with os.scandir(folder) as entries:
                    for direntry in entries:
                        if self.stopping():
                            return found
                        try:
                            if not direntry.is_file():
                                continue
                            suffix = Path(direntry.name).suffix.lower()
                            if suffix not in MEDIA_EXTENSIONS:
                                continue
                            if media_type(Path(direntry.name)) not in self.allowed_types:
                                continue
                            if direntry.path in seen:
                                continue
                            stat = direntry.stat()
                        except OSError:
                            continue
                        seen.add(direntry.path)
                        found.append((Path(direntry.path), stat))
            except OSError:
                continue
        return found

    def run(self):
        try:
            self.progress.emit("Looking for media files...", 0, 0)
            files = self.collect_files()
            if self.stopping():
                return
            if not files:
                self.finished_scan.emit([], 0, 0)
                return

            cache = self.load_cache()
            records: list[dict] = []
            pending: list[tuple[Path, object]] = []
            for path, stat in files:
                cached = cache.get(str(path))
                if (
                    isinstance(cached, dict)
                    and cached.get("mtime") == stat.st_mtime
                    and cached.get("size") == stat.st_size
                    and cached.get("dhash")
                ):
                    records.append(
                        {
                            "path": str(path),
                            "size": int(stat.st_size),
                            "mtime": float(stat.st_mtime),
                            "dhash": [int(value) for value in cached.get("dhash") or []],
                            "phash": [int(value) for value in cached.get("phash") or []],
                        }
                    )
                else:
                    pending.append((path, stat))

            total = len(files)
            done = total - len(pending)
            self.progress.emit(f"Fingerprinting media ({done} already cached)...", done, total)

            if pending:
                def build(item):
                    path, stat = item
                    signature = media_signature(path)
                    if not signature:
                        return None
                    return {
                        "path": str(path),
                        "size": int(stat.st_size),
                        "mtime": float(stat.st_mtime),
                        "dhash": signature["dhash"],
                        "phash": signature["phash"],
                    }

                # Videos dominate the cost here and decoding releases the GIL, so a
                # pool genuinely helps. Width comes from the governor and the threads
                # run below normal priority, so a scan can use the whole machine
                # without the UI or anything else losing responsiveness.
                executor = local_thread_pool(DISK_WORKER_CEILING, pending=len(pending))
                try:
                    futures = [executor.submit(build, item) for item in pending]
                    for future in concurrent.futures.as_completed(futures):
                        if self.stopping():
                            executor.shutdown(wait=False, cancel_futures=True)
                            return
                        done += 1
                        record = future.result()
                        if record:
                            records.append(record)
                            cache[record["path"]] = {
                                "mtime": record["mtime"],
                                "size": record["size"],
                                "dhash": record["dhash"],
                                "phash": record["phash"],
                            }
                        if done % 25 == 0 or done == total:
                            self.progress.emit("Fingerprinting media...", done, total)
                finally:
                    executor.shutdown(wait=False, cancel_futures=True)

            if self.stopping():
                return

            # Drop cache entries for files that no longer exist so the file does
            # not grow forever as the library changes.
            live_paths = {str(path) for path, _stat in files}
            for key in [key for key in cache if key not in live_paths]:
                cache.pop(key, None)
            self.save_cache(cache)

            self.progress.emit("Comparing fingerprints...", 0, len(records))
            groups = group_similar_signatures(
                records,
                self.threshold,
                should_stop=self.stopping,
                progress=lambda done_count, total_count: self.progress.emit(
                    "Comparing fingerprints...", done_count, total_count
                ),
            )
            if self.stopping():
                return

            payload = []
            for members in groups:
                items = [
                    {"path": records[index]["path"], "size": records[index]["size"]}
                    for index in members
                ]
                items.sort(key=lambda item: (-item["size"], item["path"].lower()))
                wasted = sum(item["size"] for item in items[1:])
                payload.append({"items": items, "wasted": wasted})
            # Biggest reclaimable space first - that is what the user is here for.
            payload.sort(key=lambda group: (-group["wasted"], -len(group["items"])))
            duplicate_count = sum(len(group["items"]) - 1 for group in payload)
            self.finished_scan.emit(payload, len(records), duplicate_count)
        except Exception as exc:
            self.failed.emit(str(exc))


class CacheMaintenanceWorker(QThread):
    # The two "freed" values are byte counts, and a Signal(int) parameter is a
    # 32-bit C++ int in PySide6 - emitting anything over ~2.1GB through one raises
    # OverflowError from inside run(), which crashes the app. That is exactly what
    # happened once the explore cache grew enough for a single prune to free 3.2GB
    # (smaller prunes had always squeaked under the limit). Byte counts must be
    # qlonglong; the deleted-file counts are genuinely small so they stay int.
    finished_prune = Signal(int, "qlonglong", int, "qlonglong")

    def __init__(self, explore_max_bytes: int, thumb_max_bytes: int, saved_folders=(), hq_side: int = THUMB_SIZE):
        super().__init__()
        self.explore_max_bytes = explore_max_bytes
        self.thumb_max_bytes = thumb_max_bytes
        self.saved_folders = list(saved_folders)
        self.hq_side = hq_side

    def run(self):
        explore_deleted, explore_freed = prune_cache_folder(explore_cache_folder(), self.explore_max_bytes)
        keep_last = None
        if self.saved_folders:
            keep_last = lambda: live_saved_thumbnail_names(self.saved_folders, self.hq_side)
        thumb_deleted, thumb_freed = prune_cache_folder(thumbnail_folder(), self.thumb_max_bytes, keep_last)
        if explore_deleted or thumb_deleted:
            write_app_log(
                f"cache prune explore_deleted={explore_deleted} explore_freed={format_size(explore_freed)} "
                f"thumb_deleted={thumb_deleted} thumb_freed={format_size(thumb_freed)}"
            )
        self.finished_prune.emit(explore_deleted, explore_freed, thumb_deleted, thumb_freed)


class ExploreWorker(QThread):
    progress = Signal(int, int)
    thumb_ready = Signal(str, str)
    finished_explore = Signal(object, int)
    failed = Signal(str)

    def __init__(
        self,
        site_key: str,
        tags: str,
        page: int = 1,
        limit: int = EXPLORE_LIMIT,
        result_offset: int | None = None,
    ):
        super().__init__()
        self.site_key = site_key
        self.tags = " ".join(tags.split())
        self.page = max(1, page)
        self.limit = limit
        self.result_offset = max(0, int(result_offset)) if result_offset is not None else None
        self.total_count = 0

    def run(self):
        try:
            write_explore_log(
                f"worker start site={self.site_key} page={self.page} limit={self.limit} "
                f"offset={self.result_offset} tags={self.tags!r}"
            )
            sites = ["gelbooru", "e621", "realbooru", "rule34xxx"] if self.site_key == "all" else [self.site_key]
            entries = []
            errors = []
            for site in sites:
                if self.isInterruptionRequested():
                    write_explore_log(f"worker interrupted before site={site}")
                    return
                try:
                    entries.extend(self.fetch_site(site))
                except urllib.error.HTTPError as exc:
                    try:
                        html_entries = self.fetch_site_html(site)
                    except Exception:
                        html_entries = []
                    if html_entries:
                        entries.extend(html_entries)
                    else:
                        errors.append(f"{EXPLORE_SITE_LABELS.get(site, site)}: {exc.code} {exc.reason}")
                except Exception as exc:
                    try:
                        html_entries = self.fetch_site_html(site)
                    except Exception:
                        html_entries = []
                    if html_entries:
                        entries.extend(html_entries)
                    else:
                        errors.append(f"{EXPLORE_SITE_LABELS.get(site, site)}: {exc}")
            if not entries and errors:
                write_explore_log(f"worker failed errors={errors}")
                raise RuntimeError("; ".join(errors))
            write_explore_log(f"worker finish entries={len(entries)} total={self.total_count}")
            self.finished_explore.emit(entries, self.total_count)
            return
        except Exception as exc:
            write_explore_log(f"worker exception {type(exc).__name__}: {exc}")
            self.failed.emit(str(exc))

    def legacy_pid_and_skip(self) -> tuple[int, int]:
        """Translate this request's item offset into the gelbooru-clone DAPI's own
        pagination units.

        The two fetch paths for these sites do NOT paginate the same way:
        `fetch_legacy_html` (via explore_search_urls) sends `pid=<raw item offset>`,
        while the DAPI's `pid` is a *page index* over `limit`-sized pages. This used
        to send `pid=page-1` to the DAPI while the HTML fallback sent the learned
        item offset, so "page 52" meant item 5100 to the API and item 2141 to the
        HTML scraper - and since these sites bounce between the two paths constantly
        (503/rate-limit -> fallback), the same page number showed completely
        different results depending on which path happened to answer. Item offset is
        the only system both can express, so it wins: convert to a page index here
        and drop the leading `skip` rows the DAPI page carries before our offset."""
        limit = max(1, int(self.limit))
        if self.result_offset is None:
            return max(0, self.page - 1), 0
        offset = max(0, int(self.result_offset))
        return offset // limit, offset % limit

    def fetch_site(self, site: str) -> list[dict]:
        if site == "e621":
            return self.fetch_e621()
        label, base_url = LEGACY_BOORU_SITES.get(site, LEGACY_BOORU_SITES["gelbooru"])
        return self.fetch_legacy_booru(label, base_url)

    def fetch_site_html(self, site: str) -> list[dict]:
        if site == "e621":
            return self.fetch_e621_html()
        label, base_url = LEGACY_BOORU_SITES.get(site, LEGACY_BOORU_SITES["gelbooru"])
        return self.fetch_legacy_html(label, base_url)

    def fetch_legacy_booru(self, label: str, base_url: str) -> list[dict]:
        errors = []
        received_valid_response = False
        try:
            write_explore_log(f"{label} api fetch start page={self.page}")
            api_entries = self.fetch_legacy_api(label, base_url)
            received_valid_response = True
            write_explore_log(f"{label} api fetch returned {len(api_entries)} entries")
            if api_entries:
                return api_entries
        except Exception as exc:
            write_explore_log(f"{label} api fetch failed {type(exc).__name__}: {exc}")
            errors.append(exc)
        try:
            write_explore_log(f"{label} xml fetch start page={self.page}")
            xml_entries = self.fetch_legacy_xml(label, base_url)
            received_valid_response = True
            write_explore_log(f"{label} xml fetch returned {len(xml_entries)} entries")
            if xml_entries:
                return xml_entries
        except Exception as exc:
            write_explore_log(f"{label} xml fetch failed {type(exc).__name__}: {exc}")
            errors.append(exc)
        try:
            write_explore_log(f"{label} html fallback start page={self.page} tags={self.tags!r}")
            html_entries = self.fetch_legacy_html(label, base_url)
            received_valid_response = True
            write_explore_log(f"{label} html fallback returned {len(html_entries)} entries")
            if html_entries:
                return html_entries
        except Exception as exc:
            write_explore_log(f"{label} html fallback failed {type(exc).__name__}: {exc}")
            errors.append(exc)
        if errors and not received_valid_response:
            raise errors[-1]
        return []

    def fetch_legacy_api(self, label: str, base_url: str) -> list[dict]:
        pid, skip = self.legacy_pid_and_skip()
        params = {
            "page": "dapi",
            "s": "post",
            "q": "index",
            "json": "1",
            "limit": str(self.limit),
            "pid": str(pid),
            "tags": self.tags,
        }
        query = urllib.parse.urlencode(with_gelbooru_auth(base_url, params))
        data = fetch_json(f"{base_url}/index.php?{query}", timeout=6)
        raise_if_legacy_api_error(data)
        if isinstance(data, dict):
            attrs = data.get("@attributes") or data.get("attributes") or {}
            try:
                self.total_count = max(self.total_count, int(attrs.get("count") or data.get("count") or 0))
            except (TypeError, ValueError):
                pass
        entries = []
        for post in post_rows(data)[skip:]:
            legacy_image = str(post.get("image") or "").strip()
            legacy_directory = str(post.get("directory") or "").strip("/ ")
            constructed_file = f"/images/{legacy_directory}/{legacy_image}" if legacy_image and legacy_directory else ""
            media_url = absolute_url(base_url, post.get("file_url") or constructed_file or post.get("source"))
            if not media_url:
                continue
            sample_url = absolute_url(base_url, post.get("sample_url"))
            constructed_preview = (
                f"/thumbnails/{legacy_directory}/thumbnail_{legacy_image}"
                if legacy_image and legacy_directory else ""
            )
            preview_url = absolute_url(
                base_url,
                post.get("preview_url") or constructed_preview or sample_url or media_url,
            )
            candidate_urls = [media_url, sample_url, preview_url]
            for candidate in list(candidate_urls):
                candidate_urls.extend(original_url_guesses(candidate))
            kind = media_type_from_url(media_url)
            post_id = str(post.get("id") or hashlib.sha1(media_url.encode("utf-8", errors="ignore")).hexdigest()[:8])
            suffix = url_suffix(media_url)
            tags = unique_tags(str(post.get("tags", "")).split())
            entries.append(
                {
                    "remote": True,
                    "site": label,
                    "path": media_url,
                    "media_url": media_url,
                    "thumb_url": preview_url,
                    "source_url": f"{base_url}/index.php?page=post&s=view&id={post_id}",
                    "post_id": post_id,
                    "name": f"{label.lower()}_{post_id}{suffix}",
                    "size": int(post.get("file_size") or 0),
                    "tags": tags,
                    "tag_categories": {},
                    "candidate_media_urls": [url for url in dict.fromkeys(candidate_urls) if url],
                    "type": kind,
                    "thumb": explore_thumb_path(preview_url or media_url),
                    "uploaded_at": parse_upload_date_string(post.get("created_at") or post.get("change")),
                }
            )
        return entries

    def fetch_legacy_xml(self, label: str, base_url: str) -> list[dict]:
        pid, skip = self.legacy_pid_and_skip()
        params = {
            "page": "dapi",
            "s": "post",
            "q": "index",
            "limit": str(self.limit),
            "pid": str(pid),
            "tags": self.tags,
        }
        root = fetch_xml_root(
            f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}",
            timeout=6,
        )
        raise_if_legacy_xml_api_error(root)
        try:
            self.total_count = max(self.total_count, int(root.attrib.get("count") or 0))
        except (TypeError, ValueError):
            pass
        entries = []
        posts = [root] if str(root.tag).lower().endswith("post") else root.findall(".//post")
        posts = posts[skip:]
        for post in posts:
            attrs = dict(post.attrib)
            legacy_image = str(attrs.get("image") or "").strip()
            legacy_directory = str(attrs.get("directory") or "").strip("/ ")
            constructed_file = f"/images/{legacy_directory}/{legacy_image}" if legacy_image and legacy_directory else ""
            media_url = absolute_url(base_url, attrs.get("file_url") or constructed_file or attrs.get("source"))
            if not media_url:
                continue
            sample_url = absolute_url(base_url, attrs.get("sample_url"))
            constructed_preview = (
                f"/thumbnails/{legacy_directory}/thumbnail_{legacy_image}"
                if legacy_image and legacy_directory else ""
            )
            preview_url = absolute_url(
                base_url,
                attrs.get("preview_url") or constructed_preview or sample_url or media_url,
            )
            candidate_urls = [media_url, sample_url, preview_url]
            for candidate in list(candidate_urls):
                candidate_urls.extend(original_url_guesses(candidate))
            kind = media_type_from_url(media_url)
            post_id = str(attrs.get("id") or hashlib.sha1(media_url.encode("utf-8", errors="ignore")).hexdigest()[:8])
            tags = unique_tags(str(attrs.get("tags", "")).split())
            entries.append(
                {
                    "remote": True,
                    "site": label,
                    "path": media_url,
                    "media_url": media_url,
                    "thumb_url": preview_url,
                    "source_url": f"{base_url}/index.php?page=post&s=view&id={post_id}",
                    "post_id": post_id,
                    "name": f"{label.lower()}_{post_id}{url_suffix(media_url)}",
                    "size": int(attrs.get("file_size") or 0),
                    "tags": tags,
                    "tag_categories": {},
                    "candidate_media_urls": [url for url in dict.fromkeys(candidate_urls) if url],
                    "type": kind,
                    "thumb": explore_thumb_path(preview_url or media_url),
                    "uploaded_at": parse_upload_date_string(attrs.get("created_at") or attrs.get("change")),
                }
            )
        return entries

    def fetch_legacy_html(self, label: str, base_url: str) -> list[dict]:
        site_key = next((key for key, value in LEGACY_BOORU_SITES.items() if value[0] == label), "gelbooru")
        last_error = None
        for page_url in explore_search_urls(
            site_key, self.tags, self.page, self.limit, offset_override=self.result_offset
        ):
            try:
                html_text = fetch_url_bytes(page_url, timeout=8).decode("utf-8", errors="replace")
                entries = self.entries_from_legacy_html(label, base_url, html_text)
                if entries:
                    for entry in entries:
                        entry["page_url"] = page_url
                    return entries
            except Exception as exc:
                last_error = exc
        if last_error:
            raise last_error
        return []

    def entries_from_legacy_html(self, label: str, base_url: str, html_text: str) -> list[dict]:
        entries = []
        seen = set()
        for anchor_attrs, anchor_body in re.findall(r"<a\b([^>]*)>(.*?)</a>", html_text, flags=re.IGNORECASE | re.DOTALL):
            href = html_attrs(anchor_attrs).get("href", "")
            source_url = absolute_url(base_url, unescape(href))
            parsed = urllib.parse.urlparse(source_url)
            query = urllib.parse.parse_qs(parsed.query)
            post_id = (query.get("id") or query.get("amp;id") or [""])[0]
            if not post_id or query.get("page", [""])[0] != "post" or query.get("s", [""])[0] != "view":
                continue
            img_match = re.search(r"<img\b([^>]*)>", anchor_body, flags=re.IGNORECASE | re.DOTALL)
            if not img_match:
                continue
            img_tag = img_match.group(1)
            attrs = html_attrs(img_tag)
            preview_url = absolute_url(base_url, attrs.get("src") or attrs.get("data-src") or "")
            if not preview_url or source_url in seen:
                continue
            seen.add(source_url)
            title = attrs.get("title") or attrs.get("alt") or ""
            listing_tags = unique_tags(text_tags(title))
            # The listing page only ever gives us a static thumbnail image, so the real
            # type is confirmed later by resolve_full_media() once the post is opened.
            # But the site's own tags reliably say "video" for video posts (confirmed
            # against real Rule34.xxx search results), so use that instead of always
            # guessing "image" - otherwise UI that checks entry type before the post is
            # opened (e.g. the right-click Play/Pause controls) stays wrong until then.
            listing_type_guess = "video" if "video" in listing_tags else "image"
            entries.append(
                {
                    "remote": True,
                    "needs_resolve": True,
                    "site": label,
                    "path": preview_url,
                    "media_url": preview_url,
                    "thumb_url": preview_url,
                    "source_url": source_url,
                    "post_id": post_id,
                    "name": f"{label.lower()}_{post_id}{'.mp4' if listing_type_guess == 'video' else '.jpg'}",
                    "size": 0,
                    "tags": listing_tags,
                    "tag_categories": {},
                    "candidate_media_urls": [url for url in dict.fromkeys([*original_url_guesses(preview_url), preview_url]) if url],
                    "type": listing_type_guess,
                    "thumb": explore_thumb_path(preview_url),
                }
            )
            if len(entries) >= self.limit:
                break
        return entries

    def fetch_e621(self) -> list[dict]:
        query = urllib.parse.urlencode({"limit": str(self.limit), "page": str(self.page), "tags": self.tags})
        data = fetch_json(f"https://e621.net/posts.json?{query}")
        posts = data.get("posts", []) if isinstance(data, dict) else []
        entries = []
        for post in posts:
            file_info = post.get("file") or {}
            media_url = url_with_scheme(file_info.get("url"))
            if not media_url:
                continue
            sample = post.get("sample") or {}
            preview = post.get("preview") or {}
            preview_url = url_with_scheme(preview.get("url") or sample.get("url") or media_url)
            kind = media_type_from_url(media_url)
            post_id = str(post.get("id") or hashlib.sha1(media_url.encode("utf-8", errors="ignore")).hexdigest()[:8])
            tags = []
            tag_categories = {}
            tag_data = post.get("tags") or {}
            if isinstance(tag_data, dict):
                for category, values in tag_data.items():
                    if isinstance(values, list):
                        for value in values:
                            tag = str(value)
                            tags.append(tag)
                            tag_categories[tag.lower()] = normalized_tag_category(str(category))
            tags = unique_tags(tags)
            suffix = url_suffix(media_url)
            entries.append(
                {
                    "remote": True,
                    "site": "e621",
                    "path": media_url,
                    "media_url": media_url,
                    "thumb_url": preview_url,
                    "source_url": f"https://e621.net/posts/{post_id}",
                    "post_id": post_id,
                    "name": f"e621_{post_id}{suffix}",
                    "size": int(file_info.get("size") or 0),
                    "tags": tags,
                    "tag_categories": tag_categories,
                    "type": kind,
                    "thumb": explore_thumb_path(preview_url or media_url),
                    "uploaded_at": parse_upload_date_string(post.get("created_at")),
                }
            )
        return entries

    def fetch_e621_html(self) -> list[dict]:
        page_url = explore_search_urls("e621", self.tags, self.page, self.limit)[0]
        html_text = fetch_url_bytes(page_url, timeout=10).decode("utf-8", errors="replace")
        articles = re.findall(r"<article\b[^>]*>", html_text, flags=re.IGNORECASE)
        entries = []
        for tag in articles[: self.limit]:
            attrs = html_attrs(tag)
            media_url = absolute_url("https://e621.net", attrs.get("data-file-url"))
            preview_url = absolute_url("https://e621.net", attrs.get("data-preview-file-url") or attrs.get("data-large-file-url") or media_url)
            post_id = attrs.get("data-id") or hashlib.sha1((media_url or tag).encode("utf-8", errors="ignore")).hexdigest()[:8]
            if not media_url and not preview_url:
                continue
            tags = unique_tags(text_tags(attrs.get("data-tags")))
            tag_categories = {}
            media_url = media_url or preview_url
            kind = media_type_from_url(media_url)
            entries.append(
                {
                    "remote": True,
                    "site": "e621",
                    "path": media_url,
                    "media_url": media_url,
                    "thumb_url": preview_url,
                    "source_url": f"https://e621.net/posts/{post_id}",
                    "post_id": str(post_id),
                    "name": f"e621_{post_id}{url_suffix(media_url)}",
                    "size": int(attrs.get("data-file-size") or 0),
                    "tags": tags,
                    "tag_categories": tag_categories,
                    "type": kind,
                    "thumb": explore_thumb_path(preview_url or media_url),
                }
            )
        return entries


class ExploreThumbnailWorker(QThread):
    thumb_ready = Signal(str, str)
    progress = Signal(int, int)

    def __init__(self, entries: list[dict]):
        super().__init__()
        self.entries = list(entries)

    def run(self):
        pending = [
            entry for entry in self.entries
            if entry.get("remote")
            and (entry.get("thumb_url") or entry.get("media_url"))
            and not Path(entry.get("thumb", "")).exists()
        ]
        total = len(pending)
        if not pending:
            self.progress.emit(0, 0)
            return

        # Rule34.xxx/Realbooru are both fragile under concurrent load (confirmed via
        # 429s, connection resets, and - worse - a burst of thumbnail requests here
        # starving out a popup's own resolution fetch for the same site moments
        # later, leaving it with no tag categories despite retries). Realbooru saves
        # already get the same treatment (REALBOORU_PARALLEL_SAVE_LIMIT); cap
        # thumbnail concurrency the same way when a batch is mostly one of these sites.
        fragile_count = sum(1 for entry in pending if entry_is_realbooru(entry) or entry_is_rule34(entry))
        if pending and fragile_count / len(pending) > 0.5:
            workers = max(1, min(6, len(pending)))
        else:
            workers = max(1, min(EXPLORE_THUMB_WORKERS, len(pending)))
        executor = concurrent.futures.ThreadPoolExecutor(max_workers=workers)
        failed_entries = []
        try:
            futures = {
                executor.submit(
                    save_remote_thumbnail,
                    entry.get("thumb_url") or entry.get("media_url"),
                    Path(entry.get("thumb", "")),
                    entry.get("source_url"),
                    4,
                ): entry
                for entry in pending
            }
            for index, future in enumerate(concurrent.futures.as_completed(futures), start=1):
                if self.isInterruptionRequested():
                    executor.shutdown(wait=False, cancel_futures=True)
                    return
                entry = futures[future]
                try:
                    future.result()
                    if Path(entry.get("thumb", "")).exists():
                        self.thumb_ready.emit(entry["path"], entry["thumb"])
                    else:
                        failed_entries.append(entry)
                except Exception:
                    failed_entries.append(entry)
                if index % 6 == 0 or index == total:
                    self.progress.emit(index, total)
        finally:
            executor.shutdown(wait=False, cancel_futures=True)

        if not failed_entries:
            return

        # A handful of thumbnails routinely fail in that initial burst of up to
        # EXPLORE_THUMB_WORKERS simultaneous requests - some sites (Rule34.xxx and
        # Realbooru especially) rate-limit or reset connections under concurrent load
        # rather than queuing them. Retry at low concurrency instead of leaving the
        # gallery slot permanently blank for the rest of this session. Deliberately
        # bounded (small worker count, short per-item timeout) rather than a fully
        # sequential retry: this worker only gets requestInterruption(), never
        # waited on, so a long-running retry pass left it more likely to still be
        # blocked in a network call - and therefore crash-prone - if the app closes
        # while it's mid-retry.
        time.sleep(0.5)
        if self.isInterruptionRequested():
            return
        retry_workers = min(3, len(failed_entries))
        retry_executor = concurrent.futures.ThreadPoolExecutor(max_workers=retry_workers)
        try:
            retry_futures = {
                retry_executor.submit(
                    save_remote_thumbnail,
                    entry.get("thumb_url") or entry.get("media_url"),
                    Path(entry.get("thumb", "")),
                    entry.get("source_url"),
                    5,
                ): entry
                for entry in failed_entries
            }
            for future in concurrent.futures.as_completed(retry_futures):
                if self.isInterruptionRequested():
                    retry_executor.shutdown(wait=False, cancel_futures=True)
                    return
                entry = retry_futures[future]
                try:
                    future.result()
                    if Path(entry.get("thumb", "")).exists():
                        self.thumb_ready.emit(entry["path"], entry["thumb"])
                except Exception:
                    pass
        finally:
            retry_executor.shutdown(wait=False, cancel_futures=True)


class ExploreCountWorker(QThread):
    count_ready = Signal(int)
    failed = Signal(str)

    def __init__(self, site_key: str, tags: str):
        super().__init__()
        self.site_key = site_key
        self.tags = " ".join(tags.split())
        self.request_key = f"{self.site_key}|{self.tags}"

    def run(self):
        try:
            if self.site_key == "all":
                total = 0
                got_any = False
                for site in ALL_EXPLORE_SITE_KEYS:
                    if self.isInterruptionRequested():
                        return
                    try:
                        if site == "e621":
                            total += max(0, self.fetch_e621_count())
                        else:
                            base_url = LEGACY_BOORU_SITES.get(site, LEGACY_BOORU_SITES["gelbooru"])[1]
                            total += max(0, self.fetch_legacy_count(base_url))
                        got_any = True
                    except Exception:
                        continue
                if not got_any:
                    raise RuntimeError("Could not reach any site to get a result count.")
            elif self.site_key == "e621":
                total = self.fetch_e621_count()
            else:
                base_url = LEGACY_BOORU_SITES.get(self.site_key, LEGACY_BOORU_SITES["gelbooru"])[1]
                total = self.fetch_legacy_count(base_url)
            if not self.isInterruptionRequested():
                self.count_ready.emit(max(0, total))
        except Exception as exc:
            if not self.isInterruptionRequested():
                self.failed.emit(str(exc))

    def fetch_e621_count(self) -> int:
        query = urllib.parse.urlencode({"tags": self.tags})
        errors = []
        for endpoint in (
            f"https://e621.net/counts/posts.json?{query}",
            f"https://e621.net/counts/posts.json?search%5Btags%5D={urllib.parse.quote_plus(self.tags)}",
        ):
            try:
                data = fetch_json(endpoint, timeout=12)
                counts = data.get("counts", {}) if isinstance(data, dict) else {}
                raw_total = counts.get("posts") if isinstance(counts, dict) else None
                if raw_total is None and isinstance(data, dict):
                    raw_total = data.get("post_count") or data.get("count") or data.get("posts")
                if raw_total is not None:
                    return int(raw_total)
            except Exception as exc:
                errors.append(exc)

        tags = [tag for tag in self.tags.split() if tag and not tag.startswith("-") and ":" not in tag]
        if len(tags) == 1 and len(self.tags.split()) == 1:
            try:
                params = urllib.parse.urlencode({"search[name]": tags[0], "limit": "1"})
                data = fetch_json(f"https://e621.net/tags.json?{params}", timeout=12)
                rows = data if isinstance(data, list) else []
                for row in rows:
                    if isinstance(row, dict) and str(row.get("name", "")).lower() == tags[0].lower():
                        return int(row.get("post_count") or 0)
            except Exception as exc:
                errors.append(exc)
        if errors:
            raise errors[-1]
        return 0

    def fetch_legacy_count(self, base_url: str) -> int:
        params = {
            "page": "dapi",
            "s": "post",
            "q": "index",
            "json": "1",
            "limit": "1",
            "pid": "0",
            "tags": self.tags,
        }
        query = urllib.parse.urlencode(with_gelbooru_auth(base_url, params))
        try:
            data = fetch_json(f"{base_url}/index.php?{query}", timeout=10)
            if isinstance(data, dict):
                attrs = data.get("@attributes") or data.get("attributes") or {}
                raw_count = attrs.get("count") if isinstance(attrs, dict) else None
                if raw_count is None:
                    raw_count = data.get("count")
                if raw_count is not None:
                    return int(raw_count)
        except Exception:
            pass

        xml_params = dict(params)
        xml_params.pop("json", None)
        xml_query = urllib.parse.urlencode(with_gelbooru_auth(base_url, xml_params))
        try:
            root = fetch_xml_root(f"{base_url}/index.php?{xml_query}", timeout=10)
            raw_count = root.attrib.get("count") or root.attrib.get("total")
            if raw_count is not None:
                return int(raw_count)
        except Exception:
            pass

        page_url = explore_search_urls(
            next((key for key, value in LEGACY_BOORU_SITES.items() if value[1] in base_url), "gelbooru"),
            self.tags,
            1,
            100,
        )[0]
        html_text = fetch_url_bytes(page_url, timeout=12).decode("utf-8", errors="replace")
        patterns = (
            r'data-(?:post-)?count=["\']([\d,]+)',
            r'(?:total|count)\s*[:=]\s*["\']?([\d,]+)',
            r'(?:of|out of)\s+([\d,]+)\s+(?:posts|results|images)',
        )
        for pattern in patterns:
            match = re.search(pattern, html_text, flags=re.IGNORECASE)
            if match:
                return int(match.group(1).replace(",", ""))
        # Rule34.xxx's current template (and possibly others in this family) no longer
        # prints a literal "N results" anywhere - the only remaining signal is the
        # numbered pagination links themselves (?...&pid=42, &pid=84, ... and a "last
        # page" link with the largest pid). The gap between consecutive page links is
        # the site's real per-page size, so pid_of_last_page + that gap is a close
        # upper-bound estimate of the true total.
        pid_values = sorted({int(value) for value in re.findall(r"[?&]pid=(\d+)", unescape(html_text))})
        if pid_values:
            steps = [b - a for a, b in zip(pid_values, pid_values[1:]) if b > a]
            step = min(steps) if steps else EXPLORE_LIMIT
            return pid_values[-1] + step
        return 0


class TagSuggestionWorker(QThread):
    suggestions_ready = Signal(str, list)
    failed = Signal(str, str)

    def __init__(self, site_key: str, prefix: str, request_key: str):
        super().__init__()
        self.site_key = site_key
        self.prefix = prefix.strip().lower()
        self.request_key = request_key

    def run(self):
        try:
            self.suggestions_ready.emit(self.request_key, self.fetch_suggestions())
        except Exception as exc:
            self.failed.emit(self.request_key, str(exc))

    def fetch_suggestions(self) -> list[tuple[str, int]]:
        if not self.prefix:
            return []
        if self.site_key == "e621":
            return self.fetch_e621_tags()
        return self.fetch_legacy_tags(LEGACY_BOORU_SITES.get(self.site_key, LEGACY_BOORU_SITES["gelbooru"])[1])

    def fetch_e621_tags(self) -> list[tuple[str, int]]:
        params = {
            "search[name_matches]": f"{self.prefix}*",
            "search[order]": "count",
            "limit": "24",
        }
        data = fetch_json(f"https://e621.net/tags.json?{urllib.parse.urlencode(params)}")
        suggestions = []
        for row in data if isinstance(data, list) else []:
            name = str(row.get("name") or "").strip()
            if name:
                suggestions.append((name, int(row.get("post_count") or 0)))
        return suggestions

    def fetch_legacy_tags(self, base_url: str) -> list[tuple[str, int]]:
        # Stop at the first fetcher that returns anything - each one is a full network
        # round trip, so chaining through all 4 on every keystroke (the old behavior)
        # is what made suggestions feel slow. The site's own autocomplete endpoint
        # (first in this list) is normally fast and good enough; the rest are only a
        # fallback for when it's unavailable.
        fetchers = (
            self.fetch_legacy_autocomplete,
            self.fetch_legacy_tag_api,
            self.fetch_legacy_tag_xml,
            self.fetch_legacy_tag_html,
        )
        if self.site_key == "rule34xxx":
            # Rule34.xxx's old page=autocomplete2 endpoint now 403s, and its DAPI (both
            # /index.php and the newer api.rule34.xxx) requires an API key the app
            # doesn't have. Its dedicated autocomplete API is still open though, and is
            # both faster and more reliable than any of the legacy fallbacks below.
            fetchers = (self.fetch_rule34_autocomplete, *fetchers)
        collected: dict[str, tuple[str, int]] = {}
        for fetcher in fetchers:
            try:
                suggestions = fetcher(base_url)
            except Exception:
                continue
            if suggestions:
                self.merge_suggestions(collected, suggestions)
                break
        return self.sorted_suggestions(collected.values())

    def fetch_rule34_autocomplete(self, base_url: str) -> list[tuple[str, int]]:
        url = f"https://api.rule34.xxx/autocomplete.php?q={urllib.parse.quote_plus(self.prefix)}"
        data = fetch_json(url, timeout=5)
        suggestions = []
        for row in data if isinstance(data, list) else []:
            if not isinstance(row, dict):
                continue
            value = str(row.get("value") or "").strip()
            if not value:
                continue
            count_match = re.search(r"\(([\d,]+)\)\s*$", str(row.get("label") or ""))
            count = int(count_match.group(1).replace(",", "")) if count_match else 0
            suggestions.append((value, count))
        return suggestions

    def merge_suggestions(self, collected: dict[str, tuple[str, int]], suggestions: list[tuple[str, int]]):
        for tag, count in suggestions:
            name = str(tag).strip()
            if not name:
                continue
            try:
                numeric_count = int(str(count or 0).replace(",", "") or 0)
            except (TypeError, ValueError):
                numeric_count = 0
            key = name.lower()
            existing = collected.get(key)
            if not existing or numeric_count > existing[1]:
                collected[key] = (name, numeric_count)

    def sorted_suggestions(self, suggestions) -> list[tuple[str, int]]:
        collected: dict[str, tuple[str, int]] = {}
        self.merge_suggestions(collected, list(suggestions))
        return sorted(collected.values(), key=lambda item: (-int(item[1] or 0), item[0].lower()))[:24]

    def fetch_legacy_autocomplete(self, base_url: str) -> list[tuple[str, int]]:
        params = {
            "page": "autocomplete2",
            "term": self.prefix,
            "type": "tag_query",
            "limit": "24",
        }
        url = f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}"
        text = fetch_url_bytes(url, timeout=5).decode("utf-8-sig", errors="replace").strip()
        data = None
        if text and text[0] in "[{":
            try:
                data = json.loads(text)
            except json.JSONDecodeError:
                data = None
        rows = data if isinstance(data, list) else data.get("results", []) if isinstance(data, dict) else []
        suggestions = []
        for row in rows:
            if isinstance(row, str):
                name = row
                count = 0
            elif isinstance(row, dict):
                name = str(row.get("value") or row.get("label") or row.get("name") or row.get("tag") or "").strip()
                count = int(row.get("post_count") or row.get("count") or row.get("posts") or 0)
            else:
                continue
            name = re.sub(r"\s+\d+$", "", name).strip()
            if name:
                suggestions.append((name, count))
        if suggestions:
            return suggestions
        return self.parse_legacy_tag_text(text)

    def parse_legacy_tag_text(self, text: str) -> list[tuple[str, int]]:
        text = unescape(text or "")
        suggestions = []
        seen = set()
        patterns = [
            r'"(?:value|label|name|tag)"\s*:\s*"([^"]+)"[^{}]*?"(?:post_count|count|posts)"\s*:\s*"?([\d,]+)"?',
            r'"(?:value|label|name|tag)"\s*:\s*"([^"]+)"[^{}]*?(?:"(?:post_count|count|posts)"\s*:\s*"?([\d,]+)"?)?',
            r'[?&]tags=([^"\'&<>]+)[^<>]*>.*?</a>\s*([\d,]+)',
            r'[?&]tags=([^"\'&<>]+)[^<>]*>(?:<[^>]+>)*([^<]*)',
            r'\b([a-z0-9_:\\.-]+)\b\s*(?:\(|\s)\s*([\d,]{2,})\)?',
            r'\b([a-z0-9_:\\.-]+)\b',
        ]
        for pattern in patterns:
            for match in re.findall(pattern, text, flags=re.IGNORECASE | re.DOTALL):
                if isinstance(match, tuple):
                    raw_name = match[0]
                    raw_count = match[1] if len(match) > 1 else "0"
                else:
                    raw_name = match
                    raw_count = "0"
                name = re.sub(r"<[^>]+>", "", urllib.parse.unquote_plus(str(raw_name))).strip()
                name = re.sub(r"\s+\d+$", "", name).strip()
                key = name.lower()
                if not name or not key.startswith(self.prefix) or key in seen:
                    continue
                seen.add(key)
                try:
                    count = int(str(raw_count or "0").replace(",", "").strip() or 0)
                except ValueError:
                    count = 0
                suggestions.append((name, count))
                if len(suggestions) >= 24:
                    return suggestions
        return suggestions

    def fetch_legacy_tag_api(self, base_url: str) -> list[tuple[str, int]]:
        params = {
            "page": "dapi",
            "s": "tag",
            "q": "index",
            "json": "1",
            "limit": "24",
            "orderby": "count",
            "name_pattern": f"{self.prefix}*",
        }
        data = fetch_json(f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}")
        rows = data.get("tag", []) if isinstance(data, dict) else data
        if isinstance(rows, dict):
            rows = [rows]
        suggestions = []
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            name = str(row.get("name") or "").strip()
            if name and name.lower().startswith(self.prefix):
                suggestions.append((name, int(row.get("count") or row.get("post_count") or 0)))
        return suggestions

    def fetch_legacy_tag_xml(self, base_url: str) -> list[tuple[str, int]]:
        params = {
            "page": "dapi",
            "s": "tag",
            "q": "index",
            "limit": "24",
            "orderby": "count",
            "name_pattern": f"{self.prefix}*",
        }
        url = f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}"
        root = fetch_xml_root(url, timeout=10)
        suggestions = []
        for node in root.findall(".//tag"):
            name = str(node.attrib.get("name") or node.findtext("name") or "").strip()
            if not name or not name.lower().startswith(self.prefix):
                continue
            raw_count = node.attrib.get("count") or node.attrib.get("post_count") or node.findtext("count") or 0
            try:
                count = int(raw_count or 0)
            except (TypeError, ValueError):
                count = 0
            suggestions.append((name, count))
        return suggestions

    def fetch_legacy_tag_html(self, base_url: str) -> list[tuple[str, int]]:
        html_text = ""
        for search_key in ("search", "tags", "name", "tag"):
            params = {
                "page": "tags",
                "s": "list",
                search_key: self.prefix,
            }
            url = f"{base_url}/index.php?{urllib.parse.urlencode(params)}"
            try:
                candidate = fetch_url_bytes(url, timeout=10).decode("utf-8", errors="replace")
                if self.prefix in candidate.lower():
                    html_text = candidate
                    break
                html_text = html_text or candidate
            except Exception:
                continue
        html_text = unescape(html_text)
        suggestions = []
        seen = set()
        patterns = [
            r'[?&]tags=([^"\'&<>]+)[^<>]*>[^<]*</a>\s*</td>\s*<td[^>]*>\s*([0-9,]+)',
            r'<a[^>]+href=["\'][^"\']*[?&]tags=([^"\'&]+)[^"\']*["\'][^>]*>(.*?)</a>[^<]*(?:</td>\s*<td[^>]*>)?\s*([0-9,]+)?',
        ]
        for pattern in patterns:
            for match in re.findall(pattern, html_text, flags=re.IGNORECASE | re.DOTALL):
                if isinstance(match, tuple):
                    raw_name = match[0]
                    raw_count = next((part for part in reversed(match[1:]) if re.fullmatch(r"\s*[0-9,]+\s*", str(part or ""))), "0")
                else:
                    raw_name = match
                    raw_count = "0"
                name = urllib.parse.unquote_plus(str(raw_name)).strip()
                if not name or not name.lower().startswith(self.prefix) or name.lower() in seen:
                    continue
                seen.add(name.lower())
                try:
                    count = int(str(raw_count or "0").replace(",", "").strip() or 0)
                except ValueError:
                    count = 0
                suggestions.append((name, count))
                if len(suggestions) >= 24:
                    return suggestions
        return suggestions


def build_tag_histogram(entries, allowed_types, site_filter: str, selected_tokens: frozenset,
                        should_stop=None, yield_every: int = 0) -> tuple[dict, list]:
    """Count how often each tag appears across `entries`, after filtering.

    Pure and self-contained so it can run on a worker thread: it lowers tags
    itself rather than going through the viewer's memo dict, which the UI thread
    owns. Returns the counts plus their sorted names, which is what lets a
    typed prefix be answered later with a pair of bisects instead of a rescan."""
    counter: "collections.Counter[str]" = collections.Counter()
    count_tags = counter.update
    site_scoped = site_filter != "all"
    chunk_started = time.monotonic()
    for position, entry in enumerate(entries, start=1):
        if yield_every and position % yield_every == 0:
            if should_stop is not None and should_stop():
                return {}, []
            # Hand the GIL over outright, for at least as long as this chunk
            # spent holding it.
            #
            # This is pure Python, so simply moving it to another thread does NOT
            # get it out of the UI thread's way - it holds the interpreter lock
            # and merely spreads the stall out. Measured: running it alongside a
            # repopulate took that repopulate from ~97ms to ~255ms, i.e. worse
            # overall than just doing this inline. Sleeping releases the lock
            # properly, and sleeping *in proportion to the work done* keeps the
            # ratio right however fast the machine is. Nothing is waiting on this
            # result, so taking a few times longer costs nothing.
            now = time.monotonic()
            time.sleep(min(0.05, (now - chunk_started) * TAG_HISTOGRAM_BACKOFF))
            chunk_started = time.monotonic()
        if site_scoped and str(entry.get("site") or "").lower().replace(" ", "") != site_filter:
            continue
        if entry.get("type") not in allowed_types:
            continue
        tags = {str(tag).lower() for tag in (entry.get("tags") or []) if str(tag).strip()}
        if selected_tokens and not selected_tokens.issubset(tags):
            continue
        # Counter.update() counts a whole iterable inside one C call, where the
        # equivalent Python loop pays interpreter overhead per tag - and this
        # library has ~1.9 million tag occurrences to get through.
        count_tags(tags)
    # The locked-in tokens are on every matching entry by definition, so they are
    # dropped once at the end rather than tested once per tag above.
    for token in selected_tokens:
        counter.pop(token, None)
    counts = dict(counter)
    return counts, sorted(counts)


def running_script_path() -> Path | None:
    """The .py file this process is actually running, or None if that is not a
    thing that can be reloaded (a frozen/packaged build)."""
    if getattr(sys, "frozen", False):
        return None
    try:
        path = Path(__file__).resolve()
    except (OSError, NameError):
        return None
    return path if path.suffix.lower() == ".py" and path.exists() else None


RELEASE_MANIFEST = "latest.json"
RELEASE_LAUNCHER = "Distant Viewer.exe"


def release_root(executable: str | None = None) -> Path | None:
    """For a published build - <release>/builds/<version>/Distant Viewer.exe -
    the <release> folder holding latest.json and the launcher. None when this
    isn't one (running from source, or a stray build somewhere else)."""
    if executable is None:
        if not getattr(sys, "frozen", False):
            return None
        executable = sys.executable
    try:
        build = Path(executable).resolve().parent
    except OSError:
        return None
    root = build.parent.parent
    if build.parent.name.lower() != "builds" or not (root / RELEASE_MANIFEST).exists():
        return None
    return root


def read_release_manifest(root: Path) -> dict | None:
    """latest.json, if it names a build that is really there."""
    try:
        data = json.loads((root / RELEASE_MANIFEST).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    if not isinstance(data, dict) or not data.get("version") or not data.get("build"):
        return None
    exe = root / str(data["build"]) / "Distant Viewer.exe"
    if not exe.exists():
        return None
    return {**data, "exe": str(exe)}


def notes_in_source(source: str) -> str:
    match = re.search(r'^APP_UPDATE_NOTES\s*=\s*"""\\?\n?(.*?)"""', source, re.MULTILINE | re.DOTALL)
    return match.group(1).strip() if match else ""


def installed_release_launcher(script: Path | None = None) -> Path | None:
    """The published app's launcher, when this is the development source file
    sitting next to a release (<project>/outputs/DistantViewer.py with
    <project>/release/). The source file is what gets edited while the app is
    being worked on; the user runs the published exe, so starting the source -
    an old shortcut, a taskbar pin - hands over to that instead.
    DISTANT_VIEWER_DEV=1 runs the source itself."""
    if getattr(sys, "frozen", False) or os.environ.get("DISTANT_VIEWER_DEV"):
        return None
    script = script or running_script_path()
    if script is None:
        return None
    project = script.parent.parent if script.parent.name.lower() == "outputs" else script.parent
    release = project / "release"
    launcher = release / RELEASE_LAUNCHER
    if launcher.exists() and (release / RELEASE_MANIFEST).exists():
        return launcher
    return None


_SINGLE_INSTANCE_HANDLES: list = []


SINGLE_INSTANCE_NAME = "Local\\DistantViewer.SingleInstance"


def acquire_single_instance(wait_seconds: float = 0.0, name: str | None = None) -> bool:
    """One Distant Viewer at a time - two copies writing the same library
    metadata would undo each other's changes. A copy started to replace one
    that is restarting for an update waits for it to finish saving."""
    if os.name != "nt":
        return True
    try:
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateMutexW.restype = wintypes.HANDLE
        kernel32.CreateMutexW.argtypes = [wintypes.LPVOID, wintypes.BOOL, wintypes.LPCWSTR]
        kernel32.WaitForSingleObject.restype = wintypes.DWORD
        kernel32.WaitForSingleObject.argtypes = [wintypes.HANDLE, wintypes.DWORD]
        handle = kernel32.CreateMutexW(None, False, name or SINGLE_INSTANCE_NAME)
        if not handle:
            return True
        result = kernel32.WaitForSingleObject(handle, int(max(0.0, wait_seconds) * 1000))
    except Exception:
        return True
    if result in (0x0, 0x80):   # WAIT_OBJECT_0, WAIT_ABANDONED (previous copy exited)
        _SINGLE_INSTANCE_HANDLES.append(handle)
        return True
    return False


def version_in_source(source: str) -> str:
    match = re.search(r"^APP_VERSION\s*=\s*[\"']([^\"']+)[\"']", source, re.MULTILINE)
    return match.group(1) if match else ""


class UpdateCheckWorker(QThread):
    """Reads the app's own source file and reports the version it declares.

    Off the UI thread because it reads ~800KB and compiles it. The compile is the
    point: the file is being edited live, so a read can easily land mid-write and
    see a truncated or syntactically broken file. Compiling is the cheapest
    honest way to ask "is this a complete script?" before telling the user an
    update is ready."""

    checked = Signal(str, str, bool)

    def __init__(self, path: Path):
        super().__init__()
        self.path = path

    def run(self):
        try:
            source = self.path.read_text(encoding="utf-8")
            compile(source, str(self.path), "exec")
        except (OSError, UnicodeDecodeError, SyntaxError, ValueError):
            self.checked.emit("", "", False)
            return
        self.checked.emit(version_in_source(source), notes_in_source(source), True)


class TagHistogramWorker(QThread):
    """Builds the search-suggestion tag histogram off the UI thread.

    Counting every tag on every file is ~0.9s on this library - small enough to
    be tempting to leave inline, big enough to be a visible freeze every time
    you finish typing a tag. The entry list is snapshotted by the caller before
    this starts, so the UI thread is free to keep editing the real one."""

    ready = Signal(object, object, object)

    def __init__(self, key, entries: list, allowed_types: set, site_filter: str, selected_tokens: frozenset):
        super().__init__()
        self.key = key
        self.entries = entries
        self.allowed_types = set(allowed_types)
        self.site_filter = site_filter
        self.selected_tokens = selected_tokens

    def run(self):
        # Below-normal priority as well: when the GIL is handed over, the OS
        # prefers waking the higher-priority thread, which is the UI.
        lower_current_thread_priority()
        try:
            counts, names = build_tag_histogram(
                self.entries, self.allowed_types, self.site_filter, self.selected_tokens,
                should_stop=self.isInterruptionRequested,
                yield_every=TAG_HISTOGRAM_YIELD_EVERY,
            )
        except Exception as exc:
            write_app_log(f"tag histogram failed error={exc}")
            return
        if self.isInterruptionRequested():
            return
        self.ready.emit(self.key, counts, names)


class TagCountWorker(QThread):
    counts_ready = Signal(str, dict)
    failed = Signal(str, str)

    def __init__(self, site_key: str, tags: list[str], request_key: str):
        super().__init__()
        self.site_key = site_key
        self.tags = unique_tags(tags)[:220]
        self.request_key = request_key

    def run(self):
        try:
            if self.site_key == "e621":
                counts = self.fetch_e621_counts()
            else:
                counts = self.fetch_legacy_counts(LEGACY_BOORU_SITES.get(self.site_key, LEGACY_BOORU_SITES["gelbooru"])[1])
            if not self.isInterruptionRequested():
                self.counts_ready.emit(self.request_key, counts)
        except Exception as exc:
            if not self.isInterruptionRequested():
                self.failed.emit(self.request_key, str(exc))

    def row_name_count(self, row) -> tuple[str, int] | None:
        if not isinstance(row, dict):
            return None
        attrs = row.get("@attributes") or row.get("attributes")
        if isinstance(attrs, dict):
            merged = dict(attrs)
            merged.update({key: value for key, value in row.items() if key not in {"@attributes", "attributes"}})
            row = merged
        name = str(row.get("name") or row.get("tag") or row.get("value") or row.get("label") or "").strip()
        if not name:
            return None
        try:
            count = int(str(row.get("count") or row.get("post_count") or row.get("posts") or 0).replace(",", "") or 0)
        except (TypeError, ValueError):
            count = 0
        return name, count

    def tag_rows(self, data) -> list[dict]:
        rows = data.get("tag", data.get("tags", [])) if isinstance(data, dict) else data
        if isinstance(rows, dict):
            rows = [rows]
        return rows if isinstance(rows, list) else []

    def add_exact_rows(self, counts: dict[str, int], rows, wanted: set[str]):
        for row in rows or []:
            parsed = self.row_name_count(row)
            if not parsed:
                continue
            name, count = parsed
            key = name.lower()
            if key in wanted and count:
                counts[key] = max(counts.get(key, 0), count)

    def fetch_e621_counts(self) -> dict[str, int]:
        wanted = {tag.lower() for tag in self.tags}
        counts: dict[str, int] = {}

        def fetch_one(tag: str):
            params = urllib.parse.urlencode({"search[name]": tag, "limit": "1"})
            data = fetch_json(f"https://e621.net/tags.json?{params}", timeout=8)
            for row in data if isinstance(data, list) else []:
                parsed = self.row_name_count(row)
                if parsed and parsed[0].lower() == tag.lower():
                    return tag.lower(), parsed[1]
            return tag.lower(), 0

        with concurrent.futures.ThreadPoolExecutor(max_workers=6) as executor:
            futures = [executor.submit(fetch_one, tag) for tag in self.tags]
            for future in concurrent.futures.as_completed(futures):
                if self.isInterruptionRequested():
                    executor.shutdown(wait=False, cancel_futures=True)
                    return counts
                try:
                    key, count = future.result()
                    if key in wanted and count:
                        counts[key] = count
                except Exception:
                    pass
        return counts

    def fetch_legacy_counts(self, base_url: str) -> dict[str, int]:
        wanted = {tag.lower() for tag in self.tags}
        counts: dict[str, int] = {}
        for chunk_start in range(0, len(self.tags), 80):
            chunk = self.tags[chunk_start:chunk_start + 80]
            self.fetch_legacy_batch_counts(base_url, chunk, counts, wanted)
            if self.isInterruptionRequested():
                return counts
        missing = [tag for tag in self.tags if tag.lower() not in counts]
        if not missing:
            return counts

        def fetch_one(tag: str):
            return tag.lower(), self.fetch_legacy_one_count(base_url, tag)

        with concurrent.futures.ThreadPoolExecutor(max_workers=6) as executor:
            futures = [executor.submit(fetch_one, tag) for tag in missing[:160]]
            for future in concurrent.futures.as_completed(futures):
                if self.isInterruptionRequested():
                    executor.shutdown(wait=False, cancel_futures=True)
                    return counts
                try:
                    key, count = future.result()
                    if key in wanted and count:
                        counts[key] = count
                except Exception:
                    pass
        return counts

    def fetch_legacy_batch_counts(self, base_url: str, tags: list[str], counts: dict[str, int], wanted: set[str]):
        if not tags:
            return
        params = {
            "page": "dapi",
            "s": "tag",
            "q": "index",
            "json": "1",
            "limit": str(max(len(tags), 1)),
            "names": " ".join(tags),
        }
        try:
            data = fetch_json(f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}", timeout=10)
            self.add_exact_rows(counts, self.tag_rows(data), wanted)
        except Exception:
            pass
        if all(tag.lower() in counts for tag in tags):
            return
        xml_params = dict(params)
        xml_params.pop("json", None)
        try:
            root = fetch_xml_root(f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, xml_params))}", timeout=10)
            rows = [dict(node.attrib) for node in root.findall(".//tag")]
            self.add_exact_rows(counts, rows, wanted)
        except Exception:
            pass

    def fetch_legacy_one_count(self, base_url: str, tag: str) -> int:
        for key_name in ("name", "name_pattern"):
            params = {
                "page": "dapi",
                "s": "tag",
                "q": "index",
                "json": "1",
                "limit": "8",
                key_name: tag if key_name == "name" else f"{tag}*",
            }
            try:
                data = fetch_json(f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}", timeout=8)
                for row in self.tag_rows(data):
                    parsed = self.row_name_count(row)
                    if parsed and parsed[0].lower() == tag.lower():
                        return parsed[1]
            except Exception:
                pass
            xml_params = dict(params)
            xml_params.pop("json", None)
            try:
                root = fetch_xml_root(f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, xml_params))}", timeout=8)
                for node in root.findall(".//tag"):
                    name = str(node.attrib.get("name") or node.findtext("name") or "").strip()
                    if name.lower() == tag.lower():
                        raw_count = node.attrib.get("count") or node.attrib.get("post_count") or node.findtext("count") or 0
                        return int(str(raw_count or "0").replace(",", "") or 0)
            except Exception:
                pass
        try:
            site_key = next((key for key, value in LEGACY_BOORU_SITES.items() if value[1] in base_url), "gelbooru")
            worker = TagSuggestionWorker(site_key, tag, "")
            for name, count in worker.fetch_legacy_tag_html(base_url):
                if name.lower() == tag.lower():
                    return int(count or 0)
        except Exception:
            pass
        return 0


class RemoteMediaWorker(QThread):
    progress = Signal(int, str)
    ready = Signal(dict)
    failed = Signal(str)

    def __init__(self, entry: dict):
        super().__init__()
        self.entry = dict(entry)

    def run(self):
        try:
            entry = dict(self.entry)
            if not entry.get("remote"):
                path = Path(entry.get("path", ""))
                if not path.exists():
                    raise RuntimeError("That local file no longer exists.")
                entry["local_path"] = str(path)
                entry["media_url"] = str(path)
                entry["type"] = entry.get("type") or media_type(path)
                if entry["type"] != "video":
                    try:
                        with Image.open(path) as image:
                            entry["width"], entry["height"] = image.size
                    except Exception:
                        pass
                self.progress.emit(100, "Loaded")
                self.ready.emit(entry)
                return
            media_url = entry.get("media_url") or entry.get("path")
            # A working DAPI search (Gelbooru always, Rule34.xxx now that a real API
            # key is configured) already returns a real, full-resolution media_url -
            # no further resolution needed there. But its tag-category DAPI lookup is
            # only reliable for sites where entry_skips_dapi_tag_lookup() is False
            # (Rule34.xxx's ignores its own names= filter and always returns garbage -
            # see distant-viewer-rule34-api-migration memory). For those sites, still
            # do the full resolve so tag_categories comes from the (accurate)
            # HTML-scraped path instead of silently staying empty/uncolored.
            needs_full_resolve = bool(
                entry.get("needs_resolve")
                or not media_url
                or looks_like_preview_media_url(media_url)
                or (entry_skips_dapi_tag_lookup(entry) and not entry.get("tag_categories"))
            )
            if needs_full_resolve:
                self.resolve_full_media(entry)
            else:
                entry["candidate_media_urls"] = [media_url]
                if entry.get("tags") and not entry.get("tag_categories"):
                    categories = self.fetch_missing_tag_categories(entry.get("source_url") or "", entry.get("tags", []), {})
                    if categories:
                        entry["tag_categories"] = categories

            media_url = entry.get("media_url") or entry.get("path")
            if not media_url:
                raise RuntimeError("No media URL found.")

            video_candidate = first_video_candidate(entry)
            if entry.get("type") == "video" and media_type_from_url(media_url) != "video" and video_candidate:
                media_url = video_candidate
                entry["media_url"] = media_url
                entry["path"] = media_url
            resolved_kind = media_type_from_url(media_url)
            if resolved_kind in {"gif", "video"} or entry.get("type") not in {"image", "gif", "video"}:
                entry["type"] = resolved_kind

            if entry.get("type") == "video":
                candidates = video_candidates_for_entry(entry, media_url)
                if not candidates:
                    raise RuntimeError("No playable video source was found for this result.")
                media_url = candidates[0]
                entry.pop("local_path", None)
                entry["stream_url"] = media_url
                entry["media_url"] = media_url
                entry["path"] = media_url
                self.progress.emit(100, "Starting video stream")
                write_app_log(f"explore video stream ready post={entry.get('post_id')} candidates={len(candidates)}")
                self.ready.emit(entry)
                return

            media_url, target, width, height = self.cache_best_media(entry)
            if self.isInterruptionRequested():
                return
            entry["media_url"] = media_url
            entry["path"] = media_url
            entry["type"] = media_type_from_url(media_url)
            entry["preview_fallback"] = bool(entry.get("source_url") and looks_like_preview_media_url(media_url))
            entry["selected_media_url"] = media_url
            entry["local_path"] = str(target)
            entry["width"] = width
            entry["height"] = height
            self.ready.emit(entry)
        except Exception as exc:
            write_app_log(
                f"remote media failed site={self.entry.get('site')} post={self.entry.get('post_id')} "
                f"type={self.entry.get('type')} error={type(exc).__name__}: {exc}"
            )
            self.failed.emit(str(exc))

    def cache_best_media(self, entry: dict) -> tuple[str, Path, int, int]:
        media_url = entry.get("media_url") or entry.get("path")
        candidates = image_candidates_for_entry(entry, media_url)
        candidates = sorted(candidates, key=media_url_score, reverse=True)
        seen = set()
        candidates = [url for url in candidates if url and not (url in seen or seen.add(url))]
        candidates = candidates[:10]
        fallback = None
        referer = entry.get("source_url")
        last_error = ""
        for url in candidates:
            target = explore_media_path(url)
            try:
                if target.exists():
                    data = target.read_bytes()
                    touch_cache_file(target)
                    self.progress.emit(100, "Cached")
                else:
                    data = self.fetch_media_bytes(url, target, referer)
                try:
                    with Image.open(io.BytesIO(data)) as image:
                        width, height = image.size
                except Exception:
                    try:
                        if target.exists():
                            target.unlink()
                    except OSError:
                        pass
                    data = self.fetch_media_bytes(url, target, referer)
                    with Image.open(io.BytesIO(data)) as image:
                        width, height = image.size
                area = width * height
                score = area + media_url_score(url) * 100000
                if looks_like_preview_media_url(url):
                    score -= 20000000
                result = (score, url, target, width, height)
                if not looks_like_preview_media_url(url):
                    return result[1], result[2], result[3], result[4]
                if fallback is None or score > fallback[0]:
                    fallback = result
            except Exception as exc:
                last_error = f"{url}: {exc}"
                continue
        if fallback:
            return fallback[1], fallback[2], fallback[3], fallback[4]
        thumb_path = Path(entry.get("thumb", ""))
        if thumb_path.exists():
            try:
                with Image.open(thumb_path) as image:
                    width, height = image.size
                thumb_url = entry.get("thumb_url") or entry.get("media_url") or entry.get("path") or str(thumb_path)
                return thumb_url, thumb_path, width, height
            except Exception:
                pass
        raise RuntimeError(f"Could not download the image from any media URL the post page exposed. {last_error}".strip())

    def cache_best_media_to_disk(self, entry: dict) -> tuple[str, Path, int, int]:
        media_url = entry.get("media_url") or entry.get("path")
        candidates = sorted(image_candidates_for_entry(entry, media_url), key=media_url_score, reverse=True)[:10]
        fallback = None
        last_error = ""
        for url in candidates:
            target = explore_media_path(url)
            try:
                if target.exists():
                    local_path = target
                    touch_cache_file(target)
                    self.progress.emit(100, "Using cached full media")
                else:
                    local_path = download_url_to_path(
                        url,
                        target,
                        entry.get("source_url"),
                        timeout=120,
                        progress=self.progress.emit,
                        progress_label="Downloading image",
                    )
                with Image.open(local_path) as image:
                    width, height = image.size
                result = (url, local_path, width, height)
                if not looks_like_preview_media_url(url):
                    return result
                if fallback is None:
                    fallback = result
            except Exception as exc:
                last_error = f"{url}: {exc}"
                try:
                    if target.exists():
                        target.unlink()
                except OSError:
                    pass
        if fallback:
            return fallback
        raise RuntimeError(f"Could not download the image from any media URL the post page exposed. {last_error}".strip())

    def fetch_media_bytes(self, url: str, target: Path, referer: str | None) -> bytes:
        parsed = urllib.parse.urlparse(url)
        referer = referer or f"{parsed.scheme}://{parsed.netloc}/"
        request = urllib.request.Request(
            url,
            headers={
                "User-Agent": EXPLORE_USER_AGENT,
                "Accept": "image/avif,image/webp,image/apng,image/*,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
                "Referer": referer,
            },
        )
        target.parent.mkdir(parents=True, exist_ok=True)
        chunks = []
        downloaded = 0
        with open_network_request(request, timeout=35) as response:
            total = int(response.headers.get("Content-Length") or 0)
            last_percent = -1
            while True:
                chunk = response.read(1024 * 128)
                if not chunk:
                    break
                chunks.append(chunk)
                downloaded += len(chunk)
                if total:
                    percent = min(99, int(downloaded * 100 / total))
                    if percent != last_percent:
                        last_percent = percent
                        self.progress.emit(percent, "Downloading")
        data = b"".join(chunks)
        target.write_bytes(data)
        self.progress.emit(100, "Downloaded")
        return data

    def resolve_full_media(self, entry: dict):
        source_url = unescape(entry.get("source_url") or "")
        if not source_url:
            return
        current_url = entry.get("media_url") or entry.get("path") or ""
        resolved_url = ""
        candidate_urls = [current_url] if current_url else []
        categories = dict(entry.get("tag_categories") or {})

        try:
            if "e621.net/posts/" in source_url:
                post_id = source_url.rstrip("/").split("/")[-1]
                data = fetch_json(f"https://e621.net/posts/{post_id}.json")
                post = data.get("post", {}) if isinstance(data, dict) else {}
                file_info = post.get("file") or {}
                resolved_url = url_with_scheme(file_info.get("url"))
                if resolved_url:
                    candidate_urls.append(resolved_url)
                if file_info.get("size"):
                    entry["size"] = int(file_info.get("size") or 0)
                tag_data = post.get("tags") or {}
                if isinstance(tag_data, dict):
                    tags = []
                    for category, values in tag_data.items():
                        if isinstance(values, list):
                            for value in values:
                                tag = str(value)
                                tags.append(tag)
                                categories[tag.lower()] = normalized_tag_category(str(category))
                    if tags:
                        entry["tags"] = unique_tags(tags)
            elif "page=post" in source_url and "id=" in source_url:
                parsed = urllib.parse.urlparse(source_url)
                query = urllib.parse.parse_qs(parsed.query)
                post_id = (query.get("id") or query.get("amp;id") or [""])[0]
                base_url = f"{parsed.scheme}://{parsed.netloc}"
                if post_id:
                    api_query = urllib.parse.urlencode(
                        with_gelbooru_auth(
                            base_url,
                            {"page": "dapi", "s": "post", "q": "index", "json": "1", "id": post_id},
                        )
                    )
                    try:
                        data = fetch_json(f"{base_url}/index.php?{api_query}")
                        rows = post_rows(data)
                        post = rows[0] if rows else {}
                        if isinstance(post, dict):
                            legacy_image = str(post.get("image") or "").strip()
                            legacy_directory = str(post.get("directory") or "").strip("/ ")
                            constructed_file = (
                                f"/images/{legacy_directory}/{legacy_image}"
                                if legacy_image and legacy_directory else ""
                            )
                            resolved_url = absolute_url(
                                base_url, post.get("file_url") or constructed_file or post.get("source")
                            )
                            if resolved_url:
                                candidate_urls.append(resolved_url)
                                candidate_urls.extend(original_url_guesses(resolved_url))
                            for extra_url in [post.get("sample_url"), post.get("preview_url")]:
                                full_extra = absolute_url(base_url, extra_url)
                                if full_extra:
                                    candidate_urls.append(full_extra)
                                    candidate_urls.extend(original_url_guesses(full_extra))
                            if post.get("file_size"):
                                entry["size"] = int(post.get("file_size") or 0)
                            tags = unique_tags(str(post.get("tags", "")).split())
                            if tags:
                                entry["tags"] = tags
                    except Exception:
                        pass
                    if not resolved_url:
                        try:
                            xml_query = urllib.parse.urlencode(
                                with_gelbooru_auth(
                                    base_url,
                                    {"page": "dapi", "s": "post", "q": "index", "id": post_id},
                                )
                            )
                            root = fetch_xml_root(f"{base_url}/index.php?{xml_query}")
                            post_node = root if str(root.tag).lower().endswith("post") else root.find(".//post")
                            if post_node is not None:
                                legacy_image = str(post_node.attrib.get("image") or "").strip()
                                legacy_directory = str(post_node.attrib.get("directory") or "").strip("/ ")
                                constructed_file = (
                                    f"/images/{legacy_directory}/{legacy_image}"
                                    if legacy_image and legacy_directory else ""
                                )
                                resolved_url = absolute_url(
                                    base_url,
                                    post_node.attrib.get("file_url") or constructed_file or post_node.attrib.get("source"),
                                )
                                if resolved_url:
                                    candidate_urls.append(resolved_url)
                                    candidate_urls.extend(original_url_guesses(resolved_url))
                                for extra_url in [post_node.attrib.get("sample_url"), post_node.attrib.get("preview_url")]:
                                    full_extra = absolute_url(base_url, extra_url)
                                    if full_extra:
                                        candidate_urls.append(full_extra)
                                        candidate_urls.extend(original_url_guesses(full_extra))
                                if post_node.attrib.get("file_size"):
                                    entry["size"] = int(post_node.attrib.get("file_size") or 0)
                                tags = unique_tags(str(post_node.attrib.get("tags", "")).split())
                                if tags:
                                    entry["tags"] = tags
                        except Exception:
                            pass
        except Exception:
            resolved_url = ""

        try:
            # This one fetch is what supplies both the real media candidates *and* the
            # tag categories (extract_tag_categories_from_html below) - a single
            # failure here (timeout/reset are common on Rule34.xxx/Realbooru under
            # load, especially right after a search just fired off a burst of
            # thumbnail requests to the same site) used to silently leave both blank:
            # a post that "resolved" with almost no real candidates and every tag
            # showing as uncategorized/white, even though a retry moments later would
            # have succeeded fine. Retry a few times with backoff instead of once.
            html_bytes = None
            last_fetch_error = None
            for attempt in range(3):
                try:
                    html_bytes = fetch_url_bytes(source_url, timeout=16, referer=source_url)
                    break
                except Exception as exc:
                    last_fetch_error = exc
                    if attempt < 2:
                        time.sleep(0.6 * (attempt + 1))
            if html_bytes is None:
                raise last_fetch_error or RuntimeError("Could not fetch the post page")
            html_text = html_bytes.decode("utf-8", errors="replace")
            declared_urls = declared_media_urls_from_html(source_url, html_text)
            html_urls = media_urls_from_html(source_url, html_text)
            # A post's own page can legitimately reference other domains (upscaler
            # proxies, reverse-image-search links, a "source:" citation pointing at
            # where the art was *also* posted) - those are usually low-scored anyway,
            # but never let one outrank/replace the real media just because it happens
            # to be hash-named too. Only URLs on the site actually being resolved are
            # eligible to become the resolved media.
            declared_urls = [url for url in declared_urls if same_site_family(url, source_url)]
            html_urls = [url for url in html_urls if same_site_family(url, source_url)]
            exact_video_urls = [url for url in declared_urls if media_type_from_url(url) == "video"]
            candidate_urls = exact_video_urls + declared_urls + candidate_urls
            candidate_urls.extend(html_urls[:24])
            if entry.get("type") == "video" and exact_video_urls:
                resolved_url = exact_video_urls[0]
            elif not resolved_url:
                html_url = declared_urls[0] if declared_urls else (html_urls[0] if html_urls else "")
                resolved_url = better_media_url(current_url, html_url)
            scraped_categories = extract_tag_categories_from_html(html_text)
            categories.update(scraped_categories)
            # The tag links scraped above are keyed by the real, canonical tag names
            # for this post, so they are the authoritative source for the tags
            # themselves and not just their colours - see merge_scraped_tags for what
            # the alternative (the search listing's space-separated display text) does
            # to multi-word tags. This also covers the case the previous version of
            # this block was written for: the DAPI post-by-id lookup above silently
            # no-ops on failure (rate limits/resets are routine here), which used to
            # leave entry["tags"] stuck at whatever sparse list the listing thumbnail
            # carried.
            if scraped_categories:
                entry["tags"] = merge_scraped_tags(entry.get("tags", []), scraped_categories.keys())
        except Exception:
            pass

        if not entry_skips_dapi_tag_lookup(entry):
            verified_categories = self.fetch_missing_tag_categories(source_url, entry.get("tags", []), {})
            categories.update(verified_categories)

        if resolved_url and looks_like_thumbnail_url(resolved_url):
            resolved_url = ""
        media_url = resolved_url if resolved_url else current_url
        if looks_like_thumbnail_url(media_url) and resolved_url:
            media_url = resolved_url
        if media_url:
            entry["media_url"] = media_url
            entry["path"] = media_url
            entry["type"] = media_type_from_url(media_url)
            entry["name"] = f"{entry.get('site', 'explore').lower()}_{hashlib.sha1(media_url.encode('utf-8', errors='ignore')).hexdigest()[:10]}{url_suffix(media_url)}"
        if current_url:
            candidate_urls.extend(original_url_guesses(current_url))
        thumb_url = entry.get("thumb_url")
        if thumb_url:
            candidate_urls.extend(original_url_guesses(thumb_url))
        candidate_urls.extend([media_url, current_url, thumb_url])
        seen = set()
        ordered_candidates = [resolved_url, media_url]
        non_preview_candidates = [
            url for url in candidate_urls
            if url and not looks_like_preview_media_url(url)
        ]
        preview_candidates = [
            url for url in candidate_urls
            if url and looks_like_preview_media_url(url)
        ]
        ordered_candidates.extend(sorted(non_preview_candidates, key=media_url_score, reverse=True))
        ordered_candidates.extend(sorted(preview_candidates, key=media_url_score, reverse=True))
        candidate_limit = 16 if entry_is_realbooru(entry) else 48
        entry["candidate_media_urls"] = [
            url for url in ordered_candidates
            if not (url in seen or seen.add(url))
        ][:candidate_limit]
        if entry.get("type") == "video":
            write_app_log(
                f"resolved video post={entry.get('post_id')} exact={len(locals().get('exact_video_urls', []))} "
                f"candidates={len(entry['candidate_media_urls'])} selected={entry.get('media_url', '')}"
            )
        entry["tag_categories"] = categories
        # Rule34.xxx/Realbooru rate-limit hard enough that even 3 retries sometimes
        # aren't enough to get through - if this is one of those sites, categories
        # came back empty, and there are real tags that should have had some, don't
        # mark this "resolved" for good. Leaving needs_resolve set means the next
        # time this post is opened, it gets a genuine retry instead of being stuck
        # showing uncategorized/white tags for the rest of the session.
        if entry_skips_dapi_tag_lookup(entry) and entry.get("tags") and not categories:
            entry["needs_resolve"] = True
        else:
            entry["needs_resolve"] = False

    def fetch_missing_tag_categories(self, source_url: str, tags: list, existing: dict) -> dict[str, str]:
        found = {}
        for tag in tags:
            key = str(tag).lower()
            if key not in existing and key in TAG_CATEGORY_CACHE:
                found[key] = TAG_CATEGORY_CACHE[key]
        missing = [str(tag) for tag in tags if str(tag).lower() not in existing and str(tag).lower() not in found]
        if not missing or "page=post" not in source_url:
            return found
        parsed = urllib.parse.urlparse(source_url)
        base_url = f"{parsed.scheme}://{parsed.netloc}"
        for offset in range(0, len(missing), 80):
            batch = missing[offset:offset + 80]
            batch_keys = {tag.lower() for tag in batch}
            names = " ".join(batch)
            batch_found = set()
            for params in [
                {"page": "dapi", "s": "tag", "q": "index", "json": "1", "names": names},
                {"page": "dapi", "s": "tag", "q": "index", "json": "1", "name": names},
            ]:
                try:
                    data = fetch_json(f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}")
                    rows = data.get("tag", []) if isinstance(data, dict) else data
                    if isinstance(rows, dict):
                        rows = [rows]
                    for row in rows or []:
                        if not isinstance(row, dict):
                            continue
                        name = str(row.get("name") or "").lower()
                        # The site's names= filter isn't reliably scoping results (seen
                        # returning tags never asked for at all) - never trust a
                        # response row unless it's actually one of the tags in this
                        # batch, or an unrelated tag's category could get attached to
                        # this post/silently bloat its stored tag_categories.
                        if name and name in batch_keys:
                            raw_category = row["type"] if "type" in row else row.get("category", "")
                            found[name] = normalized_tag_category(str(raw_category))
                            batch_found.add(name)
                    if batch_found:
                        break
                except Exception:
                    pass
            unresolved = [tag for tag in batch if tag.lower() not in batch_found]
            if not unresolved:
                continue
            try:
                unresolved_keys = {tag.lower() for tag in unresolved}
                params = {"page": "dapi", "s": "tag", "q": "index", "names": " ".join(unresolved)}
                root = fetch_xml_root(f"{base_url}/index.php?{urllib.parse.urlencode(with_gelbooru_auth(base_url, params))}")
                for node in root.findall(".//tag"):
                    name = str(node.attrib.get("name") or "").lower()
                    if name and name in unresolved_keys:
                        raw_category = node.attrib["type"] if "type" in node.attrib else node.attrib.get("category", "")
                        found[name] = normalized_tag_category(str(raw_category))
            except Exception:
                pass
        if found:
            TAG_CATEGORY_CACHE.update(found)
        return found


class ExplorePrefetchWorker(QThread):
    cached = Signal(str)

    def __init__(self, entries: list[dict]):
        super().__init__()
        self.entries = [dict(entry) for entry in entries if entry.get("remote")]

    def run(self):
        for entry in self.entries:
            if self.isInterruptionRequested():
                return
            try:
                resolver = RemoteMediaWorker(entry)
                media_url = entry.get("media_url") or entry.get("path")
                if entry.get("needs_resolve") or not media_url or looks_like_preview_media_url(media_url):
                    resolver.resolve_full_media(entry)
                media_url = entry.get("media_url") or entry.get("path")
                if not media_url:
                    continue
                if media_type_from_url(media_url) == "video":
                    continue
                _media_url, target, _width, _height = resolver.cache_best_media(entry)
                if self.isInterruptionRequested():
                    return
                self.cached.emit(str(target))
            except Exception:
                continue


class SaveExploreWorker(QThread):
    progress = Signal(int, str)
    saved = Signal(dict)
    failed = Signal(str)

    def __init__(self, entry: dict, destination: Path):
        super().__init__()
        self.entry = dict(entry)
        self.destination = destination

    def run(self):
        try:
            entry = dict(self.entry)
            resolver = RemoteMediaWorker(entry)
            media_url = entry.get("media_url") or entry.get("path")
            # See the matching comment in RemoteMediaWorker.run() - a working DAPI
            # search already supplies a real media_url, but for sites whose DAPI tag
            # lookup is broken (Rule34.xxx), that means tag_categories would otherwise
            # get permanently saved empty/uncolored unless resolve_full_media runs to
            # pull them from the HTML-scraped path instead.
            if (
                entry.get("needs_resolve")
                or not media_url
                or looks_like_preview_media_url(media_url)
                or (entry_skips_dapi_tag_lookup(entry) and not entry.get("tag_categories"))
            ):
                resolver.resolve_full_media(entry)
            media_url = entry.get("media_url") or entry.get("path")
            if not media_url:
                raise RuntimeError("No full media URL was found for this result.")

            video_candidate = first_video_candidate(entry)
            if entry.get("type") == "video" and media_type_from_url(media_url) != "video" and video_candidate:
                media_url = video_candidate
                entry["media_url"] = media_url
                entry["path"] = media_url
            resolved_kind = media_type_from_url(media_url)
            kind = resolved_kind if resolved_kind in {"gif", "video"} or entry.get("type") not in {"image", "gif", "video"} else entry.get("type")
            entry["type"] = kind
            cached_raw = entry.get("local_path")
            cached_local = Path(cached_raw) if cached_raw else None
            if cached_local and cached_local.is_file():
                local_path = cached_local
                self.progress.emit(100, "Using cached full media")
                if kind not in {"image", "gif", "video"}:
                    kind = media_type(cached_local)
            elif kind == "video":
                if not video_candidates_for_entry(entry, media_url):
                    raise RuntimeError("No downloadable video source was found for this result.")
                self.progress.emit(0, "Downloading video")
                media_url, local_path = cached_video_path_for_entry(entry, media_url, entry.get("source_url"), self.progress.emit)
            else:
                resolver.progress.connect(self.progress.emit)
                media_url, local_path, width, height = resolver.cache_best_media_to_disk(entry)
                entry["width"] = width
                entry["height"] = height
                kind = media_type_from_url(media_url)

            self.destination.mkdir(parents=True, exist_ok=True)
            target = self.destination / remote_save_name(entry, media_url)
            if not target.exists():
                self.progress.emit(100, "Copying")
                shutil.copy2(str(local_path), str(target))

            tags = unique_tags(entry.get("tags", []))
            categories = {
                str(key).lower(): str(value)
                for key, value in (entry.get("tag_categories") or {}).items()
                if str(key).strip()
            }
            if tags and not categories and not entry_skips_dapi_tag_lookup(entry):
                categories = resolver.fetch_missing_tag_categories(entry.get("source_url") or "", tags, {})
            # Metadata is applied to the main thread's cached dict and flushed to disk
            # there (see on_explore_saved/mark_saved_metadata_dirty), not written here.
            # This used to do its own load_saved_metadata()+write_saved_metadata() per
            # file - a full read *and* full write of the whole folder's metadata JSON
            # (tens of MB with a large library) on every single save. For a 300+ file
            # batch that's hundreds of full-file read/write cycles fighting over
            # SAVED_METADATA_LOCK and burning CPU on JSON parsing under the GIL right
            # alongside the UI thread - the real cause of "laggy during big downloads".
            self.saved.emit(
                {
                    "path": str(target),
                    "name": target.name,
                    "tags": sorted(set(tags)),
                    "tag_categories": categories,
                    "site": entry.get("site", "Explore"),
                    "source_url": entry.get("source_url", ""),
                    "media_url": media_url,
                    "post_id": entry.get("post_id", ""),
                    "type": media_type(target),
                    "size": target.stat().st_size,
                    "saved_at": time.time(),
                    "uploaded_at": entry.get("uploaded_at"),
                }
            )
        except Exception as exc:
            self.failed.emit(str(exc))


class MissingInfoRepairWorker(QThread):
    """Fetches tags, tag categories and upload dates for saved files missing any
    of them - including files whose metadata was lost entirely, which are
    identified from their file name. Realbooru items go through their own
    single-lane pool (that site throttles hard) so they never hold up the rest."""

    progress = Signal(int, int, int)
    info_found = Signal(str, str, object)
    nothing_to_do = Signal(str, str)
    item_failed = Signal(str, str, bool)          # folder, name, permanent
    finished_repair = Signal(int, int, int, int)

    def __init__(self, items: list[tuple[str, str, str, str, tuple]]):
        super().__init__()
        self.items = items

    def run(self):
        total = len(self.items)
        if not total:
            self.finished_repair.emit(0, 0, 0, 0)
            return
        done = fixed = settled = failed = 0

        def process(item):
            _folder_key, _name, site_label, source_url, _needs = item
            try:
                info = fetch_saved_post_info(site_label, source_url)
            except Exception as exc:
                return ("gone" if repair_failure_is_permanent(exc) else "failed"), None
            if info.get("tags") or info.get("uploaded_at"):
                return "fixed", info
            return "settled", None

        slow_pool = concurrent.futures.ThreadPoolExecutor(max_workers=1)
        fast_pool = concurrent.futures.ThreadPoolExecutor(max_workers=4)
        try:
            futures = {}
            for item in self.items:
                pool = slow_pool if entry_is_realbooru({"site": item[2]}) or "realbooru" in item[3] else fast_pool
                futures[pool.submit(process, item)] = item
            for future in concurrent.futures.as_completed(futures):
                if self.isInterruptionRequested():
                    break
                folder_key, name, _site, _url, _needs = futures[future]
                outcome, info = future.result()
                done += 1
                if outcome == "fixed":
                    fixed += 1
                    self.info_found.emit(folder_key, name, info)
                elif outcome == "settled":
                    settled += 1
                    self.nothing_to_do.emit(folder_key, name)
                else:
                    failed += 1
                    self.item_failed.emit(folder_key, name, outcome == "gone")
                if done % 5 == 0 or done == total:
                    self.progress.emit(done, total, fixed)
        finally:
            slow_pool.shutdown(wait=False, cancel_futures=True)
            fast_pool.shutdown(wait=False, cancel_futures=True)
        self.finished_repair.emit(fixed, settled, failed, done)


def fetch_post_tags_and_categories(source_url: str) -> tuple[list[str], dict[str, str]]:
    """Re-scrape one already-saved post's own page for its canonical tag names and
    their categories.

    Used by SavedTagRepairWorker to fix files saved before v0.86, when Realbooru
    posts got their tags from the search listing's display text (which shatters
    multi-word tags) and got no categories at all because its post pages carry the
    category on the tag anchor rather than a list wrapper - see
    extract_tag_categories_from_html. Retries a few times with backoff because
    these sites 503 constantly under any sustained load."""
    source_url = unescape(str(source_url or ""))
    if not source_url:
        return [], {}
    site_label = ""
    for label in _SITE_LABEL_BASE_URLS:
        if label and label in source_url.lower():
            site_label = label
            break
    lock = _UPLOAD_DATE_SITE_LOCKS.get(site_label, _UPLOAD_DATE_DEFAULT_SEMAPHORE)
    with lock:
        html_text = ""
        last_error = None
        for attempt in range(3):
            try:
                html_text = fetch_url_bytes(source_url, timeout=16, referer=source_url).decode(
                    "utf-8", errors="replace"
                )
                if looks_like_soft_error_page(html_text):
                    # 200 OK but not the real page - retry rather than scraping it.
                    html_text = ""
                    raise SoftErrorPage(source_url)
                break
            except Exception as exc:
                last_error = exc
                if repair_failure_is_permanent(exc):
                    # Deleted post - no amount of retrying brings it back.
                    break
                if attempt < 2:
                    time.sleep(1.0 * (attempt + 1))
        if not html_text:
            # Raise rather than returning empty: the caller has to be able to tell
            # "the page loaded and genuinely had no tags" (settled, remember it) from
            # "we never got the page" (retry it next run).
            raise last_error or RuntimeError("Could not fetch the post page")
    categories = extract_tag_categories_from_html(html_text)
    return list(categories.keys()), categories


class SavedTagRepairWorker(QThread):
    """Re-fetches canonical tags/categories for already-saved posts whose stored
    metadata predates the v0.86 tag fixes. One request per file, heavily throttled
    (the per-site semaphore above), interruptible, and resumable - it only ever
    looks at files that still have no categories, so stopping and restarting picks
    up where it left off rather than redoing work."""

    progress = Signal(int, int, int)
    tags_found = Signal(str, str, list, dict)
    nothing_to_do = Signal(str, str)
    finished_repair = Signal(int, int, int, int)

    def __init__(self, items: list[tuple[str, str, str]]):
        super().__init__()
        self.items = items

    def run(self):
        total = len(self.items)
        if not total:
            self.finished_repair.emit(0, 0, 0, 0)
            return
        done = 0
        repaired = 0
        settled = 0
        failed = 0

        def process(item):
            _folder_key, _filename, source_url = item
            try:
                tags, categories = fetch_post_tags_and_categories(source_url)
            except Exception as exc:
                # "settled" only for something that will never succeed (deleted post).
                return ("settled" if repair_failure_is_permanent(exc) else "failed"), [], {}
            if tags and categories:
                return "fixed", tags, categories
            # The page loaded fine and simply had nothing to scrape - re-fetching it
            # next run would get the same nothing, so stop asking.
            return "settled", [], {}

        # Deliberately small: the whole point is not to get rate-limited into
        # failure across a 10k-file run. The per-site semaphore already serialises
        # Realbooru, so more threads here would only queue up on it anyway.
        executor = concurrent.futures.ThreadPoolExecutor(max_workers=3)
        try:
            futures = {executor.submit(process, item): item for item in self.items}
            for future in concurrent.futures.as_completed(futures):
                if self.isInterruptionRequested():
                    executor.shutdown(wait=False, cancel_futures=True)
                    break
                folder_key, filename, _source_url = futures[future]
                outcome, tags, categories = future.result()
                done += 1
                if outcome == "fixed":
                    repaired += 1
                    self.tags_found.emit(folder_key, filename, tags, categories)
                elif outcome == "settled":
                    settled += 1
                    self.nothing_to_do.emit(folder_key, filename)
                else:
                    failed += 1
                if done % 5 == 0 or done == total:
                    self.progress.emit(done, total, repaired)
        finally:
            executor.shutdown(wait=False, cancel_futures=True)
        self.finished_repair.emit(repaired, settled, failed, done)


class SavedThumbnailRepairWorker(QThread):
    """Rebuilds thumbnails for already-saved videos.

    Video thumbnails cached before v0.86 can be the generic Windows "unknown file"
    icon rather than a real frame (see the SIIGBF_THUMBNAILONLY fix) - and because a
    cached thumbnail file exists and is perfectly valid JPEG, nothing in the normal
    thumbnail path will ever notice or replace it. This deletes and regenerates them.
    Local decode only, no network, so it is far quicker than the tag repair; the cv2
    decode itself is still serialised app-wide by CV2_VIDEO_DECODE_LOCK."""

    progress = Signal(int, int, int)
    thumb_repaired = Signal(str, str, str)
    nothing_to_do = Signal(str, str)
    finished_repair = Signal(int, int, int, int)

    def __init__(self, items: list[tuple[str, str, str, str, str]]):
        super().__init__()
        self.items = items

    def run(self):
        total = len(self.items)
        if not total:
            self.finished_repair.emit(0, 0, 0, 0)
            return
        done = 0
        repaired = 0
        settled = 0
        failed = 0

        def process(item):
            _folder_key, _filename, path_text, thumb_text, kind = item
            source = Path(path_text)
            destination = Path(thumb_text)
            if not source.is_file():
                # The video is gone (moved/deleted). Nothing to retry, ever.
                return "settled"
            try:
                # The stale icon lives in this exact file - it has to go first, or
                # create_thumbnail would just overwrite it with the same bytes if the
                # regeneration failed halfway.
                try:
                    if destination.exists():
                        destination.unlink()
                except OSError:
                    pass
                create_thumbnail(source, destination, kind)
                return "fixed" if destination.is_file() else "failed"
            except Exception:
                return "failed"

        executor = local_thread_pool(DISK_WORKER_CEILING, pending=total)
        try:
            futures = {executor.submit(process, item): item for item in self.items}
            for future in concurrent.futures.as_completed(futures):
                if self.isInterruptionRequested():
                    executor.shutdown(wait=False, cancel_futures=True)
                    break
                folder_key, filename, path_text, _thumb_text, _kind = futures[future]
                outcome = future.result()
                done += 1
                if outcome == "fixed":
                    repaired += 1
                    self.thumb_repaired.emit(folder_key, filename, path_text)
                elif outcome == "settled":
                    settled += 1
                    self.nothing_to_do.emit(folder_key, filename)
                else:
                    failed += 1
                if done % 5 == 0 or done == total:
                    self.progress.emit(done, total, repaired)
        finally:
            executor.shutdown(wait=False, cancel_futures=True)
        self.finished_repair.emit(repaired, settled, failed, done)


class BulkSearchFetchWorker(QThread):
    """Pages through every result of the current Explore search - not just the
    page that's currently loaded in the gallery - so "Save All From Search"
    can queue every match. Reuses ExploreWorker's per-site fetch methods one
    page at a time instead of running them as separate threads."""

    progress = Signal(int, int)
    entries_ready = Signal(object)
    finished_bulk = Signal(int)
    failed = Signal(str)

    def __init__(self, site_key: str, tags: str, page_size: int, total_count: int):
        super().__init__()
        self.site_key = site_key
        self.tags = tags
        self.page_size = max(1, page_size)
        self.total_count = max(0, total_count)

    def run(self):
        try:
            sites = ["gelbooru", "e621", "realbooru", "rule34xxx"] if self.site_key == "all" else [self.site_key]
            seen_keys: set[str] = set()
            fetched = 0
            page = 1
            empty_pages = 0
            while True:
                if self.isInterruptionRequested():
                    return
                fetch_worker = ExploreWorker(self.site_key, self.tags, page, self.page_size)
                page_entries = []
                for site in sites:
                    if self.isInterruptionRequested():
                        return
                    try:
                        page_entries.extend(fetch_worker.fetch_site(site))
                    except Exception:
                        try:
                            page_entries.extend(fetch_worker.fetch_site_html(site))
                        except Exception:
                            pass
                new_entries = []
                for entry in page_entries:
                    key = entry.get("source_url") or entry.get("media_url") or entry.get("path")
                    if not key or key in seen_keys:
                        continue
                    seen_keys.add(key)
                    new_entries.append(entry)
                if new_entries:
                    empty_pages = 0
                    fetched += len(new_entries)
                    self.entries_ready.emit(new_entries)
                    self.progress.emit(fetched, self.total_count)
                else:
                    empty_pages += 1
                if self.total_count and fetched >= self.total_count:
                    break
                if not page_entries and empty_pages >= 2:
                    break
                if page > 5000:
                    break
                page += 1
            self.finished_bulk.emit(fetched)
        except Exception as exc:
            self.failed.emit(str(exc))


class VideoCacheWorker(QThread):
    progress = Signal(int, str)
    ready = Signal(str, str)
    failed = Signal(str)

    def __init__(self, entry: dict):
        super().__init__()
        self.entry = dict(entry)

    def run(self):
        try:
            entry = dict(self.entry)
            media_url = entry.get("stream_url") or entry.get("media_url") or entry.get("path")
            if entry.get("needs_resolve") or not media_url:
                resolver = RemoteMediaWorker(entry)
                resolver.resolve_full_media(entry)
                media_url = entry.get("media_url") or entry.get("path")
            media_url, target = cached_video_path_for_entry(entry, media_url, entry.get("source_url"), self.progress.emit)
            self.ready.emit(media_url, str(target))
        except Exception as exc:
            write_app_log(
                f"video cache worker failed site={self.entry.get('site')} post={self.entry.get('post_id')} "
                f"error={type(exc).__name__}: {exc}"
            )
            self.failed.emit(str(exc))


class DetailImageScrollArea(QScrollArea):
    def __init__(self, dialog):
        super().__init__()
        self.dialog = dialog
        self._panning = False
        self._pan_start = QPoint()
        self._h_start = 0
        self._v_start = 0
        self.setWidgetResizable(False)
        self.setAlignment(Qt.AlignCenter)
        self.setFrameShape(QFrame.NoFrame)
        self.setObjectName("preview")

    def wheelEvent(self, event):
        factor = 1.25 if event.angleDelta().y() > 0 else 0.8
        self.dialog.zoom_at(event.position().toPoint(), factor)
        event.accept()

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton and not self.dialog.fit_to_frame:
            self._panning = True
            self._pan_start = event.position().toPoint()
            self._h_start = self.horizontalScrollBar().value()
            self._v_start = self.verticalScrollBar().value()
            self.setCursor(Qt.ClosedHandCursor)
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._panning:
            delta = event.position().toPoint() - self._pan_start
            self.horizontalScrollBar().setValue(self._h_start - delta.x())
            self.verticalScrollBar().setValue(self._v_start - delta.y())
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._panning and event.button() == Qt.LeftButton:
            self._panning = False
            self.setCursor(Qt.ArrowCursor)
            event.accept()
            return
        super().mouseReleaseEvent(event)


class SortingCounter(QObject):
    """The "del N + mov M = T" tally for sorting the Unfiltered library.

    One per app, shared by every pop-out, and kept - on disk too - until Reset
    is pressed, so closing a pop-out and opening the next one carries on
    counting. Each image counts once: stepping forward onto an image not seen
    yet counts as a move; deleting an image counts as a delete, and if that
    image had already been counted as a move (you went back to delete it) the
    move is taken back. Going back and forward over seen images, and the image
    that slides in after a delete, don't count."""

    changed = Signal()

    def __init__(self, file_path: Path | None = None, parent=None):
        super().__init__(parent)
        self.file_path = file_path
        self.deleted = 0
        self.moved = 0
        self.seen: set[str] = set()
        self.moved_paths: set[str] = set()
        self._save_timer = QTimer(self)
        self._save_timer.setSingleShot(True)
        self._save_timer.setInterval(2000)
        self._save_timer.timeout.connect(self.flush)
        self._dirty = False
        self._load()

    def _load(self):
        if self.file_path is None:
            return
        try:
            data = json.loads(self.file_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return
        if not isinstance(data, dict):
            return
        self.deleted = max(0, int(data.get("deleted") or 0))
        self.moved = max(0, int(data.get("moved") or 0))
        self.seen = {str(item) for item in data.get("seen") or []}
        self.moved_paths = {str(item) for item in data.get("moved_paths") or []}

    def flush(self):
        self._save_timer.stop()
        if not self._dirty or self.file_path is None:
            return
        self._dirty = False
        try:
            write_json_file(self.file_path, {
                "deleted": self.deleted,
                "moved": self.moved,
                "seen": sorted(self.seen),
                "moved_paths": sorted(self.moved_paths),
            })
        except OSError as exc:
            write_app_log(f"sorting counter save failed error={exc}")

    def _changed(self):
        self._dirty = True
        self._save_timer.start()
        self.changed.emit()

    def text(self) -> str:
        return f"del {self.deleted} + mov {self.moved} = {self.deleted + self.moved}"

    def note_seen(self, path: str):
        """The image is on screen without having been stepped onto (the one a
        pop-out opened on, or the one that slid in after a delete)."""
        if path and path not in self.seen:
            self.seen.add(path)
            self._dirty = True
            self._save_timer.start()

    def note_forward(self, path: str):
        if path and path not in self.seen:
            self.seen.add(path)
            self.moved_paths.add(path)
            self.moved += 1
            self._changed()

    def note_deleted(self, path: str):
        if path in self.moved_paths:
            self.moved_paths.discard(path)
            self.moved = max(0, self.moved - 1)
        self.deleted += 1
        self._changed()

    def reset(self):
        self.deleted = 0
        self.moved = 0
        self.seen.clear()
        self.moved_paths.clear()
        self._changed()


class ExploreMediaDialog(QDialog):
    def __init__(self, entry: dict, parent=None, entries: list[dict] | None = None, row: int = 0):
        # Deliberately parentless. A Qt.Window with a parent is still owned by that
        # parent: Windows gives it no taskbar button of its own, and Qt destroys it
        # when the parent goes - so closing the main window took every open pop-out
        # with it. With no parent this is a real top-level window that survives the
        # main window, appears in its own right on the taskbar, and shows up in the
        # app icon's hover preview alongside the others. `viewer` is kept as a plain
        # reference for the app services this dialog uses; ownership is not implied.
        super().__init__(
            None,
            Qt.Window | Qt.WindowMinimizeButtonHint | Qt.WindowMaximizeButtonHint | Qt.WindowCloseButtonHint,
        )
        # Nothing owns this window now, so it must free itself when closed. The
        # viewer's explore_windows list holds the only strong reference and drops it
        # on the destroyed signal.
        self.setAttribute(Qt.WA_DeleteOnClose, True)
        self.viewer = parent
        self.entries = list(entries or [entry])
        self.entry_index = max(0, min(row, len(self.entries) - 1))
        self.entry = dict(entry)
        self.worker: RemoteMediaWorker | None = None
        self.video_cache_worker: VideoCacheWorker | None = None
        self.tag_count_worker: TagCountWorker | None = None
        self.tag_count_request_key = ""
        self.tag_counts: dict[str, int] = {}
        self.retired_workers: list[RemoteMediaWorker] = []
        self.current_pixmap = QPixmap()
        self.current_image_path = ""
        self.current_image_size = QSize()
        self.current_movie: QMovie | None = None
        self.current_movie_native_size = QSize()
        self.current_movie_data: QByteArray | None = None
        self.current_movie_buffer: QBuffer | None = None
        self.is_closing = False
        self.fit_to_frame = True
        self.fit_zoom_factor = 1.0
        self.zoom_factor = 1.0
        self.player = QMediaPlayer(self)
        self.audio_output = QAudioOutput(self)
        initial_volume = max(0, min(100, int(getattr(self.viewer, "video_volume", 75))))
        self.audio_output.setVolume(initial_volume / 100)
        self.player.setAudioOutput(self.audio_output)
        self.player.durationChanged.connect(self.on_video_duration_changed)
        self.player.positionChanged.connect(self.on_video_position_changed)
        self.player.mediaStatusChanged.connect(self.on_media_status_changed)
        self.player.errorOccurred.connect(self.on_video_error)
        self.video_slider_is_pressed = False
        self.video_stream_failed = False

        self.setWindowTitle(f"{APP_NAME} // Explore")
        icon_path = resource_path(ICON_FILE)
        if icon_path.exists():
            # A parentless window does not inherit one implicitly on every platform.
            self.setWindowIcon(QIcon(str(icon_path)))
        self.resize(1180, 820)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(14, 14, 14, 14)
        layout.setSpacing(10)

        self.title = QLabel(f"{self.entry.get('site', 'Explore')} // {self.entry.get('name', 'Online media')}")
        self.title.setObjectName("sectionTitle")
        self.title.setWordWrap(True)
        layout.addWidget(self.title)

        content = QHBoxLayout()
        content.setContentsMargins(0, 0, 0, 0)
        content.setSpacing(10)
        left_panel = QFrame()
        left_panel.setObjectName("galleryPanel")
        left_panel.setFixedWidth(270)
        left_layout = QVBoxLayout(left_panel)
        left_layout.setContentsMargins(10, 10, 10, 10)
        left_layout.setSpacing(8)

        self.resolution_label = QLabel("Resolving original file...")
        self.resolution_label.setObjectName("scanValue")
        self.resolution_label.setWordWrap(True)
        left_layout.addWidget(self.resolution_label)

        self.load_progress = DotProgressBar()
        self.load_progress.setRange(0, 100)
        self.load_progress.setValue(0)
        left_layout.addWidget(self.load_progress)

        self.position_label = QLabel("")
        self.position_label.setObjectName("muted")
        left_layout.addWidget(self.position_label)

        # Sorting counter for the Unfiltered library - see SortingCounter. It
        # belongs to the main window, so it carries on across pop-outs until
        # Reset is pressed.
        self.session_counting = self.opened_on_unfiltered()
        counter = getattr(self.viewer, "sorting_counter", None) if self.viewer else None
        self.sorting_counter = counter if counter is not None else SortingCounter(None, self)
