        self.image_scroll = DetailImageScrollArea(self)
        self.image_scroll.setWidget(self.image_label)
        self.video_widget = QVideoWidget()
        # Stop Qt erasing the widget to its background before the next frame arrives.
        # That erase is the black flash seen while zooming: resizing the widget
        # invalidates it, Qt paints the background, and only then does the video sink
        # put a frame up.
        self.video_widget.setAttribute(Qt.WA_OpaquePaintEvent, True)
        self.video_widget.setAttribute(Qt.WA_NoSystemBackground, True)
        self.player.setVideoOutput(self.video_widget)
        # Loop natively instead of reacting to EndOfMedia with a seek+play, which
