        self.media_cache: dict = {}
        self.icon_cache: "collections.OrderedDict" = collections.OrderedDict()
        self.entry_tag_cache: dict = {}
        self._cache_write_lock = threading.Lock()
        self._cache_write_running = False
        self._cache_write_pending = False
        self.cache_save_requested.connect(self._save_cache)
        # Memoized tag histogram behind the search suggestions - see
        # active_tag_counts() / invalidate_tag_histogram().
        self._tag_histogram_cache: tuple | None = None
        self._tag_histogram_generation = 0
        self.tag_histogram_worker: "TagHistogramWorker | None" = None
        # Live-update watch - see check_for_update().
        self.update_check_worker: "UpdateCheckWorker | None" = None
        self.available_update_version = ""
        self._update_last_signature: tuple | None = None
        self._update_checked_signature: tuple | None = None
        self.restarting_for_update = False
        self.retired_tag_histogram_workers: list = []
        self._entry_path_index: dict[str, list[dict]] = {}
        self._entry_path_index_token: tuple | None = None
        # Cached saved-mode sort order - see saved_sorted_entries().
        self._saved_sorted_entries: list[dict] = []
        self._saved_sorted_token: tuple | None = None
        self._saved_sort_generation = 0
        # Memoizes the two filesystem stats behind "does this saved file get a
        # full-quality thumbnail" - see full_quality_thumbnail_source() /
        # full_quality_thumbnail_cache_info() for why these are safe to cache.
        self.full_quality_source_cache: "collections.OrderedDict" = collections.OrderedDict()
        self.full_quality_cache_info_cache: "collections.OrderedDict" = collections.OrderedDict()
        # Lazily built path -> gallery rows index; see gallery_rows_for_path().
        self._gallery_path_rows: dict[str, list[int]] | None = None
