        # Coalescing for rapid selection changes - see select_media().
        self.media_load_timer = QTimer(self)
        self.media_load_timer.setSingleShot(True)
        self.media_load_timer.setInterval(int(MEDIA_LOAD_COALESCE_SECONDS * 1000))
