            QLabel#duplicateBarExtra { background: #211734; border: 1px solid #34294a; border-radius: 4px; color: #bfaaff; font-size: 12pt; font-weight: 700; }
            QListWidget#duplicateBarList::item { background: transparent; border: 0; padding: 0; margin: 0; }
            QListWidget#duplicateBarList::item:hover { background: transparent; }
