            QListWidget#tagSuggestions { background: #090912; border: 1px solid #34294a; border-radius: 3px; padding: 3px; }
            QListWidget#tagSuggestions::item { background: #101017; color: #f5f3f8; margin: 2px; border: 1px solid #211734; border-radius: 3px; padding: 4px 8px; }
