        frame = HudPanel("TAG SCAN")
        frame.setObjectName("galleryPanel")
        layout = QVBoxLayout(frame)
        layout.setContentsMargins(14, 14, 14, 14)
        layout.setSpacing(10)
        self.folder_label = QLabel("No folder selected")
        self.folder_label.setObjectName("muted")
        layout.addWidget(self.folder_label)

        self.search_tabs_widget = QWidget()
        self.search_tabs_layout = QHBoxLayout(self.search_tabs_widget)
        self.search_tabs_layout.setContentsMargins(0, 0, 0, 0)
        self.search_tabs_layout.setSpacing(6)
        self.search_tabs_widget.hide()
        layout.addWidget(self.search_tabs_widget)

        self.explore_controls = QWidget()
        explore_row = QHBoxLayout()
        self.explore_controls.setLayout(explore_row)
