        self.explore_next_page_button.clicked.connect(self.next_explore_page)
        self.explore_history_back_button = HoverButton("<")
        self.explore_history_back_button.setObjectName("flat")
        self.explore_history_back_button.setToolTip("Back to previous Explore search")
        self.explore_history_back_button.clicked.connect(self.go_back_explore_search)
        self.explore_history_forward_button = HoverButton(">")
        self.explore_history_forward_button.setObjectName("flat")
