        self.explore_search_button.clicked.connect(self.force_explore_search)
        explore_row.addWidget(self.explore_site_combo)
        explore_row.addWidget(self.explore_prev_page_button)
        explore_row.addWidget(self.explore_page_label)
        explore_row.addWidget(self.explore_next_page_button)
        explore_row.addWidget(self.explore_history_back_button)
        explore_row.addWidget(self.explore_history_forward_button)
        explore_row.addWidget(self.explore_popup_button)
        explore_row.addWidget(self.search_input, 1)
        explore_row.addWidget(self.filter_button)
        explore_row.addWidget(self.favorite_tags_button)
        explore_row.addWidget(self.explore_search_button)
        self.explore_only_controls = [
            self.explore_site_combo,
            self.explore_prev_page_button,
            self.explore_page_label,
            self.explore_next_page_button,
            self.explore_history_back_button,
            self.explore_history_forward_button,
            self.explore_popup_button,
            self.explore_search_button,
        ]
        self.explore_controls.hide()
        layout.addWidget(self.explore_controls)

        self.saved_controls = QWidget()
        saved_row = QHBoxLayout(self.saved_controls)
        saved_row.setContentsMargins(0, 0, 0, 0)
